│  2  │  3  │  3  │
└─────┴─────┴─────┘

结果：prev2=2, prev1=3 ✅

🎯 常见错误与避免技巧
❌ 错误1：更新顺序搞反
// ❌ 错误写法
int current = prev1 + prev2;
prev1 = current;    // 先更新prev1
prev2 = prev1;      // 再更新prev2（此时prev1已经变了！）

// ✅ 正确写法
int current = prev1 + prev2;
prev2 = prev1;      // 先保存prev1到prev2
prev1 = current;    // 再更新prev1
避免技巧：

🔄 “先保存历史，再更新现在”

❌ 错误2：忘记临时变量
// ❌ 错误写法（没有临时变量）
prev1 = prev1 + prev2;  // prev1变了
prev2 = prev1;          // 用的是新的prev1，错了！

// ✅ 正确写法（使用临时变量）
int current = prev1 + prev2;  // 先保存结果
prev2 = prev1;                // 再更新
prev1 = current;
避免技巧：

💾 “先算先存，避免覆盖”

❌ 错误3：变量含义混乱
// ❌ 混乱的命名
int a = b + c;
b = c;
c = a;

// ✅ 清晰的命名
int current = prev1 + prev2;
prev2 = prev1;
prev1 = current;
避免技巧：

📝 “语义化命名，一目了然”


🎯 快速记忆的5个小技巧
💡 技巧1：口诀记忆法
万能口诀：

🎵 “先算新值存起来，老二接棒老大位，老大接棒新值位”

int current = prev1 + prev2;  // 先算新值存起来
prev2 = prev1;                // 老二接棒老大位
prev1 = current;              // 老大接棒新值位
💡 技巧2：手势记忆法
用手指表示变量：

👆 食指 = prev2（最老）
🖕 中指 = prev1（较新）
👍 拇指 = current（最新）

手势动作：

👍 = 🖕 + 👆 （拇指 = 中指 + 食指）
👆 ← 🖕 （食指接收中指的值）
🖕 ← 👍 （中指接收拇指的值）

💡 技巧3：颜色记忆法
// 🔴 红色 = 最老的值（prev2）
// 🟡 黄色 = 较新的值（prev1）
// 🟢 绿色 = 最新的值（current）

int 🟢 = 🟡 + 🔴;  // 绿 = 黄 + 红
🔴 = 🟡;            // 红 ← 黄
🟡 = 🟢;            // 黄 ← 绿
💡 技巧4：数字位置法
把变量想象成数字位置：
// 位置：  [2] [1] [0]
// 含义：  老  新  最新
// 变量：prev2 prev1 current

// 更新就是所有数字向右移动一位
int current = prev1 + prev2;  // 计算位置[0]
prev2 = prev1;                // [2] ← [1]
prev1 = current;              // [1] ← [0]
💡 技巧5：模板记忆法
固定模板，直接套用：
// 🎯 DP空间优化万能模板
public int dpOptimized(int n) {
    if (n &lt;= 边界) return 边界值;

    int prev2 = 初始值1;
    int prev1 = 初始值2;

    for (int i = 起始; i &lt;= n; i++) {
        // 📸 第一步：拍快照
        int current = 状态转移方程(prev1, prev2);

        // 📝 第二步：更新状态（固定顺序）
        prev2 = prev1;    // 历史更新
        prev1 = current;  // 当前更新
    }

    return prev1;
}

🎯 实战练习：其他DP问题
📚 练习1：打家劫舍
public int rob(int[] nums) {
    if (nums.length == 1) return nums[0];

    // 使用&quot;角色&quot;思维
    int 爷爷 = nums[0];                    // 最远的房子
    int 爸爸 = Math.max(nums[0], nums[1]); // 较近的房子

    for (int i = 2; i &lt; nums.length; i++) {
        // 👶 儿子 = max(不偷当前, 偷当前+爷爷)
        int 儿子 = Math.max(爸爸, 爷爷 + nums[i]);

        // 🔄 三代传承
        爷爷 = 爸爸;   // 爸爸变爷爷
        爸爸 = 儿子;   // 儿子变爸爸
    }

    return 爸爸;
}
📚 练习2：斐波那契数列
public int fib(int n) {
    if (n &lt;= 1) return n;

    // 使用&quot;队列&quot;思维
    int 队尾 = 0;  // fib(0)
    int 队头 = 1;  // fib(1)

    for (int i = 2; i &lt;= n; i++) {
        // 🎫 新人入队
        int 新人 = 队头 + 队尾;

        // 🚶 队列前移
        队尾 = 队头;   // 队头变队尾
        队头 = 新人;   // 新人变队头
    }

    return 队头;
}

