public class Solution {
    /**
     * 问题描述和解题思路
     * 
     * 状态定义：dp[i] = ...
     * 状态转移：dp[i] = ...
     * 边界条件：dp[0] = ...
     * 
     * 时间复杂度：O(...)
     * 空间复杂度：O(...)
     */
    public int solve(int[] nums) {
        // 1. 输入验证
        if (nums == null || nums.length == 0) {
            return 0;
        }

        // 2. 特殊情况处理
        if (nums.length == 1) {
            return nums[0];
        }

        // 3. DP数组初始化
        int n = nums.length;
        int[] dp = new int[n];

        // 4. 边界条件设置
        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);

        // 5. 状态转移
        for (int i = 2; i &lt; n; i++) {
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
        }

        // 6. 返回结果
        return dp[n-1];
    }
}
