// 验证中间结果
for (int i = 0; i &lt; Math.min(5, dp.length); i++) {
    System.out.printf(&quot;dp[%d] = %d (expected: %d)\n&quot;, 
                     i, dp[i], expectedValues[i]);
}

// 断言检查
assert dp[0] == nums[0] : &quot;边界条件错误&quot;;
assert dp[1] == Math.max(nums[0], nums[1]) : &quot;边界条件错误&quot;;

❌ 常见错误总结
1. 状态定义不清晰
// ❌ 错误：状态定义模糊
// dp[i] = 第i个数的某个值

// ✅ 正确：状态定义明确
// dp[i] = 到第i个房子时能偷到的最大金额
2. 边界条件错误
// ❌ 错误：边界条件不符合实际
dp[0] = 0;  // 应该是nums[0]

// ✅ 正确：边界条件符合问题定义
dp[0] = nums[0];
dp[1] = Math.max(nums[0], nums[1]);
3. 状态转移方程错误
// ❌ 错误：没有考虑所有选择
dp[i] = dp[i-1] + nums[i];

// ✅ 正确：考虑所有可能的选择
dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
4. 数组越界
// ❌ 错误：没有检查数组边界
for (int i = 0; i &lt; n; i++) {
    dp[i] = dp[i-1] + dp[i-2];  // i=0,1时越界
}

// ✅ 正确：正确处理边界
for (int i = 2; i &lt; n; i++) {
    dp[i] = dp[i-1] + dp[i-2];
}
5. 忘记处理特殊情况
// ❌ 错误：没有处理空数组
public int solve(int[] nums) {
    int[] dp = new int[nums.length];  // nums可能为null
}

// ✅ 正确：完整的输入验证
public int solve(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    if (nums.length == 1) {
        return nums[0];
    }
    // 正常逻辑
}

