int fc(int[][] num) {
    // 边界条件处理
    if (null == num) return 0;
    if (nums.length == 1) return 1;
    if (nums[0].length == 1) return 1;

    // 初始化第一列
    for (i) {
        dp[i][0] = 1;
    }

    // 初始化第一行
    for (j) {
        dp[0][j] = 1;
    }

    // 填充DP表
    for (i = 1; i++; ) {
        for (j = 1; j++; ) {
            dp[i][j] = dp[i-1][j] + dp[i][j-1];
        }
    }

    return dp[dp.length-1][num[0].length-1];
}
