dp[0][2]: s[0]=&#039;b&#039;, s[2]=&#039;b&#039; → &#039;b&#039;=&#039;b&#039; → true (长度≤3)
dp[1][3]: s[1]=&#039;a&#039;, s[3]=&#039;a&#039; → &#039;a&#039;=&#039;a&#039; → true (长度≤3)
dp[2][4]: s[2]=&#039;b&#039;, s[4]=&#039;d&#039; → &#039;b&#039;≠&#039;d&#039; → false

