📈 最长递增子序列

*� 300-最长递增子序列

// O(n²) 解法
public int lengthOfLIS(int[] nums) {
    int n = nums.length;
    int[] dp = new int[n];
    Arrays.fill(dp, 1);

    int maxLen = 1;
    for (int i = 1; i &lt; n; i++) {
        for (int j = 0; j &lt; i; j++) {
            if (nums[j] &lt; nums[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        maxLen = Math.max(maxLen, dp[i]);
    }
    return maxLen;
}

// O(nlogn) 二分优化解法
public int lengthOfLISOptimized(int[] nums) {
    List&lt;Integer&gt; tails = new ArrayList&lt;&gt;();

    for (int num : nums) {
        int left = 0, right = tails.size();
        while (left &lt; right) {
            int mid = left + (right - left) / 2;
            if (tails.get(mid) &lt; num) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        if (left == tails.size()) {
            tails.add(num);
        } else {
            tails.set(left, num);
        }
    }
    return tails.size();
}
- **标签**: LIS、二分优化
