💻 代码实现
方法一：双栈实现（推荐）
import java.util.*;

class MyQueue {

    private Deque&lt;Integer&gt; inStack;   // 输入栈
    private Deque&lt;Integer&gt; outStack;  // 输出栈

    public MyQueue() {
        inStack = new ArrayDeque&lt;&gt;();
        outStack = new ArrayDeque&lt;&gt;();
    }

    /**
     * 将元素推入队列末尾
     */
    public void push(int x) {
        inStack.push(x);
    }

    /**
     * 从队列开头移除并返回元素
     */
    public int pop() {
        // 确保输出栈有元素
        transferIfNeeded();
        return outStack.pop();
    }

    /**
     * 返回队列开头的元素
     */
    public int peek() {
        // 确保输出栈有元素
        transferIfNeeded();
        return outStack.peek();
    }

    /**
     * 检查队列是否为空
     */
    public boolean empty() {
        return inStack.isEmpty() &amp;&amp; outStack.isEmpty();
    }

    /**
     * 如果输出栈为空，将输入栈的所有元素转移到输出栈
     */
    private void transferIfNeeded() {
        if (outStack.isEmpty()) {
            while (!inStack.isEmpty()) {
                outStack.push(inStack.pop());
            }
        }
    }
}
方法二：优化版本（延迟转移）
class MyQueueOptimized {

    private Deque&lt;Integer&gt; inStack;
    private Deque&lt;Integer&gt; outStack;
    private Integer front; // 缓存队列头元素

    public MyQueueOptimized() {
        inStack = new ArrayDeque&lt;&gt;();
        outStack = new ArrayDeque&lt;&gt;();
        front = null;
    }

    public void push(int x) {
        // 如果是第一个元素，记录为队列头
        if (inStack.isEmpty()) {
            front = x;
        }
        inStack.push(x);
    }

    public int pop() {
        if (outStack.isEmpty()) {
            // 转移所有元素到输出栈
            while (!inStack.isEmpty()) {
                outStack.push(inStack.pop());
            }
        }

        int result = outStack.pop();

        // 更新front缓存
        if (outStack.isEmpty() &amp;&amp; !inStack.isEmpty()) {
            front = inStack.peek();
        }

        return result;
    }

    public int peek() {
        if (!outStack.isEmpty()) {
            return outStack.peek();
        }
        return front;
    }

    public boolean empty() {
        return inStack.isEmpty() &amp;&amp; outStack.isEmpty();
    }
}
方法三：单栈递归实现（理论参考）
class MyQueueRecursive {

    private Deque&lt;Integer&gt; stack;

    public MyQueueRecursive() {
        stack = new ArrayDeque&lt;&gt;();
    }

    public void push(int x) {
        stack.push(x);
    }

    public int pop() {
        if (stack.size() == 1) {
            return stack.pop();
        }

        // 递归取出栈底元素
        int top = stack.pop();
        int result = pop(); // 递归调用
        stack.push(top);    // 恢复栈结构
        return result;
    }

    public int peek() {
        if (stack.size() == 1) {
            return stack.peek();
        }

        int top = stack.pop();
        int result = peek(); // 递归调用
        stack.push(top);     // 恢复栈结构
        return result;
    }

    public boolean empty() {
        return stack.isEmpty();
    }
}
方法四：使用数组实现
class MyQueueArray {

    private int[] inStack;
    private int[] outStack;
    private int inTop;
    private int outTop;
    private static final int CAPACITY = 100;

    public MyQueueArray() {
        inStack = new int[CAPACITY];
        outStack = new int[CAPACITY];
        inTop = -1;
        outTop = -1;
    }

    public void push(int x) {
        inStack[++inTop] = x;
    }

    public int pop() {
        transferIfNeeded();
        return outStack[outTop--];
    }

    public int peek() {
        transferIfNeeded();
        return outStack[outTop];
    }

    public boolean empty() {
        return inTop == -1 &amp;&amp; outTop == -1;
    }

    private void transferIfNeeded() {
        if (outTop == -1) {
            while (inTop != -1) {
                outStack[++outTop] = inStack[inTop--];
            }
        }
    }
}
🔍 复杂度分析
时间复杂度
双栈实现：

push()：O(1)
pop()：均摊 O(1)，最坏情况 O(n)
peek()：均摊 O(1)，最坏情况 O(n)
empty()：O(1)

均摊分析：

每个元素最多被转移一次（从输入栈到输出栈）
n 个操作的总时间复杂度为 O(n)
因此均摊时间复杂度为 O(1)

单栈递归实现：

push()：O(1)
pop()：O(n)
peek()：O(n)
empty()：O(1)

空间复杂度
双栈实现：

O(n)，其中 n 是队列中元素的数量

单栈递归实现：

O(n)，递归调用栈的深度

