/**
 * 用队列实现栈（双栈问题的逆向）
 */
class MyStack {

    private Queue&lt;Integer&gt; queue1;
    private Queue&lt;Integer&gt; queue2;

    public MyStack() {
        queue1 = new LinkedList&lt;&gt;();
        queue2 = new LinkedList&lt;&gt;();
    }

    public void push(int x) {
        queue2.offer(x);

        // 将queue1的所有元素转移到queue2
        while (!queue1.isEmpty()) {
            queue2.offer(queue1.poll());
        }

        // 交换两个队列
        Queue&lt;Integer&gt; temp = queue1;
        queue1 = queue2;
        queue2 = temp;
    }

    public int pop() {
        return queue1.poll();
    }

    public int top() {
        return queue1.peek();
    }

    public boolean empty() {
        return queue1.isEmpty();
    }
}
2. 最小队列（扩展应用）
/**
 * 支持获取最小值的队列
 */
class MinQueue {

    private Deque&lt;Integer&gt; inStack;
    private Deque&lt;Integer&gt; outStack;
    private Deque&lt;Integer&gt; inMin;    // 输入栈的最小值栈
    private Deque&lt;Integer&gt; outMin;   // 输出栈的最小值栈

    public MinQueue() {
        inStack = new ArrayDeque&lt;&gt;();
        outStack = new ArrayDeque&lt;&gt;();
        inMin = new ArrayDeque&lt;&gt;();
        outMin = new ArrayDeque&lt;&gt;();
    }

    public void push(int x) {
        inStack.push(x);

        // 维护输入栈的最小值
        if (inMin.isEmpty() || x &lt;= inMin.peek()) {
            inMin.push(x);
        }
    }

    public int pop() {
        transferIfNeeded();

        int result = outStack.pop();

        // 维护输出栈的最小值
        if (!outMin.isEmpty() &amp;&amp; result == outMin.peek()) {
            outMin.pop();
        }

        return result;
    }

    public int peek() {
        transferIfNeeded();
        return outStack.peek();
    }

    public int getMin() {
        int min = Integer.MAX_VALUE;

        if (!inMin.isEmpty()) {
            min = Math.min(min, inMin.peek());
        }

        if (!outMin.isEmpty()) {
            min = Math.min(min, outMin.peek());
        }

        return min;
    }

    public boolean empty() {
        return inStack.isEmpty() &amp;&amp; outStack.isEmpty();
    }

    private void transferIfNeeded() {
        if (outStack.isEmpty()) {
            while (!inStack.isEmpty()) {
                int element = inStack.pop();
                outStack.push(element);

                // 维护输出栈的最小值
                if (outMin.isEmpty() || element &lt;= outMin.peek()) {
                    outMin.push(element);
                }

                // 维护输入栈的最小值
                if (!inMin.isEmpty() &amp;&amp; element == inMin.peek()) {
                    inMin.pop();
                }
            }
        }
    }
}
