3. 分工型双栈 - 表达式求值
核心思想： 一个栈存储操作数，另一个栈存储操作符
/**
 * 表达式求值的双栈实现
 */
public class ExpressionEvaluator {
    private Deque&lt;Integer&gt; operandStack;   // 操作数栈
    private Deque&lt;Character&gt; operatorStack; // 操作符栈

    public ExpressionEvaluator() {
        operandStack = new ArrayDeque&lt;&gt;();
        operatorStack = new ArrayDeque&lt;&gt;();
    }

    /**
     * 计算表达式
     */
    public int evaluate(String expression) {
        for (int i = 0; i &lt; expression.length(); i++) {
            char ch = expression.charAt(i);

            if (ch == &#039; &#039;) continue;  // 跳过空格

            // 处理数字
            if (Character.isDigit(ch)) {
                int num = 0;
                while (i &lt; expression.length() &amp;&amp; 
                       Character.isDigit(expression.charAt(i))) {
                    num = num * 10 + (expression.charAt(i) - &#039;0&#039;);
                    i++;
                }
                i--; // 回退一位
                operandStack.push(num);
            }
            // 处理左括号
            else if (ch == &#039;(&#039;) {
                operatorStack.push(ch);
            }
            // 处理右括号
            else if (ch == &#039;)&#039;) {
                while (!operatorStack.isEmpty() &amp;&amp; 
                       operatorStack.peek() != &#039;(&#039;) {
                    processOperation();
                }
                operatorStack.pop(); // 弹出左括号
            }
            // 处理操作符
            else if (isOperator(ch)) {
                while (!operatorStack.isEmpty() &amp;&amp; 
                       precedence(operatorStack.peek()) &gt;= precedence(ch)) {
                    processOperation();
                }
                operatorStack.push(ch);
            }
        }

        // 处理剩余操作符
        while (!operatorStack.isEmpty()) {
            processOperation();
        }

        return operandStack.pop();
    }

    /**
     * 执行一次运算
     */
    private void processOperation() {
        if (operandStack.size() &lt; 2 || operatorStack.isEmpty()) {
            throw new RuntimeException(&quot;表达式错误&quot;);
        }

        int b = operandStack.pop();
        int a = operandStack.pop();
        char op = operatorStack.pop();

        int result = calculate(a, b, op);
        operandStack.push(result);
    }

    /**
     * 计算两个数的运算结果
     */
    private int calculate(int a, int b, char op) {
        switch (op) {
            case &#039;+&#039;: return a + b;
            case &#039;-&#039;: return a - b;
            case &#039;*&#039;: return a * b;
            case &#039;/&#039;: return a / b;
            default: throw new RuntimeException(&quot;未知操作符: &quot; + op);
        }
    }

    /**
     * 判断是否为操作符
     */
    private boolean isOperator(char ch) {
        return ch == &#039;+&#039; || ch == &#039;-&#039; || ch == &#039;*&#039; || ch == &#039;/&#039;;
    }

    /**
     * 获取操作符优先级
     */
    private int precedence(char op) {
        switch (op) {
            case &#039;+&#039;:
            case &#039;-&#039;:
                return 1;
            case &#039;*&#039;:
            case &#039;/&#039;:
                return 2;
            default:
                return 0;
        }
    }
}
