1. 浏览器前进后退功能
/**
 * 浏览器历史记录管理
 */
public class BrowserHistory {
    private Deque&lt;String&gt; backStack;     // 后退栈
    private Deque&lt;String&gt; forwardStack;  // 前进栈
    private String currentPage;

    public BrowserHistory(String homepage) {
        backStack = new ArrayDeque&lt;&gt;();
        forwardStack = new ArrayDeque&lt;&gt;();
        currentPage = homepage;
    }

    /**
     * 访问新页面
     */
    public void visit(String url) {
        if (currentPage != null) {
            backStack.push(currentPage);
        }
        currentPage = url;
        forwardStack.clear(); // 清空前进历史
    }

    /**
     * 后退
     */
    public String back(int steps) {
        for (int i = 0; i &lt; steps &amp;&amp; !backStack.isEmpty(); i++) {
            forwardStack.push(currentPage);
            currentPage = backStack.pop();
        }
        return currentPage;
    }

    /**
     * 前进
     */
    public String forward(int steps) {
        for (int i = 0; i &lt; steps &amp;&amp; !forwardStack.isEmpty(); i++) {
            backStack.push(currentPage);
            currentPage = forwardStack.pop();
        }
        return currentPage;
    }
}
2. 撤销重做功能
/**
 * 文本编辑器的撤销重做功能
 */
public class TextEditor {
    private StringBuilder content;
    private Deque&lt;String&gt; undoStack;   // 撤销栈
    private Deque&lt;String&gt; redoStack;   // 重做栈

    public TextEditor() {
        content = new StringBuilder();
        undoStack = new ArrayDeque&lt;&gt;();
        redoStack = new ArrayDeque&lt;&gt;();
    }

    /**
     * 执行操作
     */
    public void execute(String operation) {
        // 保存当前状态到撤销栈
        undoStack.push(content.toString());

        // 执行操作
        applyOperation(operation);

        // 清空重做栈
        redoStack.clear();
    }

    /**
     * 撤销操作
     */
    public void undo() {
        if (!undoStack.isEmpty()) {
            redoStack.push(content.toString());
            content = new StringBuilder(undoStack.pop());
        }
    }

    /**
     * 重做操作
     */
    public void redo() {
        if (!redoStack.isEmpty()) {
            undoStack.push(content.toString());
            content = new StringBuilder(redoStack.pop());
        }
    }

    private void applyOperation(String operation) {
        // 简化的操作应用逻辑
        content.append(operation);
    }
}
3. 最小栈实现
/**
 * 支持获取最小值的栈
 */
public class MinStack {
    private Deque&lt;Integer&gt; dataStack;  // 数据栈
    private Deque&lt;Integer&gt; minStack;   // 最小值栈

    public MinStack() {
        dataStack = new ArrayDeque&lt;&gt;();
        minStack = new ArrayDeque&lt;&gt;();
    }

    /**
     * 入栈
     */
    public void push(int val) {
        dataStack.push(val);

        // 维护最小值栈
        if (minStack.isEmpty() || val &lt;= minStack.peek()) {
            minStack.push(val);
        }
    }

    /**
     * 出栈
     */
    public void pop() {
        if (dataStack.isEmpty()) return;

        int val = dataStack.pop();

        // 如果弹出的是最小值，同时弹出最小值栈
        if (!minStack.isEmpty() &amp;&amp; val == minStack.peek()) {
            minStack.pop();
        }
    }

    /**
     * 获取栈顶元素
     */
    public int top() {
        return dataStack.peek();
    }

    /**
     * 获取最小值
     */
    public int getMin() {
        return minStack.peek();
    }
}
