├──────────────────────────────────────────────────────────┤
│ &#039;3&#039;  │ 累积数字     │ 3   │ &quot;&quot;         │ []       │ []       │
│ &#039;[&#039;  │ 保存状态     │ 0   │ &quot;&quot;         │ [3]      │ [&quot;&quot;]     │
│ &#039;a&#039;  │ 拼接字符     │ 0   │ &quot;a&quot;        │ [3]      │ [&quot;&quot;]     │
│ &#039;]&#039;  │ 计算结果     │ 0   │ &quot;aaa&quot;      │ []       │ []       │
