│ &#039;c&#039;  │ 拼接字符     │ 0   │ &quot;c&quot;        │ [3,2]    │ [&quot;&quot;,&quot;a&quot;] │
│ &#039;]&#039;  │ 计算结果     │ 0   │ &quot;acc&quot;      │ [3]      │ [&quot;&quot;]     │
