小测清单（强烈建议逐个跑）

基础：&quot;a&quot; → &quot;a&quot;；&quot;aa&quot; → &quot;aa&quot;；&quot;ab&quot; → &quot;a&quot; 或 &quot;b&quot;。
典型奇中心：&quot;babad&quot; → &quot;bab&quot; 或 &quot;aba&quot;；&quot;racecar&quot; → 整串。
典型偶中心：&quot;abba&quot; → 整串；&quot;cbbd&quot; → &quot;bb&quot;。
边界：空串 &quot;&quot;；全部相同 &quot;aaaaa&quot;；全部不同 &quot;abcdef&quot;。

Python 对照版（逐行注释）
class Solution:
    def longestPalindrome(self, s: str) -&gt; str:
        # 空串或长度为 1，直接返回自身
        if s is None or len(s) &lt; 2:
            return s

        start = 0      # 最优子串起点
        max_len = 1    # 最优子串长度

        # 遍历每一个中心位置 i
        for i in range(len(s)):
            # 奇中心：以 i 为中心扩展
            len1 = self.expand(s, i, i)
            # 偶中心：以 i 和 i+1 为中心扩展
            len2 = self.expand(s, i, i + 1)
            curr = max(len1, len2)

            if curr &gt; max_len:
                max_len = curr
                # 统一公式：奇偶都适用；Python 用整数整除 //
                start = i - (curr - 1) // 2

        # 截取并返回答案
        return s[start:start + max_len]

    def expand(self, s: str, l: int, r: int) -&gt; int:
        # 从中心 (l, r) 向两侧扩展，只要左右字符相等就继续
        while l &gt;= 0 and r &lt; len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        # 退出时有效回文区间是 (l+1, r-1)，长度为 r - l - 1
        return r - l - 1
