public class TopKFinder&lt;T extends Comparable&lt;T&gt;&gt; {
    public T findKthLargest(T[] array, int k) {
        PriorityQueue&lt;T&gt; heap = new PriorityQueue&lt;&gt;();

        for (T element : array) {
            if (heap.size() &lt; k) {
                heap.offer(element);
            } else if (element.compareTo(heap.peek()) &gt; 0) {
                heap.poll();
                heap.offer(element);
            }
        }

        return heap.peek();
    }
}

