归并排序详解-稳定高效的分治算法
归并排序详解：稳定高效的分治算法
📚 什么是归并排序
归并排序（Merge Sort）是一种基于分治思想的稳定排序算法，由约翰·冯·诺伊曼在1945年发明。它的核心思想是”分而治之”：将大问题分解为小问题，解决小问题后再合并结果。
核心思想

分解（Divide）：将数组从中间分成两个子数组
解决（Conquer）：递归地对两个子数组进行归并排序
合并（Combine）：将两个已排序的子数组合并成一个有序数组

算法特点

时间复杂度：始终 O(n log n)（最好、平均、最坏都相同）
空间复杂度：O(n)（需要额外数组空间）
稳定性：稳定排序
原地排序：否（需要额外空间）
分治算法：典型的分治算法实现


🎯 何时使用归并排序
适用场景

需要稳定排序：保持相等元素的相对位置不变
要求时间复杂度稳定：无论什么数据都保证 O(n log n)
大数据量排序：对于大型数据集表现优秀
外部排序：处理无法完全加载到内存的大文件
链表排序：归并排序特别适合链表结构
并行计算：容易并行化实现

优势特点
// 示例：需要稳定排序的场景
class Student {
    String name;
    int score;
    int id;  // 学号
}

// 按分数排序，分数相同时保持学号顺序
// 归并排序能保证稳定性
Student[] students = {
    new Student(&quot;Alice&quot;, 85, 1001),
    new Student(&quot;Bob&quot;, 90, 1002),
    new Student(&quot;Charlie&quot;, 85, 1003)  // 与Alice分数相同
};
// 排序后Charlie仍在Alice后面
不适用场景

内存受限：需要额外的 O(n) 空间
小数据量：对于小数组，插入排序可能更快
原地排序需求：如果必须原地排序，选择快速排序或堆排序


💻 归并排序通用代码模板
基础递归版本
public class MergeSort {
    public void mergeSort(int[] arr) {
        if (arr == null || arr.length &lt;= 1) {
            return;
        }

        int[] temp = new int[arr.length];
        mergeSort(arr, temp, 0, arr.length - 1);
    }

    private void mergeSort(int[] arr, int[] temp, int left, int right) {
        if (left &gt;= right) {
            return;
        }

        // 分解：找到中点
        int mid = left + (right - left) / 2;

        // 递归排序左半部分
        mergeSort(arr, temp, left, mid);
        // 递归排序右半部分
        mergeSort(arr, temp, mid + 1, right);

        // 合并两个已排序的部分
        merge(arr, temp, left, mid, right);
    }

    private void merge(int[] arr, int[] temp, int left, int mid, int right) {
        // 复制到临时数组
        for (int i = left; i &lt;= right; i++) {
            temp[i] = arr[i];
        }

        int i = left;      // 左半部分的指针
        int j = mid + 1;   // 右半部分的指针
        int k = left;      // 合并后数组的指针

        // 合并两个有序数组
        while (i &lt;= mid &amp;&amp; j &lt;= right) {
            if (temp[i] &lt;= temp[j]) {
                arr[k++] = temp[i++];
            } else {
                arr[k++] = temp[j++];
            }
        }

        // 复制剩余元素
        while (i &lt;= mid) {
            arr[k++] = temp[i++];
        }
        while (j &lt;= right) {
            arr[k++] = temp[j++];
        }
    }
}
优化版本（减少数组复制）
public class MergeSortOptimized {
    public void mergeSort(int[] arr) {
        if (arr == null || arr.length &lt;= 1) {
            return;
        }

        int[] aux = arr.clone();  // 辅助数组
        mergeSort(aux, arr, 0, arr.length - 1);
    }

    private void mergeSort(int[] src, int[] dst, int left, int right) {
        if (left &gt;= right) {
            return;
        }

        int mid = left + (right - left) / 2;

        // 注意：递归时交换src和dst
        mergeSort(dst, src, left, mid);
        mergeSort(dst, src, mid + 1, right);

        merge(src, dst, left, mid, right);
    }

    private void merge(int[] src, int[] dst, int left, int mid, int right) {
        int i = left, j = mid + 1;

        for (int k = left; k &lt;= right; k++) {
            if (i &gt; mid) {
                dst[k] = src[j++];
            } else if (j &gt; right) {
                dst[k] = src[i++];
            } else if (src[i] &lt;= src[j]) {
                dst[k] = src[i++];
            } else {
                dst[k] = src[j++];
            }
        }
    }
}
迭代版本（自底向上）
public class MergeSortIterative {
    public void mergeSort(int[] arr) {
        int n = arr.length;
        int[] temp = new int[n];

        // 子数组大小从1开始，每次翻倍
        for (int size = 1; size &lt; n; size *= 2) {
            // 合并相邻的子数组
            for (int left = 0; left &lt; n - size; left += 2 * size) {
                int mid = left + size - 1;
                int right = Math.min(left + 2 * size - 1, n - 1);
                merge(arr, temp, left, mid, right);
            }
        }
    }

    // merge方法同上
}

🌟 简单例题：数组排序
题目
给定一个整数数组 [38, 27, 43, 3, 9, 82, 10]，使用归并排序将其升序排列。
完整解答
public class MergeSortExample {
    public static void main(String[] args) {
        int[] arr = {38, 27, 43, 3, 9, 82, 10};
        System.out.println(&quot;排序前: &quot; + Arrays.toString(arr));

        mergeSort(arr);

        System.out.println(&quot;排序后: &quot; + Arrays.toString(arr));
    }

    public static void mergeSort(int[] arr) {
        if (arr.length &lt;= 1) return;

        int[] temp = new int[arr.length];
        mergeSort(arr, temp, 0, arr.length - 1);
    }

    private static void mergeSort(int[] arr, int[] temp, int left, int right) {
        if (left &gt;= right) return;

        int mid = left + (right - left) / 2;

        System.out.printf(&quot;分解: [%d, %d] -&gt; [%d, %d] 和 [%d, %d]\n&quot;, 
                         left, right, left, mid, mid + 1, right);

        mergeSort(arr, temp, left, mid);
        mergeSort(arr, temp, mid + 1, right);

        merge(arr, temp, left, mid, right);

        System.out.printf(&quot;合并: [%d, %d] 结果: &quot;, left, right);
        for (int i = left; i &lt;= right; i++) {
            System.out.print(arr[i] + &quot; &quot;);
        }
        System.out.println();
    }

    private static void merge(int[] arr, int[] temp, int left, int mid, int right) {
        // 复制到临时数组
        for (int i = left; i &lt;= right; i++) {
            temp[i] = arr[i];
        }

        int i = left, j = mid + 1, k = left;

        while (i &lt;= mid &amp;&amp; j &lt;= right) {
            if (temp[i] &lt;= temp[j]) {
                arr[k++] = temp[i++];
            } else {
                arr[k++] = temp[j++];
            }
        }

        while (i &lt;= mid) arr[k++] = temp[i++];
        while (j &lt;= right) arr[k++] = temp[j++];
    }
}
