💡 核心思想在代码中的体现
1. 分治思想的体现
// 分治的三个步骤在代码中的体现
public void quickSort(int[] arr, int low, int high) {
    if (low &lt; high) {
        // 【分解】：将数组分成两部分
        int pivotIndex = partition(arr, low, high);

        // 【解决】：递归解决子问题
        quickSort(arr, low, pivotIndex - 1);     // 解决左子问题
        quickSort(arr, pivotIndex + 1, high);    // 解决右子问题

        // 【合并】：不需要显式合并，因为是原地排序
        // 当左右子数组都排好序后，整个数组自然就排好序了
    }
}
2. 基准选择策略的体现
// 简单策略：选择最后一个元素
int pivot = arr[high];

// 优化策略：三数取中
public int medianOfThree(int[] arr, int low, int high) {
    int mid = low + (high - low) / 2;

    if (arr[mid] &lt; arr[low]) {
        swap(arr, low, mid);
    }
    if (arr[high] &lt; arr[low]) {
        swap(arr, low, high);
    }
    if (arr[high] &lt; arr[mid]) {
        swap(arr, mid, high);
    }

    return arr[high];  // 现在 arr[high] 是中位数
}
3. 原地排序的体现
// 快速排序不需要额外的数组空间
// 所有操作都在原数组上进行
public int partition(int[] arr, int low, int high) {
    // 只使用几个变量，空间复杂度 O(1)
    int pivot = arr[high];
    int i = low - 1;

    // 通过交换操作重新排列元素
    for (int j = low; j &lt; high; j++) {
        if (arr[j] &lt;= pivot) {
            i++;
            swap(arr, i, j);  // 原地交换
        }
    }

    swap(arr, i + 1, high);
    return i + 1;
}

