public class QuickSortDemo {
    public static void main(String[] args) {
        int[] arr = {4, 2, 7, 1, 3};
        System.out.println(&quot;排序前: &quot; + Arrays.toString(arr));

        quickSort(arr, 0, arr.length - 1);

        System.out.println(&quot;排序后: &quot; + Arrays.toString(arr));
    }

    public static void quickSort(int[] arr, int low, int high) {
        System.out.printf(&quot;quickSort(%s, %d, %d)\n&quot;, 
                         Arrays.toString(arr), low, high);

        if (low &lt; high) {
            int pivotIndex = partition(arr, low, high);
            System.out.printf(&quot;分区后: %s, 基准位置: %d\n&quot;, 
                             Arrays.toString(arr), pivotIndex);

            quickSort(arr, low, pivotIndex - 1);
            quickSort(arr, pivotIndex + 1, high);
        }
    }

    public static int partition(int[] arr, int low, int high) {
        int pivot = arr[high];
        System.out.printf(&quot;分区操作: 基准=%d\n&quot;, pivot);

        int i = low - 1;

        for (int j = low; j &lt; high; j++) {
            if (arr[j] &lt;= pivot) {
                i++;
                swap(arr, i, j);
                System.out.printf(&quot;  交换后: %s\n&quot;, Arrays.toString(arr));
            }
        }

        swap(arr, i + 1, high);
        System.out.printf(&quot;  基准归位: %s\n&quot;, Arrays.toString(arr));

        return i + 1;
    }

    public static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
