🔄 插入排序的变种
1. 希尔排序（Shell Sort）
// 插入排序的改进版本，使用间隔序列
public void shellSort(int[] arr) {
    int n = arr.length;

    // 从大间隔开始，逐渐减小间隔
    for (int gap = n / 2; gap &gt; 0; gap /= 2) {
        // 对每个间隔进行插入排序
        for (int i = gap; i &lt; n; i++) {
            int key = arr[i];
            int j = i;

            while (j &gt;= gap &amp;&amp; arr[j - gap] &gt; key) {
                arr[j] = arr[j - gap];
                j -= gap;
            }

            arr[j] = key;
        }
    }
}
2. 二分插入排序
// 使用二分查找优化查找插入位置的时间
// 查找时间从O(n)优化到O(log n)
// 但移动元素仍需要O(n)时间，总体复杂度仍为O(n²)

⚡ 性能优化技巧
1. 哨兵优化
public void insertionSortWithSentinel(int[] arr) {
    // 将最小元素放在第一位作为哨兵
    int minIndex = 0;
    for (int i = 1; i &lt; arr.length; i++) {
        if (arr[i] &lt; arr[minIndex]) {
            minIndex = i;
        }
    }
    swap(arr, 0, minIndex);

    // 现在可以省略边界检查 j &gt;= 0
    for (int i = 2; i &lt; arr.length; i++) {
        int key = arr[i];
        int j = i - 1;

        while (arr[j] &gt; key) {  // 不需要检查 j &gt;= 0
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = key;
    }
}
2. 提前终止优化
public void insertionSortEarlyTermination(int[] arr) {
    for (int i = 1; i &lt; arr.length; i++) {
        int key = arr[i];

        // 如果当前元素已经大于等于前一个元素，跳过
        if (key &gt;= arr[i - 1]) {
            continue;
        }

        int j = i - 1;
        while (j &gt;= 0 &amp;&amp; arr[j] &gt; key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

