二叉树遍历通用模式
二叉树遍历通用模式
概述
二叉树遍历是算法面试中的高频考点，掌握通用的解题模式可以快速解决各种变种问题。本文档总结了二叉树遍历的通用解题思路和代码模板。
核心思想
1. 递归三要素

递归终止条件：通常是节点为空
递归函数功能：明确当前递归层要做什么
递归调用：如何缩小问题规模

2. 迭代的栈模拟

栈的作用：保存递归调用的上下文
入栈顺序：决定了访问顺序
出栈时机：决定了何时处理节点

通用代码模板
递归模板
// 递归遍历通用模板
public void traverseRecursive(TreeNode root) {
    // 1. 递归终止条件
    if (root == null) {
        return;
    }

    // 2. 处理当前节点（前序位置）
    process(root);

    // 3. 递归处理左子树
    traverseRecursive(root.left);

    // 4. 处理当前节点（中序位置）
    process(root);

    // 5. 递归处理右子树
    traverseRecursive(root.right);

    // 6. 处理当前节点（后序位置）
    process(root);
}
迭代模板
前序遍历模板
public List&lt;Integer&gt; preorderTemplate(TreeNode root) {
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
    if (root == null) return result;

    Stack&lt;TreeNode&gt; stack = new Stack&lt;&gt;();
    stack.push(root);

    while (!stack.isEmpty()) {
        TreeNode node = stack.pop();

        // 处理当前节点
        result.add(node.val);

        // 先右后左入栈（保证左子树先处理）
        if (node.right != null) stack.push(node.right);
        if (node.left != null) stack.push(node.left);
    }

    return result;
}
中序遍历模板
public List&lt;Integer&gt; inorderTemplate(TreeNode root) {
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
    Stack&lt;TreeNode&gt; stack = new Stack&lt;&gt;();
    TreeNode current = root;

    while (current != null || !stack.isEmpty()) {
        // 一直向左走，压栈
        while (current != null) {
            stack.push(current);
            current = current.left;
        }

        // 处理栈顶节点
        current = stack.pop();
        result.add(current.val);

        // 转向右子树
        current = current.right;
    }

    return result;
}
后序遍历模板
// 方法一：单栈 + 标记
public List&lt;Integer&gt; postorderTemplate1(TreeNode root) {
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
    if (root == null) return result;

    Stack&lt;TreeNode&gt; stack = new Stack&lt;&gt;();
    TreeNode lastVisited = null;
    TreeNode current = root;

    while (current != null || !stack.isEmpty()) {
        if (current != null) {
            stack.push(current);
            current = current.left;
        } else {
            TreeNode peekNode = stack.peek();
            if (peekNode.right != null &amp;&amp; lastVisited != peekNode.right) {
                current = peekNode.right;
            } else {
                result.add(peekNode.val);
                lastVisited = stack.pop();
            }
        }
    }

    return result;
}

// 方法二：双栈法
public List&lt;Integer&gt; postorderTemplate2(TreeNode root) {
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
    if (root == null) return result;

    Stack&lt;TreeNode&gt; stack1 = new Stack&lt;&gt;();
    Stack&lt;TreeNode&gt; stack2 = new Stack&lt;&gt;();

    stack1.push(root);

    while (!stack1.isEmpty()) {
        TreeNode node = stack1.pop();
        stack2.push(node);

        if (node.left != null) stack1.push(node.left);
        if (node.right != null) stack1.push(node.right);
    }

    while (!stack2.isEmpty()) {
        result.add(stack2.pop().val);
    }

    return result;
}
解题步骤
1. 分析问题

确定遍历类型（前序/中序/后序/层序）
确定实现方式（递归/迭代）
明确输出格式

2. 选择模板

简单问题：优先选择递归
需要控制过程：选择迭代
空间限制严格：考虑Morris遍历

3. 套用模板

替换处理逻辑
调整数据结构
处理边界条件

4. 测试验证

空树测试
单节点测试
完全二叉树测试
链状树测试

常见变种问题及解法
1. 路径问题
// 模板：从根到叶子的所有路径
public List&lt;String&gt; binaryTreePaths(TreeNode root) {
    List&lt;String&gt; result = new ArrayList&lt;&gt;();
    if (root == null) return result;

    dfs(root, &quot;&quot;, result);
    return result;
}

private void dfs(TreeNode node, String path, List&lt;String&gt; result) {
    if (node == null) return;

    path += node.val;

    // 叶子节点
    if (node.left == null &amp;&amp; node.right == null) {
        result.add(path);
        return;
    }

    path += &quot;-&gt;&quot;;
    dfs(node.left, path, result);
    dfs(node.right, path, result);
}
2. 层序遍历变种
// 模板：按层遍历
public List&lt;List&lt;Integer&gt;&gt; levelOrderTemplate(TreeNode root) {
    List&lt;List&lt;Integer&gt;&gt; result = new ArrayList&lt;&gt;();
    if (root == null) return result;

    Queue&lt;TreeNode&gt; queue = new LinkedList&lt;&gt;();
    queue.offer(root);

    while (!queue.isEmpty()) {
        int size = queue.size();
        List&lt;Integer&gt; level = new ArrayList&lt;&gt;();

        for (int i = 0; i &lt; size; i++) {
            TreeNode node = queue.poll();
            level.add(node.val);

            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }

        result.add(level);
    }

    return result;
}
3. 树的构造问题
// 模板：根据前序和中序构造二叉树
public TreeNode buildTreeTemplate(int[] preorder, int[] inorder) {
    Map&lt;Integer, Integer&gt; inorderMap = new HashMap&lt;&gt;();
    for (int i = 0; i &lt; inorder.length; i++) {
        inorderMap.put(inorder[i], i);
    }

    return buildHelper(preorder, 0, preorder.length - 1,
                      inorder, 0, inorder.length - 1, inorderMap);
}

private TreeNode buildHelper(int[] preorder, int preStart, int preEnd,
                           int[] inorder, int inStart, int inEnd,
                           Map&lt;Integer, Integer&gt; inorderMap) {
    if (preStart &gt; preEnd) return null;

    int rootVal = preorder[preStart];
    TreeNode root = new TreeNode(rootVal);

    int rootIndex = inorderMap.get(rootVal);
    int leftSize = rootIndex - inStart;

    root.left = buildHelper(preorder, preStart + 1, preStart + leftSize,
                           inorder, inStart, rootIndex - 1, inorderMap);
    root.right = buildHelper(preorder, preStart + leftSize + 1, preEnd,
                            inorder, rootIndex + 1, inEnd, inorderMap);

    return root;
}
