    return stack.isEmpty();
}
2. 内存性能优化策略
容量预估
// 根据树的特征预估栈深度
public int estimateStackDepth(TreeNode root) {
    if (root == null) return 0;

    // 对于平衡树：深度约为 log2(n)
    // 对于链式树：深度约为 n
    // 保守估计：使用 sqrt(n) 作为初始容量
    int nodeCount = countNodes(root);
    return Math.max(16, (int) Math.sqrt(nodeCount));
}

// 使用预估容量
int capacity = estimateStackDepth(root);
Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;(capacity);
内存使用监控
public class MemoryAwareTraversal {
    private static final int MAX_STACK_SIZE = 10000;

    public List&lt;Integer&gt; safePreorder(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();

        if (root != null) stack.push(root);

        while (!stack.isEmpty()) {
            // 防止栈溢出
            if (stack.size() &gt; MAX_STACK_SIZE) {
                throw new RuntimeException(&quot;树深度过大，可能导致栈溢出&quot;);
            }

            TreeNode node = stack.pop();
            result.add(node.val);

            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);
        }

        return result;
    }
}
3. 空间复杂度优化
Morris遍历（O(1)空间）
// 中序Morris遍历
public List&lt;Integer&gt; morrisInorder(TreeNode root) {
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
    TreeNode current = root;

    while (current != null) {
        if (current.left == null) {
            result.add(current.val);
            current = current.right;
        } else {
            // 找到前驱节点
            TreeNode predecessor = current.left;
            while (predecessor.right != null &amp;&amp; predecessor.right != current) {
                predecessor = predecessor.right;
            }

            if (predecessor.right == null) {
                // 建立线索
                predecessor.right = current;
                current = current.left;
            } else {
                // 恢复树结构
                predecessor.right = null;
                result.add(current.val);
                current = current.right;
            }
        }
    }

    return result;
}
4. 性能基准测试
不同实现的性能对比
public class TraversalBenchmark {
    public static void benchmark(TreeNode root, int iterations) {
        // Stack实现
        long start = System.nanoTime();
        for (int i = 0; i &lt; iterations; i++) {
            preorderWithStack(root);
        }
        long stackTime = System.nanoTime() - start;

        // ArrayDeque实现
        start = System.nanoTime();
        for (int i = 0; i &lt; iterations; i++) {
            preorderWithArrayDeque(root);
        }
        long dequeTime = System.nanoTime() - start;

        // LinkedList实现
        start = System.nanoTime();
        for (int i = 0; i &lt; iterations; i++) {
            preorderWithLinkedList(root);
        }
        long linkedTime = System.nanoTime() - start;

        System.out.printf(&quot;Stack: %d ms%n&quot;, stackTime / 1_000_000);
        System.out.printf(&quot;ArrayDeque: %d ms%n&quot;, dequeTime / 1_000_000);
        System.out.printf(&quot;LinkedList: %d ms%n&quot;, linkedTime / 1_000_000);

        System.out.printf(&quot;ArrayDeque比Stack快: %.1f%%%n&quot;, 
            (double)(stackTime - dequeTime) / stackTime * 100);
    }
}
5. 递归技巧

明确递归函数的定义：函数做什么，返回什么
利用递归的返回值：子问题的结果如何组合
前序位置：刚进入节点时的逻辑
后序位置：即将离开节点时的逻辑

6. 迭代技巧

栈的使用：模拟递归调用栈
