/**
 * 栈算法性能优化指南
 */
public class StackOptimizationGuide {

    // 1. 选择合适的栈实现
    public &lt;T&gt; Deque&lt;T&gt; chooseStackImplementation(int expectedSize, boolean needRandomAccess) {
        if (needRandomAccess) {
            return new ArrayList&lt;&gt;();  // 支持随机访问
        } else if (expectedSize &gt; 1000) {
            return new ArrayDeque&lt;&gt;();  // 大数据量，性能更好
        } else {
            return new LinkedList&lt;&gt;();  // 小数据量，内存效率高
        }
    }

    // 2. 避免不必要的对象创建
    public int[] optimizedNextGreaterElement(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        int[] stack = new int[n];  // 使用数组模拟栈
        int top = -1;

        for (int i = n - 1; i &gt;= 0; i--) {
            while (top &gt;= 0 &amp;&amp; nums[stack[top]] &lt;= nums[i]) {
                top--;
            }
            result[i] = (top &gt;= 0) ? nums[stack[top]] : -1;
            stack[++top] = i;
        }

        return result;
    }

    // 3. 提前终止优化
    public boolean hasValidParentheses(String s) {
        if (s.length() % 2 == 1) return false;  // 提前终止

        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == &#039;(&#039;) {
                count++;
            } else if (c == &#039;)&#039;) {
                count--;
                if (count &lt; 0) return false;  // 提前终止
            }
        }

        return count == 0;
    }
}
