public class StackDebuggingTips {

    // 1. 栈状态可视化
    public void visualizeStack(Deque&lt;Integer&gt; stack, String operation) {
        System.out.printf(&quot;操作: %s\n&quot;, operation);
        System.out.printf(&quot;栈状态: %s\n&quot;, stack.toString());
        System.out.printf(&quot;栈顶: %s\n&quot;, stack.isEmpty() ? &quot;空&quot; : stack.peek());
        System.out.println(&quot;---&quot;);
    }

    // 2. 单调栈调试模板
    public int[] debugMonotonicStack(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();

        System.out.println(&quot;单调栈调试信息:&quot;);
        for (int i = 0; i &lt; n; i++) {
            System.out.printf(&quot;处理元素 nums[%d] = %d\n&quot;, i, nums[i]);

            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt; nums[i]) {
                int index = stack.pop();
                result[index] = nums[i];
                System.out.printf(&quot;  找到答案: nums[%d] = %d 的下一个更大元素是 nums[%d] = %d\n&quot;, 
                                index, nums[index], i, nums[i]);
            }

            stack.push(i);
            visualizeStack(stack, &quot;push &quot; + i);
        }

        return result;
    }

    // 3. 状态栈调试模板
    public String debugStateStack(String s) {
        Deque&lt;Integer&gt; countStack = new ArrayDeque&lt;&gt;();
        Deque&lt;StringBuilder&gt; stringStack = new ArrayDeque&lt;&gt;();
        StringBuilder currentString = new StringBuilder();
        int count = 0;

        System.out.println(&quot;状态栈调试信息:&quot;);
        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);
            System.out.printf(&quot;处理字符 &#039;%c&#039; (位置 %d)\n&quot;, c, i);

            if (Character.isDigit(c)) {
                count = count * 10 + (c - &#039;0&#039;);
                System.out.printf(&quot;  更新计数: %d\n&quot;, count);
            } else if (c == &#039;[&#039;) {
                countStack.push(count);
                stringStack.push(currentString);
                System.out.printf(&quot;  保存状态: count=%d, string=&#039;%s&#039;\n&quot;, count, currentString);
                count = 0;
                currentString = new StringBuilder();
            } else if (c == &#039;]&#039;) {
                StringBuilder temp = currentString;
                currentString = stringStack.pop();
                int repeatCount = countStack.pop();
                System.out.printf(&quot;  恢复状态: repeatCount=%d, string=&#039;%s&#039;, temp=&#039;%s&#039;\n&quot;, 
                                repeatCount, currentString, temp);
                for (int j = 0; j &lt; repeatCount; j++) {
                    currentString.append(temp);
                }
                System.out.printf(&quot;  重复后: &#039;%s&#039;\n&quot;, currentString);
            } else {
                currentString.append(c);
                System.out.printf(&quot;  添加字符: &#039;%s&#039;\n&quot;, currentString);
            }
        }

        return currentString.toString();
    }
}
