public class StackSolutionTemplate {
    public ResultType solve(InputType input) {
        // 1. 初始化栈和结果容器
        Deque&lt;ElementType&gt; stack = new ArrayDeque&lt;&gt;();
        ResultType result = initializeResult();

        // 2. 遍历输入数据
        for (ElementType element : input) {
            // 3. 栈的核心处理逻辑
            while (!stack.isEmpty() &amp;&amp; shouldPop(stack.peek(), element)) {
                ElementType popped = stack.pop();
                processPopped(popped, result);
            }

            // 4. 处理当前元素
            processCurrentElement(element, result);

            // 5. 决定是否入栈
            if (shouldPush(element)) {
                stack.push(element);
            }
        }

        // 6. 处理栈中剩余元素
        while (!stack.isEmpty()) {
            processRemaining(stack.pop(), result);
        }

        return result;
    }

