// 1. 基础括号匹配
public boolean isValidParentheses(String s) {
    Deque&lt;Character&gt; stack = new ArrayDeque&lt;&gt;();
    for (char c : s.toCharArray()) {
        if (c == &#039;(&#039; || c == &#039;[&#039; || c == &#039;{&#039;) {
            stack.push(c);
        } else {
            if (stack.isEmpty()) return false;
            char top = stack.pop();
            if ((c == &#039;)&#039; &amp;&amp; top != &#039;(&#039;) || 
                (c == &#039;]&#039; &amp;&amp; top != &#039;[&#039;) || 
                (c == &#039;}&#039; &amp;&amp; top != &#039;{&#039;)) {
                return false;
            }
        }
    }
    return stack.isEmpty();
}

// 2. HTML标签匹配
public boolean isValidHTML(String html) {
    Deque&lt;String&gt; stack = new ArrayDeque&lt;&gt;();
    Pattern tagPattern = Pattern.compile(&quot;&lt;(/?)([a-zA-Z]+)&gt;&quot;);
    Matcher matcher = tagPattern.matcher(html);

    while (matcher.find()) {
        String isClosing = matcher.group(1);
        String tagName = matcher.group(2);

        if (isClosing.isEmpty()) {
            // 开始标签
            stack.push(tagName);
        } else {
            // 结束标签
            if (stack.isEmpty() || !stack.pop().equals(tagName)) {
                return false;
            }
        }
    }

    return stack.isEmpty();
}
模式2：单调栈模式
解题思路

维护栈的单调性（递增或递减）
当前元素破坏单调性时，弹出栈顶元素
弹出过程中计算结果

代码模板
public class MonotonicStackPattern {
    public int[] nextGreaterElements(int[] nums) {
        int[] result = new int[nums.length];
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;(); // 存储索引

        // 从右到左遍历（或从左到右，取决于具体问题）
        for (int i = nums.length - 1; i &gt;= 0; i--) {
            // 维护单调递减栈
            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt;= nums[i]) {
                stack.pop();
            }

            result[i] = stack.isEmpty() ? -1 : nums[stack.peek()];
            stack.push(i);
        }

        return result;
    }
}
