}

// ✅ 正确：检查空栈
public int safePeek(Deque&lt;Integer&gt; stack) {
    if (stack.isEmpty()) {
        throw new IllegalStateException(&quot;Stack is empty&quot;);
    }
    return stack.peek();
}
2. 索引越界
// ❌ 错误：可能索引越界
while (!stack.isEmpty()) {
    int index = stack.pop();
    result[index] = nums[index + 1]; // 可能越界
}

// ✅ 正确：边界检查
while (!stack.isEmpty()) {
    int index = stack.pop();
    if (index + 1 &lt; nums.length) {
        result[index] = nums[index + 1];
    }
}
