1️⃣1️⃣ 单词搜索 (LeetCode 79)
📝 题目描述
给定一个 m x n 二维字符网格 board 和一个字符串单词 word。如果 word 存在于网格中，返回 true；否则，返回 false。
单词必须按照字母顺序，通过相邻的单元格内的字母构成，其中”相邻”单元格是那些水平相邻或垂直相邻的单元格。同一个单元格内的字母不允许被重复使用。
示例 1：
输入：board = [[&quot;A&quot;,&quot;B&quot;,&quot;C&quot;,&quot;E&quot;],[&quot;S&quot;,&quot;F&quot;,&quot;C&quot;,&quot;S&quot;],[&quot;A&quot;,&quot;D&quot;,&quot;E&quot;,&quot;E&quot;]], word = &quot;ABCCED&quot;
输出：true
示例 2：
输入：board = [[&quot;A&quot;,&quot;B&quot;,&quot;C&quot;,&quot;E&quot;],[&quot;S&quot;,&quot;F&quot;,&quot;C&quot;,&quot;S&quot;],[&quot;A&quot;,&quot;D&quot;,&quot;E&quot;,&quot;E&quot;]], word = &quot;SEE&quot;
输出：true
示例 3：
输入：board = [[&quot;A&quot;,&quot;B&quot;,&quot;C&quot;,&quot;E&quot;],[&quot;S&quot;,&quot;F&quot;,&quot;C&quot;,&quot;S&quot;],[&quot;A&quot;,&quot;D&quot;,&quot;E&quot;,&quot;E&quot;]], word = &quot;ABCB&quot;
输出：false
🔧 基础解法：DFS回溯
class Solution {
    private int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public boolean exist(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        // 从每个位置开始尝试
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (dfs(board, word, i, j, 0)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean dfs(char[][] board, String word, int row, int col, int index) {
        // 边界检查
        if (row &lt; 0 || row &gt;= board.length || col &lt; 0 || col &gt;= board[0].length) {
            return false;
        }

        // 字符不匹配或已访问
        if (board[row][col] != word.charAt(index)) {
            return false;
        }

        // 找到完整单词
        if (index == word.length() - 1) {
            return true;
        }

        // 标记当前位置为已访问
        char temp = board[row][col];
        board[row][col] = &#039;#&#039;;

        // 向四个方向搜索
        for (int[] dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (dfs(board, word, newRow, newCol, index + 1)) {
                board[row][col] = temp; // 恢复
                return true;
            }
        }

        // 回溯：恢复当前位置
        board[row][col] = temp;
        return false;
    }
}
复杂度分析：

时间复杂度：O(m * n * 4^L)，L是单词长度
空间复杂度：O(L)，递归调用栈

🚀 进阶解法：多重优化剪枝
class Solution {
    private int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public boolean exist(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;

        // 优化1：字符频率统计
        int[] boardCount = new int[128];
        int[] wordCount = new int[128];

        for (char[] row : board) {
            for (char c : row) {
                boardCount[c]++;
            }
        }

        for (char c : word.toCharArray()) {
            wordCount[c]++;
            if (boardCount[c] &lt; wordCount[c]) {
                return false; // 字符数量不足
            }
        }

        // 优化2：如果末尾字符出现频率更低，反转单词
        if (boardCount[word.charAt(0)] &gt; boardCount[word.charAt(word.length() - 1)]) {
            word = new StringBuilder(word).reverse().toString();
        }

        // 优化3：从出现频率最低的字符开始搜索
        char startChar = word.charAt(0);
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (board[i][j] == startChar &amp;&amp; dfs(board, word, i, j, 0)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean dfs(char[][] board, String word, int row, int col, int index) {
        if (index == word.length()) {
            return true;
        }

        if (row &lt; 0 || row &gt;= board.length || col &lt; 0 || col &gt;= board[0].length ||
            board[row][col] != word.charAt(index)) {
            return false;
        }

        char temp = board[row][col];
        board[row][col] = &#039;#&#039;;

        // 优化4：提前检查剩余字符是否足够
        boolean found = false;
        for (int[] dir : directions) {
            if (dfs(board, word, row + dir[0], col + dir[1], index + 1)) {
                found = true;
                break;
            }
        }

        board[row][col] = temp;
        return found;
    }
}
复杂度分析：

时间复杂度：O(m * n * 4^L)，但实际运行更快
空间复杂度：O(L)

🚀 最优解法：Trie树+并行搜索
class Solution {
    class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;

        public TrieNode() {
            word = null;
        }
    }

    private int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public boolean exist(char[][] board, String word) {
        // 构建Trie树（适用于多单词搜索的扩展）
        TrieNode root = buildTrie(new String[]{word});

        int m = board.length;
        int n = board[0].length;

        // 字符频率优化
        int[] boardFreq = new int[26];
        for (char[] row : board) {
            for (char c : row) {
                if (c &gt;= &#039;a&#039; &amp;&amp; c &lt;= &#039;z&#039;) {
                    boardFreq[c - &#039;a&#039;]++;
                } else if (c &gt;= &#039;A&#039; &amp;&amp; c &lt;= &#039;Z&#039;) {
                    boardFreq[c - &#039;A&#039;]++;
                }
            }
        }

        // 检查字符频率
        int[] wordFreq = new int[26];
        for (char c : word.toCharArray()) {
            int index = Character.toLowerCase(c) - &#039;a&#039;;
            wordFreq[index]++;
            if (boardFreq[index] &lt; wordFreq[index]) {
                return false;
            }
        }

        // DFS搜索
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (dfs(board, i, j, root)) {
                    return true;
                }
            }
        }

        return false;
    }

    private TrieNode buildTrie(String[] words) {
        TrieNode root = new TrieNode();

        for (String word : words) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                int index = Character.toLowerCase(c) - &#039;a&#039;;
                if (node.children[index] == null) {
                    node.children[index] = new TrieNode();
                }
                node = node.children[index];
            }
            node.word = word;
        }

        return root;
    }

    private boolean dfs(char[][] board, int row, int col, TrieNode node) {
        if (row &lt; 0 || row &gt;= board.length || col &lt; 0 || col &gt;= board[0].length) {
            return false;
        }

        char c = board[row][col];
        if (c == &#039;#&#039;) {
            return false;
        }

        int index = Character.toLowerCase(c) - &#039;a&#039;;
        if (index &lt; 0 || index &gt;= 26 || node.children[index] == null) {
            return false;
        }

        node = node.children[index];
        if (node.word != null) {
            return true;
        }

        board[row][col] = &#039;#&#039;;

        for (int[] dir : directions) {
            if (dfs(board, row + dir[0], col + dir[1], node)) {
                board[row][col] = c;
                return true;
            }
        }

        board[row][col] = c;
        return false;
    }
}
复杂度分析：

时间复杂度：O(m * n * 4^L)
空间复杂度：O(L)


