public double[] calcEquation(List&lt;List&lt;String&gt;&gt; equations, double[] values, List&lt;List&lt;String&gt;&gt; queries) {
    // 构建带权图
    Map&lt;String, Map&lt;String, Double&gt;&gt; graph = new HashMap&lt;&gt;();

    for (int i = 0; i &lt; equations.size(); i++) {
        String a = equations.get(i).get(0);
        String b = equations.get(i).get(1);
        double value = values[i];

        graph.putIfAbsent(a, new HashMap&lt;&gt;());
        graph.putIfAbsent(b, new HashMap&lt;&gt;());

        graph.get(a).put(b, value);
        graph.get(b).put(a, 1.0 / value);
    }

    double[] results = new double[queries.size()];

    for (int i = 0; i &lt; queries.size(); i++) {
        String start = queries.get(i).get(0);
        String end = queries.get(i).get(1);
        results[i] = dfs(graph, start, end, new HashSet&lt;&gt;());
    }

    return results;
}

private double dfs(Map&lt;String, Map&lt;String, Double&gt;&gt; graph, String start, String end, Set&lt;String&gt; visited) {
    if (!graph.containsKey(start) || !graph.containsKey(end)) {
        return -1.0;
    }
    if (start.equals(end)) {
        return 1.0;
    }

    visited.add(start);

    for (Map.Entry&lt;String, Double&gt; neighbor : graph.get(start).entrySet()) {
        String next = neighbor.getKey();
        double weight = neighbor.getValue();

        if (!visited.contains(next)) {
            double result = dfs(graph, next, end, visited);
            if (result != -1.0) {
                visited.remove(start);
                return weight * result;
            }
        }
    }

    visited.remove(start);
    return -1.0;
}
Java 并查集模板:
class UnionFind {
    private Map&lt;String, String&gt; parent;
    private Map&lt;String, Double&gt; weight;

    public UnionFind() {
        parent = new HashMap&lt;&gt;();
        weight = new HashMap&lt;&gt;();
    }

    public String find(String x) {
        if (!parent.containsKey(x)) {
            parent.put(x, x);
            weight.put(x, 1.0);
            return x;
        }

        if (!parent.get(x).equals(x)) {
            String origin = parent.get(x);
            parent.put(x, find(origin));
            weight.put(x, weight.get(x) * weight.get(origin));
        }
        return parent.get(x);
    }

    public void union(String x, String y, double value) {
        String rootX = find(x);
        String rootY = find(y);

        if (!rootX.equals(rootY)) {
            parent.put(rootX, rootY);
            weight.put(rootX, weight.get(y) * value / weight.get(x));
        }
    }

    public double query(String x, String y) {
        if (!parent.containsKey(x) || !parent.containsKey(y)) {
            return -1.0;
        }

        String rootX = find(x);
        String rootY = find(y);

        if (!rootX.equals(rootY)) {
            return -1.0;
        }

        return weight.get(x) / weight.get(y);
    }
}

public double[] calcEquationUnionFind(List&lt;List&lt;String&gt;&gt; equations, double[] values, List&lt;List&lt;String&gt;&gt; queries) {
    UnionFind uf = new UnionFind();

    // 构建并查集
    for (int i = 0; i &lt; equations.size(); i++) {
        String a = equations.get(i).get(0);
        String b = equations.get(i).get(1);
        uf.union(a, b, values[i]);
    }

    double[] results = new double[queries.size()];

    for (int i = 0; i &lt; queries.size(); i++) {
        String a = queries.get(i).get(0);
        String b = queries.get(i).get(1);
        results[i] = uf.query(a, b);
    }

    return results;
}
