    while (!queue.isEmpty()) {
        int node = queue.poll();
        // 处理当前节点

        if (graph.containsKey(node)) {
            for (int neighbor : graph.get(node)) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.offer(neighbor);
                }
            }
        }
    }
}
🎯 拓扑排序模板
📊 Kahn算法 (BFS)
public List&lt;Integer&gt; topologicalSort(List&lt;List&lt;Integer&gt;&gt; graph, int n) {
    int[] indegree = new int[n];

    // 计算入度
    for (int u = 0; u &lt; n; u++) {
        for (int v : graph.get(u)) {
            indegree[v]++;
        }
    }

    Queue&lt;Integer&gt; queue = new LinkedList&lt;&gt;();
    for (int i = 0; i &lt; n; i++) {
        if (indegree[i] == 0) {
            queue.offer(i);
        }
    }

    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();

    while (!queue.isEmpty()) {
        int node = queue.poll();
        result.add(node);

        for (int neighbor : graph.get(node)) {
            indegree[neighbor]--;
            if (indegree[neighbor] == 0) {
                queue.offer(neighbor);
            }
        }
    }

    return result.size() == n ? result : new ArrayList&lt;&gt;();
}
🔍 DFS拓扑排序
public List&lt;Integer&gt; topologicalSortDFS(List&lt;List&lt;Integer&gt;&gt; graph, int n) {
    final int WHITE = 0, GRAY = 1, BLACK = 2;
    int[] color = new int[n];
    List&lt;Integer&gt; result = new ArrayList&lt;&gt;();

    for (int i = 0; i &lt; n; i++) {
        if (color[i] == WHITE) {
            if (!dfs(graph, i, color, result)) {
                return new ArrayList&lt;&gt;();  // 有环
            }
        }
    }

    Collections.reverse(result);
    return result;
}

private boolean dfs(List&lt;List&lt;Integer&gt;&gt; graph, int node, int[] color, List&lt;Integer&gt; result) {
    final int WHITE = 0, GRAY = 1, BLACK = 2;

    if (color[node] == GRAY) {
        return false;  // 发现环
    }
    if (color[node] == BLACK) {
        return true;
    }

    color[node] = GRAY;

    for (int neighbor : graph.get(node)) {
        if (!dfs(graph, neighbor, color, result)) {
            return false;
        }
    }

    color[node] = BLACK;
    result.add(node);
    return true;
}

