🚀 优化技巧
1. 递归优化（避免栈溢出）
private void dfsIterative(char[][] grid, int startI, int startJ) {
    Stack&lt;int[]&gt; stack = new Stack&lt;&gt;();
    stack.push(new int[]{startI, startJ});

    while (!stack.isEmpty()) {
        int[] curr = stack.pop();
        int i = curr[0], j = curr[1];

        if (i &lt; 0 || i &gt;= grid.length || j &lt; 0 || j &gt;= grid[0].length || 
            grid[i][j] == &#039;0&#039;) {
            continue;
        }

        grid[i][j] = &#039;0&#039;;

        // 四方向入栈
        stack.push(new int[]{i + 1, j});
        stack.push(new int[]{i - 1, j});
        stack.push(new int[]{i, j + 1});
        stack.push(new int[]{i, j - 1});
    }
}
2. 并查集解法
class UnionFind {
    private int[] parent;
    private int count;

    public UnionFind(char[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        parent = new int[m * n];
        count = 0;

        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == &#039;1&#039;) {
                    parent[i * n + j] = i * n + j;
                    count++;
                }
            }
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
            count--;
        }
    }

    public int getCount() {
        return count;
    }
}

public int numIslands(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;

    int m = grid.length;
    int n = grid[0].length;
    UnionFind uf = new UnionFind(grid);
    int[][] directions = {{0, 1}, {1, 0}};

    for (int i = 0; i &lt; m; i++) {
        for (int j = 0; j &lt; n; j++) {
            if (grid[i][j] == &#039;1&#039;) {
                for (int[] dir : directions) {
                    int newI = i + dir[0];
                    int newJ = j + dir[1];
                    if (newI &lt; m &amp;&amp; newJ &lt; n &amp;&amp; grid[newI][newJ] == &#039;1&#039;) {
                        uf.union(i * n + j, newI * n + newJ);
                    }
                }
            }
        }
    }

    return uf.getCount();
}
