🎯 算法概述
BFS（广度优先搜索）层序搜索是解决”删除无效的括号”问题的最优方法。核心思想是通过逐层删除字符，天然保证找到的第一个有效解就是删除字符数最少的解。
算法特点：

最少删除保证：BFS按层搜索，第一层找到的有效解就是最优解
去重优化：使用HashSet避免重复处理相同字符串
智能剪枝：只删除括号字符，保留所有字母
早停机制：找到有效层后立即停止更深层搜索

💻 完整Java实现
import java.util.*;

public class RemoveInvalidParenthesesBFS {

    /**
     * BFS方法删除无效括号
     * @param s 输入字符串
     * @return 所有删除最少括号后的有效字符串集合
     */
    public List&lt;String&gt; removeInvalidParentheses(String s) {
        List&lt;String&gt; result = new ArrayList&lt;&gt;();
        if (s == null) return result;

        // 如果原始字符串已经有效，直接返回
        if (isValid(s)) {
            result.add(s);
            return result;
        }

        Queue&lt;String&gt; queue = new LinkedList&lt;&gt;();
        Set&lt;String&gt; visited = new HashSet&lt;&gt;();
        boolean found = false;

        // 初始化：将原始字符串加入队列
        queue.offer(s);
        visited.add(s);

        while (!queue.isEmpty()) {
            int levelSize = queue.size();

            // 处理当前层的所有字符串
            for (int i = 0; i &lt; levelSize; i++) {
                String current = queue.poll();

                // 检查当前字符串是否有效
                if (isValid(current)) {
                    result.add(current);
                    found = true; // 标记已找到有效层
                }

                // 如果已经找到有效字符串，不再生成下一层
                if (found) continue;

                // 生成下一层：删除一个字符
                for (int j = 0; j &lt; current.length(); j++) {
                    char c = current.charAt(j);

                    // 只删除括号字符，保留字母
                    if (c != &#039;(&#039; &amp;&amp; c != &#039;)&#039;) {
                        continue;
                    }

                    // 删除第j个字符
                    String next = current.substring(0, j) + current.substring(j + 1);

                    // 避免重复处理
                    if (!visited.contains(next)) {
                        visited.add(next);
                        queue.offer(next);
                    }
                }
            }

            // 如果当前层找到有效字符串，停止搜索
            if (found) break;
        }

        return result;
    }

    /**
     * 检查字符串括号是否有效
     * @param s 输入字符串
     * @return 是否有效
     */
    private boolean isValid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == &#039;(&#039;) {
                balance++;
            } else if (c == &#039;)&#039;) {
                balance--;
                // 任何时候右括号多于左括号都无效
                if (balance &lt; 0) return false;
            }
        }
        // 最终左右括号数量相等才有效
        return balance == 0;
    }

    /**
     * 测试方法
     */
    public static void main(String[] args) {
        RemoveInvalidParenthesesBFS solution = new RemoveInvalidParenthesesBFS();

        // 测试用例
        String[] testCases = {
            &quot;()())&quot;,
            &quot;(a)())&quot;,
            &quot;)(&quot;,
            &quot;abc&quot;,
            &quot;(((&quot;,
            &quot;)))&quot;,
            &quot;()())()&quot;
        };

        for (String testCase : testCases) {
            List&lt;String&gt; result = solution.removeInvalidParentheses(testCase);
            System.out.println(&quot;输入: \&quot;&quot; + testCase + &quot;\&quot;&quot;);
            System.out.println(&quot;输出: &quot; + result);
            System.out.println(&quot;---&quot;);
        }
    }
}
