/**
 * 下一个排列 - 详细版本
 * 包含完整的步骤说明和边界处理
 */
public class NextPermutationDetailed {

    public void nextPermutation(int[] nums) {
        if (nums == null || nums.length &lt;= 1) {
            return; // 空数组或单元素数组无需处理
        }

        int n = nums.length;

        // ========== 步骤1：寻找递减点 ==========
        // 从右往左找第一个 nums[i] &lt; nums[i+1] 的位置
        // 这个位置是我们需要增大的位置
        int i = findDecreasingPoint(nums);

        // ========== 步骤2：寻找替换数字 ==========
        if (i &gt;= 0) {
            // 如果找到了递减点，从右往左找第一个大于nums[i]的数
            int j = findReplacementNumber(nums, i);

            // ========== 步骤3：交换 ==========
            swap(nums, i, j);
        }

        // ========== 步骤4：反转后续部分 ==========
        // 将i+1到末尾的部分反转，使其变为升序（最小排列）
        reverse(nums, i + 1, n - 1);
    }

    /**
     * 寻找递减点：从右往左找第一个nums[i] &lt; nums[i+1]的位置
     * @param nums 输入数组
     * @return 递减点的索引，如果不存在返回-1
     */
    private int findDecreasingPoint(int[] nums) {
        int i = nums.length - 2;

        // 从倒数第二个元素开始向左扫描
        while (i &gt;= 0 &amp;&amp; nums[i] &gt;= nums[i + 1]) {
            i--;
        }

        return i; // 返回-1表示整个数组是递减的（最大排列）
    }

    /**
     * 寻找替换数字：从右往左找第一个大于nums[i]的数
     * @param nums 输入数组
     * @param i 需要被替换的位置
     * @return 替换数字的索引
     */
    private int findReplacementNumber(int[] nums, int i) {
        int j = nums.length - 1;

        // 从右往左找第一个大于nums[i]的数
        while (nums[j] &lt;= nums[i]) {
            j--;
        }

        return j;
    }

    /**
     * 交换数组中两个位置的元素
     */
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    /**
     * 反转数组中指定范围的元素
     */
    private void reverse(int[] nums, int start, int end) {
        while (start &lt; end) {
            swap(nums, start, end);
            start++;
            end--;
        }
    }
}
