解法二：动态规划
核心思路
利用已知的小规模结果，构建大规模的解。对于n对括号，可以分解为：( + i对括号 + ) + (n-1-i)对括号
class Solution {
    public List&lt;String&gt; generateParenthesis(int n) {
        List&lt;List&lt;String&gt;&gt; dp = new ArrayList&lt;&gt;();

        // 初始化：dp[0] = [&quot;&quot;]
        dp.add(Arrays.asList(&quot;&quot;));

        for (int i = 1; i &lt;= n; i++) {
            List&lt;String&gt; current = new ArrayList&lt;&gt;();

            // 枚举左侧括号内的对数
            for (int j = 0; j &lt; i; j++) {
                List&lt;String&gt; left = dp.get(j);      // j对括号
                List&lt;String&gt; right = dp.get(i - 1 - j);  // (i-1-j)对括号

                // 组合：( + left + ) + right
                for (String l : left) {
                    for (String r : right) {
                        current.add(&quot;(&quot; + l + &quot;)&quot; + r);
                    }
                }
            }

            dp.add(current);
        }

        return dp.get(n);
    }
}
DP构建过程
dp[0] = [&quot;&quot;]
dp[1] = [&quot;()&quot;]
dp[2] = [&quot;(())&quot;, &quot;()()&quot;]
dp[3] = [&quot;((()))&quot;, &quot;(()())&quot;, &quot;(())()&quot;, &quot;()(())&quot;, &quot;()()()&quot;]

解法三：BFS层次遍历
核心思路
使用队列进行广度优先搜索，逐层构建有效的括号序列。
class Solution {
    static class Node {
        String str;
        int left;
        int right;

        Node(String str, int left, int right) {
            this.str = str;
            this.left = left;
            this.right = right;
        }
    }

    public List&lt;String&gt; generateParenthesis(int n) {
        List&lt;String&gt; result = new ArrayList&lt;&gt;();
        Queue&lt;Node&gt; queue = new LinkedList&lt;&gt;();

        queue.offer(new Node(&quot;&quot;, 0, 0));

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            // 如果序列长度达到2n，加入结果
            if (current.str.length() == 2 * n) {
                result.add(current.str);
                continue;
            }

            // 尝试添加左括号
            if (current.left &lt; n) {
                queue.offer(new Node(current.str + &quot;(&quot;, current.left + 1, current.right));
            }

            // 尝试添加右括号
            if (current.right &lt; current.left) {
                queue.offer(new Node(current.str + &quot;)&quot;, current.left, current.right + 1));
            }
        }

        return result;
    }
}
解法四：暴力枚举 + 验证
核心思路
生成所有可能的2^(2n)种括号序列，然后验证每个序列是否有效。
class Solution {
    public List&lt;String&gt; generateParenthesis(int n) {
        List&lt;String&gt; result = new ArrayList&lt;&gt;();
        char[] current = new char[2 * n];
        generateAll(current, 0, result);
        return result;
    }

    private void generateAll(char[] current, int pos, List&lt;String&gt; result) {
        if (pos == current.length) {
            if (isValid(current)) {
                result.add(new String(current));
            }
            return;
        }

        current[pos] = &#039;(&#039;;
        generateAll(current, pos + 1, result);

        current[pos] = &#039;)&#039;;
        generateAll(current, pos + 1, result);
    }

    private boolean isValid(char[] chars) {
        int balance = 0;
        for (char c : chars) {
            if (c == &#039;(&#039;) {
                balance++;
            } else {
                balance--;
            }
            if (balance &lt; 0) {
                return false;
            }
        }
        return balance == 0;
    }
}
