[]✓

有效路径：[7], [2,2,3]

解法二：递归回溯（优化版）
核心思路
先对数组排序，利用排序后的性质进行更有效的剪枝。
class Solution {
    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) {
        List&lt;List&lt;Integer&gt;&gt; result = new ArrayList&lt;&gt;();
        List&lt;Integer&gt; path = new ArrayList&lt;&gt;();

        // 排序以便剪枝
        Arrays.sort(candidates);

        backtrack(candidates, target, 0, path, result);
        return result;
    }

    private void backtrack(int[] candidates, int target, int start, 
                          List&lt;Integer&gt; path, List&lt;List&lt;Integer&gt;&gt; result) {
        if (target == 0) {
            result.add(new ArrayList&lt;&gt;(path));
            return;
        }

        for (int i = start; i &lt; candidates.length; i++) {
            // 剪枝：由于数组已排序，后面的数字都会更大
            if (candidates[i] &gt; target) {
                break;  // 直接跳出循环
            }

            path.add(candidates[i]);
            backtrack(candidates, target - candidates[i], i, path, result);
            path.remove(path.size() - 1);
        }
    }
}
解法三：动态规划
核心思路
使用动态规划的思想，dp[i] 表示和为 i 的所有组合。
class Solution {
    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) {
        // dp[i] 存储和为 i 的所有组合
        List&lt;List&lt;List&lt;Integer&gt;&gt;&gt; dp = new ArrayList&lt;&gt;();

        // 初始化
        for (int i = 0; i &lt;= target; i++) {
            dp.add(new ArrayList&lt;&gt;());
        }
        dp.get(0).add(new ArrayList&lt;&gt;());  // 和为0的组合是空集

        // 遍历每个候选数字
        for (int candidate : candidates) {
            // 更新所有可能的和
            for (int i = candidate; i &lt;= target; i++) {
                // 如果 dp[i - candidate] 有解，则可以构造 dp[i]
                for (List&lt;Integer&gt; combination : dp.get(i - candidate)) {
                    List&lt;Integer&gt; newCombination = new ArrayList&lt;&gt;(combination);
                    newCombination.add(candidate);
                    dp.get(i).add(newCombination);
                }
            }
        }

        return dp.get(target);
    }
}
解法四：BFS层次搜索
核心思路
使用队列进行广度优先搜索，每一层代表一个选择的深度。
class Solution {
    static class Node {
        List&lt;Integer&gt; path;
        int sum;
        int start;

        Node(List&lt;Integer&gt; path, int sum, int start) {
            this.path = new ArrayList&lt;&gt;(path);
            this.sum = sum;
            this.start = start;
        }
    }

    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) {
        List&lt;List&lt;Integer&gt;&gt; result = new ArrayList&lt;&gt;();
        Queue&lt;Node&gt; queue = new LinkedList&lt;&gt;();

        queue.offer(new Node(new ArrayList&lt;&gt;(), 0, 0));

        while (!queue.isEmpty()) {
            Node current = queue.poll();

            if (current.sum == target) {
                result.add(current.path);
                continue;
            }

            if (current.sum &gt; target) {
                continue;
            }

            for (int i = current.start; i &lt; candidates.length; i++) {
                List&lt;Integer&gt; newPath = new ArrayList&lt;&gt;(current.path);
                newPath.add(candidates[i]);
                queue.offer(new Node(newPath, current.sum + candidates[i], i));
            }
        }

        return result;
    }
}
解法五：记忆化搜索
核心思路
使用记忆化避免重复计算相同的子问题。
class Solution {
    private Map&lt;String, List&lt;List&lt;Integer&gt;&gt;&gt; memo = new HashMap&lt;&gt;();

    public List&lt;List&lt;Integer&gt;&gt; combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        return dfs(candidates, target, 0);
    }

    private List&lt;List&lt;Integer&gt;&gt; dfs(int[] candidates, int target, int start) {
        String key = target + &quot;,&quot; + start;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        List&lt;List&lt;Integer&gt;&gt; result = new ArrayList&lt;&gt;();

        if (target == 0) {
            result.add(new ArrayList&lt;&gt;());
            memo.put(key, result);
            return result;
        }

        for (int i = start; i &lt; candidates.length; i++) {
            if (candidates[i] &gt; target) {
                break;
            }

            List&lt;List&lt;Integer&gt;&gt; subResult = dfs(candidates, target - candidates[i], i);
            for (List&lt;Integer&gt; combination : subResult) {
                List&lt;Integer&gt; newCombination = new ArrayList&lt;&gt;();
                newCombination.add(candidates[i]);
                newCombination.addAll(combination);
                result.add(newCombination);
            }
        }

        memo.put(key, result);
        return result;
    }
}
