        path.remove(path.size() - 1);
        System.out.println(&quot;撤销元素：&quot; + nums[i] + &quot;，当前路径：&quot; + path);
    }

    System.out.println(&quot;退出递归，当前路径：&quot; + path);
}
🎯 常见错误与解决
错误1：忘记撤销
// ❌ 错误
