基础功能测试
public class MinStackTest {

    @Test
    public void testBasicOperations() {
        MinStack minStack = new MinStack();

        // 测试空栈
        assertTrue(minStack.isEmpty());

        // 测试单个元素
        minStack.push(5);
        assertEquals(5, minStack.top());
        assertEquals(5, minStack.getMin());

        // 测试多个元素
        minStack.push(3);
