public class FunctionCallStack {
    private Deque&lt;String&gt; callStack = new ArrayDeque&lt;&gt;();

    public void enterFunction(String functionName) {
        callStack.push(functionName);
        System.out.println(&quot;进入函数: &quot; + functionName);
        System.out.println(&quot;当前调用栈: &quot; + callStack);
    }

    public void exitFunction() {
        if (!callStack.isEmpty()) {
            String functionName = callStack.pop();
            System.out.println(&quot;退出函数: &quot; + functionName);
            System.out.println(&quot;当前调用栈: &quot; + callStack);
        }
    }

    public void showCallStack() {
        System.out.println(&quot;完整调用栈: &quot; + callStack);
    }
}
