public class NextGreaterElementII {

    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        Arrays.fill(result, -1);

        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();

        // 遍历两遍数组来模拟循环
        for (int i = 0; i &lt; 2 * n; i++) {
