            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt; num) {
                int index = stack.pop();
                result[index] = num;
            }

            // 只在第一遍时入栈
            if (i &lt; n) {
                stack.push(i);
            }
        }

        return result;
