import java.util.*;

public class MonotonicStack {

    /**
     * 单调递增栈模板
     * @param nums 输入数组
     * @return 处理结果
     */
    public int[] monotonicIncreasingStack(int[] nums) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        int[] result = new int[nums.length];

        for (int i = 0; i &lt; nums.length; i++) {
            // 维护单调递增性
            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &gt;= nums[i]) {
                int index = stack.pop();
                // 在这里处理被弹出的元素
                result[index] = processElement(index, i, nums);
            }
            stack.push(i);
        }

        // 处理栈中剩余元素
        while (!stack.isEmpty()) {
            int index = stack.pop();
            result[index] = processRemaining(index, nums);
        }

        return result;
    }

    /**
     * 单调递减栈模板
     * @param nums 输入数组
     * @return 处理结果
     */
    public int[] monotonicDecreasingStack(int[] nums) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        int[] result = new int[nums.length];

        for (int i = 0; i &lt; nums.length; i++) {
            // 维护单调递减性
            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt;= nums[i]) {
                int index = stack.pop();
                // 在这里处理被弹出的元素
                result[index] = processElement(index, i, nums);
            }
            stack.push(i);
        }

        // 处理栈中剩余元素
        while (!stack.isEmpty()) {
            int index = stack.pop();
            result[index] = processRemaining(index, nums);
        }

        return result;
    }

    // 处理被弹出元素的逻辑（根据具体问题实现）
    private int processElement(int popIndex, int currentIndex, int[] nums) {
        // 具体实现取决于问题需求
        return currentIndex - popIndex;
    }

    // 处理剩余元素的逻辑（根据具体问题实现）
    private int processRemaining(int index, int[] nums) {
        // 具体实现取决于问题需求
        return -1;
    }
}
