/**
 * 带可视化功能的单调栈实现
 */
public class VisualMonotonicStack {
    private Deque&lt;Integer&gt; stack;
    private boolean isIncreasing;

    public VisualMonotonicStack(boolean isIncreasing) {
        this.stack = new ArrayDeque&lt;&gt;();
        this.isIncreasing = isIncreasing;
    }

    public void push(int element) {
        System.out.println(&quot;\n=== 处理元素: &quot; + element + &quot; ===&quot;);
        System.out.println(&quot;当前栈状态: &quot; + stack);

        List&lt;Integer&gt; popped = new ArrayList&lt;&gt;();

        if (isIncreasing) {
            // 单调递增栈
            while (!stack.isEmpty() &amp;&amp; stack.peek() &gt;= element) {
                int poppedElement = stack.pop();
                popped.add(poppedElement);
                System.out.println(&quot;弹出元素: &quot; + poppedElement + 
                                 &quot; (因为 &quot; + poppedElement + &quot; &gt;= &quot; + element + &quot;)&quot;);
            }
        } else {
            // 单调递减栈
            while (!stack.isEmpty() &amp;&amp; stack.peek() &lt;= element) {
                int poppedElement = stack.pop();
                popped.add(poppedElement);
                System.out.println(&quot;弹出元素: &quot; + poppedElement + 
                                 &quot; (因为 &quot; + poppedElement + &quot; &lt;= &quot; + element + &quot;)&quot;);
            }
        }

        stack.push(element);
        System.out.println(&quot;入栈元素: &quot; + element);
        System.out.println(&quot;新栈状态: &quot; + stack);

        if (!popped.isEmpty()) {
            System.out.println(&quot;本次弹出的元素: &quot; + popped);
        }
    }

    public void showFinalState() {
        System.out.println(&quot;\n=== 最终状态 ===&quot;);
        System.out.println(&quot;栈类型: &quot; + (isIncreasing ? &quot;单调递增&quot; : &quot;单调递减&quot;));
        System.out.println(&quot;最终栈: &quot; + stack);
        System.out.println(&quot;栈大小: &quot; + stack.size());
    }

    // 演示方法
    public static void demo() {
        int[] nums = {3, 1, 4, 2, 6, 5};

        System.out.println(&quot;输入序列: &quot; + Arrays.toString(nums));

        // 演示单调递增栈
        System.out.println(&quot;\n&quot; + &quot;=&quot;.repeat(50));
        System.out.println(&quot;单调递增栈演示&quot;);
        System.out.println(&quot;=&quot;.repeat(50));

        VisualMonotonicStack incStack = new VisualMonotonicStack(true);
        for (int num : nums) {
            incStack.push(num);
        }
        incStack.showFinalState();

        // 演示单调递减栈
        System.out.println(&quot;\n&quot; + &quot;=&quot;.repeat(50));
        System.out.println(&quot;单调递减栈演示&quot;);
        System.out.println(&quot;=&quot;.repeat(50));

        VisualMonotonicStack decStack = new VisualMonotonicStack(false);
        for (int num : nums) {
            decStack.push(num);
        }
        decStack.showFinalState();
    }
}
🎯 单调栈的典型应用场景
1. 寻找下一个更大元素
问题描述： 对于数组中的每个元素，找到它右边第一个比它大的元素
/**
 * 下一个更大元素问题
 * 使用单调递减栈解决
 */
public int[] nextGreaterElement(int[] nums) {
    int n = nums.length;
    int[] result = new int[n];
    Arrays.fill(result, -1);  // 默认值为-1

    Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();  // 存储索引

    for (int i = 0; i &lt; n; i++) {
        // 当前元素比栈顶元素大，说明找到了栈顶元素的下一个更大元素
        while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt; nums[i]) {
            int index = stack.pop();
            result[index] = nums[i];
        }
        stack.push(i);
    }

    return result;
}
过程图解：
输入：[2, 1, 2, 4, 3, 1]

i=0, nums[0]=2:
栈：[] → [0]
结果：[-1, -1, -1, -1, -1, -1]

i=1, nums[1]=1:
比较：1 &lt; 2，直接入栈
栈：[0] → [0, 1]
结果：[-1, -1, -1, -1, -1, -1]

i=2, nums[2]=2:
比较：2 &gt; 1，弹出索引1，nums[1]的下一个更大元素是2
栈：[0, 1] → [0] → [0, 2]
结果：[-1, 2, -1, -1, -1, -1]

i=3, nums[3]=4:
比较：4 &gt; 2，弹出索引2，nums[2]的下一个更大元素是4
比较：4 &gt; 2，弹出索引0，nums[0]的下一个更大元素是4
栈：[0, 2] → [0] → [] → [3]
结果：[4, 2, 4, -1, -1, -1]

i=4, nums[4]=3:
比较：3 &lt; 4，直接入栈
栈：[3] → [3, 4]
结果：[4, 2, 4, -1, -1, -1]

i=5, nums[5]=1:
比较：1 &lt; 3，直接入栈
栈：[3, 4] → [3, 4, 5]
结果：[4, 2, 4, -1, -1, -1]

最终结果：[4, 2, 4, -1, -1, -1]
2. 柱状图中的最大矩形
问题描述： 给定柱状图的高度，求能构成的最大矩形面积
/**
 * 柱状图中最大矩形问题
 * 使用单调递增栈解决
 */
public int largestRectangleArea(int[] heights) {
    int n = heights.length;
    Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
    int maxArea = 0;

    for (int i = 0; i &lt;= n; i++) {
        // 在末尾添加高度为0的柱子，确保所有柱子都被处理
        int currentHeight = (i == n) ? 0 : heights[i];

        // 当前高度小于栈顶高度，计算以栈顶为高的矩形面积
        while (!stack.isEmpty() &amp;&amp; heights[stack.peek()] &gt; currentHeight) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }

        stack.push(i);
    }

    return maxArea;
}
过程图解：
输入：[2, 1, 5, 6, 2, 3]

柱状图：
    6
  5 █
  █ █     3
2 █ █ 2 █
█ █ █ █ █
█ 1 █ █ █
0 1 2 3 4 5

处理过程：
i=0: 栈=[0], 高度=2
i=1: 高度1&lt;2，弹出0，计算面积=2*1=2，栈=[1]
i=2: 栈=[1,2], 高度=5
i=3: 栈=[1,2,3], 高度=6
i=4: 高度2&lt;6，弹出3，计算面积=6*1=6
     高度2&lt;5，弹出2，计算面积=5*2=10
     栈=[1,4]
i=5: 栈=[1,4,5], 高度=3
i=6: 高度0，依次弹出所有元素计算面积

最大面积：10
3. 接雨水问题
问题描述： 给定高度数组，计算能接多少雨水
/**
 * 接雨水问题
 * 使用单调递减栈解决
 */
public int trap(int[] height) {
    Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
    int water = 0;

    for (int i = 0; i &lt; height.length; i++) {
        // 当前高度大于栈顶高度，可能形成凹槽
        while (!stack.isEmpty() &amp;&amp; height[i] &gt; height[stack.peek()]) {
            int bottom = stack.pop();  // 凹槽底部

            if (stack.isEmpty()) break;  // 没有左边界

            int left = stack.peek();   // 左边界
            int right = i;             // 右边界

            // 计算水的高度和宽度
            int h = Math.min(height[left], height[right]) - height[bottom];
            int w = right - left - 1;
            water += h * w;
        }
        stack.push(i);
    }

    return water;
}
