public void monotonicStackTemplate(int[] nums) {
    Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();

    for (int i = 0; i &lt; nums.length; i++) {
        // 关键：维护单调性的条件判断
        while (!stack.isEmpty() &amp;&amp; shouldPop(stack.peek(), i, nums)) {
            int poppedIndex = stack.pop();
            // 处理被弹出的元素
            processPopped(poppedIndex, i, nums);
        }
        stack.push(i);
    }

    // 处理栈中剩余元素
    while (!stack.isEmpty()) {
        processRemaining(stack.pop(), nums);
    }
}

