2. 镜像型双栈 - 共享空间
核心思想： 两个栈在同一数组中相向增长，最大化空间利用率
/**
 * 镜像型双栈实现
 */
public class MirrorDualStack&lt;T&gt; {
    private Object[] array;
    private int capacity;
    private int top1;  // 栈1的栈顶指针
    private int top2;  // 栈2的栈顶指针

    public MirrorDualStack(int capacity) {
        this.capacity = capacity;
        this.array = new Object[capacity];
        this.top1 = -1;              // 栈1从左边开始
        this.top2 = capacity;        // 栈2从右边开始
    }

    /**
     * 栈1入栈
     */
    public void push1(T element) {
        if (isFull()) {
            throw new RuntimeException(&quot;栈已满&quot;);
        }
        array[++top1] = element;
    }

    /**
     * 栈2入栈
     */
    public void push2(T element) {
        if (isFull()) {
            throw new RuntimeException(&quot;栈已满&quot;);
        }
        array[--top2] = element;
    }

    /**
     * 栈1出栈
     */
    @SuppressWarnings(&quot;unchecked&quot;)
    public T pop1() {
        if (isEmpty1()) {
            throw new RuntimeException(&quot;栈1为空&quot;);
        }
        T element = (T) array[top1];
        array[top1--] = null;
        return element;
    }

    /**
     * 栈2出栈
     */
    @SuppressWarnings(&quot;unchecked&quot;)
    public T pop2() {
        if (isEmpty2()) {
            throw new RuntimeException(&quot;栈2为空&quot;);
        }
        T element = (T) array[top2];
        array[top2++] = null;
        return element;
    }

    /**
     * 检查是否已满
     */
    public boolean isFull() {
        return top1 + 1 == top2;
    }

    /**
     * 检查栈1是否为空
     */
    public boolean isEmpty1() {
        return top1 == -1;
    }

    /**
     * 检查栈2是否为空
     */
    public boolean isEmpty2() {
        return top2 == capacity;
    }

    /**
     * 获取栈1大小
     */
    public int size1() {
        return top1 + 1;
    }

    /**
     * 获取栈2大小
     */
    public int size2() {
        return capacity - top2;
    }

    /**
     * 显示当前状态
     */
    public void showState() {
        System.out.println(&quot;数组状态: &quot; + Arrays.toString(array));
        System.out.println(&quot;top1: &quot; + top1 + &quot;, top2: &quot; + top2);
        System.out.println(&quot;栈1大小: &quot; + size1() + &quot;, 栈2大小: &quot; + size2());
        System.out.println(&quot;剩余空间: &quot; + (top2 - top1 - 1));
    }
}
