先移除旧的A：栈：[&quot;C&quot;]，哈希表：{&quot;C&quot;: 0}
再添加新的A：栈：[&quot;C&quot;, &quot;A&quot;]，哈希表：{&quot;C&quot;: 0, &quot;A&quot;: 1}
2. 状态记录模式
核心思想： 栈存储元素，哈希表记录元素的状态信息
/**
 * 带状态的栈结构
 */
public class StatefulStack&lt;T&gt; {
    private Deque&lt;T&gt; stack;
    private Map&lt;T, ElementState&gt; stateMap;

    public StatefulStack() {
        stack = new ArrayDeque&lt;&gt;();
        stateMap = new HashMap&lt;&gt;();
    }

    /**
     * 元素状态枚举
     */
    public enum ElementState {
        ACTIVE,     // 活跃状态
        PROCESSED,  // 已处理
        MARKED,     // 已标记
        LOCKED      // 锁定状态
    }

    /**
     * 入栈并设置状态
     */
    public void push(T element, ElementState state) {
        stack.push(element);
        stateMap.put(element, state);
    }

    /**
     * 入栈（默认活跃状态）
     */
    public void push(T element) {
        push(element, ElementState.ACTIVE);
    }

    /**
     * 出栈
     */
    public T pop() {
        if (stack.isEmpty()) {
            throw new RuntimeException(&quot;栈为空&quot;);
        }

        T element = stack.pop();
        stateMap.remove(element);
        return element;
    }

    /**
     * 更新元素状态
     */
    public boolean updateState(T element, ElementState newState) {
        if (!stateMap.containsKey(element)) {
            return false;
        }
        stateMap.put(element, newState);
        return true;
    }

    /**
     * 获取元素状态
     */
    public ElementState getState(T element) {
        return stateMap.get(element);
    }

    /**
     * 检查元素是否在栈中且为指定状态
     */
    public boolean isInState(T element, ElementState state) {
        return stateMap.getOrDefault(element, null) == state;
    }

    /**
     * 获取指定状态的所有元素
     */
    public List&lt;T&gt; getElementsByState(ElementState state) {
        return stateMap.entrySet().stream()
                .filter(entry -&gt; entry.getValue() == state)
                .map(Map.Entry::getKey)
                .collect(Collectors.toList());
    }

    /**
     * 弹出指定状态的栈顶元素
     */
    public T popByState(ElementState state) {
        while (!stack.isEmpty()) {
            T top = stack.peek();
            if (stateMap.get(top) == state) {
                return pop();
            } else {
                // 如果栈顶不是目标状态，暂时移除
                T temp = pop();
                // 这里可以根据需求决定如何处理
            }
        }
        return null;
    }
}
3. 频率统计模式
核心思想： 栈维护元素顺序，哈希表统计元素频率
/**
 * 频率统计栈
 */
public class FrequencyStack {
    private Map&lt;Integer, Integer&gt; frequency;      // 元素 -&gt; 频率
    private Map&lt;Integer, Deque&lt;Integer&gt;&gt; groups;  // 频率 -&gt; 该频率的元素栈
    private int maxFrequency;                     // 当前最大频率

    public FrequencyStack() {
        frequency = new HashMap&lt;&gt;();
        groups = new HashMap&lt;&gt;();
        maxFrequency = 0;
    }

    /**
     * 入栈操作
     */
    public void push(int val) {
        // 更新频率
        int freq = frequency.getOrDefault(val, 0) + 1;
        frequency.put(val, freq);

        // 更新最大频率
        maxFrequency = Math.max(maxFrequency, freq);

        // 将元素加入对应频率的栈
        groups.computeIfAbsent(freq, k -&gt; new ArrayDeque&lt;&gt;()).push(val);
    }

    /**
     * 出栈操作（弹出频率最高的元素）
     */
    public int pop() {
        if (maxFrequency == 0) {
            throw new RuntimeException(&quot;栈为空&quot;);
        }

        // 从最高频率栈中弹出元素
        Deque&lt;Integer&gt; maxFreqStack = groups.get(maxFrequency);
        int val = maxFreqStack.pop();

        // 更新频率
        frequency.put(val, frequency.get(val) - 1);

        // 如果最高频率栈为空，降低最大频率
        if (maxFreqStack.isEmpty()) {
            maxFrequency--;
        }

        return val;
    }

    /**
     * 获取元素频率
     */
    public int getFrequency(int val) {
        return frequency.getOrDefault(val, 0);
    }

    /**
     * 获取当前最大频率
     */
    public int getMaxFrequency() {
        return maxFrequency;
    }

    /**
     * 显示当前状态
     */
    public void showState() {
        System.out.println(&quot;频率映射: &quot; + frequency);
        System.out.println(&quot;频率分组: &quot; + groups);
        System.out.println(&quot;最大频率: &quot; + maxFrequency);
    }
}
