class Solution {
    public boolean isValid(String s) {
        int n = s.length();
        if (n % 2 == 1) {
            return false;
        }

        char[] stack = new char[n];
        int top = -1;

        for (char c : s.toCharArray()) {
            if (c == &#039;(&#039; || c == &#039;[&#039; || c == &#039;{&#039;) {
                stack[++top] = c;
            } else {
                if (top == -1) {
                    return false;
                }

                char left = stack[top--];
                if ((c == &#039;)&#039; &amp;&amp; left != &#039;(&#039;) ||
                    (c == &#039;]&#039; &amp;&amp; left != &#039;[&#039;) ||
                    (c == &#039;}&#039; &amp;&amp; left != &#039;{&#039;)) {
                    return false;
                }
            }
        }

        return top == -1;
    }
}
