/**
 * 前序遍历：根 → 左 → 右
 */
public class PreorderTraversal {

    // 递归解法
    public List&lt;Integer&gt; preorderTraversalRecursive(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        preorderHelper(root, result);
        return result;
    }

    private void preorderHelper(TreeNode node, List&lt;Integer&gt; result) {
        if (node != null) {
            result.add(node.val);              // 访问根节点
            preorderHelper(node.left, result); // 递归左子树
            preorderHelper(node.right, result);// 递归右子树
        }
    }

    // 迭代解法
    public List&lt;Integer&gt; preorderTraversalIterative(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            result.add(node.val);

            // 先压右子树，再压左子树（栈是后进先出）
            if (node.right != null) {
                stack.push(node.right);
            }
            if (node.left != null) {
                stack.push(node.left);
            }
        }

        return result;
    }
}
2. LeetCode 145 - 二叉树的后序遍历
/**
 * 后序遍历：左 → 右 → 根
 */
public class PostorderTraversal {

    // 递归解法
    public List&lt;Integer&gt; postorderTraversalRecursive(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        postorderHelper(root, result);
        return result;
    }

    private void postorderHelper(TreeNode node, List&lt;Integer&gt; result) {
        if (node != null) {
            postorderHelper(node.left, result); // 递归左子树
            postorderHelper(node.right, result);// 递归右子树
            result.add(node.val);               // 访问根节点
        }
    }

    // 迭代解法（双栈）
    public List&lt;Integer&gt; postorderTraversalIterative(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; stack1 = new ArrayDeque&lt;&gt;();
        Deque&lt;TreeNode&gt; stack2 = new ArrayDeque&lt;&gt;();

        stack1.push(root);

        while (!stack1.isEmpty()) {
            TreeNode node = stack1.pop();
            stack2.push(node);

            if (node.left != null) {
                stack1.push(node.left);
            }
            if (node.right != null) {
                stack1.push(node.right);
            }
        }

        while (!stack2.isEmpty()) {
            result.add(stack2.pop().val);
        }

        return result;
    }

    // 迭代解法（单栈+状态）
    public List&lt;Integer&gt; postorderTraversalSingleStack(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();
        TreeNode lastVisited = null;
        TreeNode current = root;

        while (current != null || !stack.isEmpty()) {
            if (current != null) {
                stack.push(current);
                current = current.left;
            } else {
                TreeNode peekNode = stack.peek();
                if (peekNode.right != null &amp;&amp; lastVisited != peekNode.right) {
                    current = peekNode.right;
                } else {
                    result.add(peekNode.val);
                    lastVisited = stack.pop();
                }
            }
        }

        return result;
    }
}
