/**
 * N皇后问题的栈模拟实现
 */
public class NQueensStackSimulation {

    public List&lt;List&lt;String&gt;&gt; solveNQueens(int n) {
        List&lt;List&lt;String&gt;&gt; result = new ArrayList&lt;&gt;();

        Deque&lt;BacktrackState&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(new BacktrackState(new int[n], 0, BacktrackState.Phase.ENTER));

        while (!stack.isEmpty()) {
            BacktrackState current = stack.peek();

            switch (current.phase) {
                case ENTER:
                    if (current.row == n) {
                        // 找到一个解
                        result.add(generateBoard(current.queens, n));
                        stack.pop();
                    } else {
                        current.phase = BacktrackState.Phase.TRY_POSITION;
                        current.col = 0;
                    }
                    break;

                case TRY_POSITION:
                    if (current.col &lt; n) {
                        if (isValid(current.queens, current.row, current.col)) {
                            // 尝试在当前位置放置皇后
                            current.queens[current.row] = current.col;
                            current.phase = BacktrackState.Phase.RECURSE;

                            // 模拟递归调用下一行
                            int[] newQueens = current.queens.clone();
                            stack.push(new BacktrackState(newQueens, current.row + 1, 
                                                        BacktrackState.Phase.ENTER));
                        } else {
                            // 当前位置无效，尝试下一列
                            current.col++;
                        }
                    } else {
                        // 当前行所有位置都尝试过，回溯
                        stack.pop();
                    }
                    break;

                case RECURSE:
                    // 子问题处理完毕，尝试下一列
                    current.col++;
                    current.phase = BacktrackState.Phase.TRY_POSITION;
                    break;
            }
        }

        return result;
    }

    private boolean isValid(int[] queens, int row, int col) {
        for (int i = 0; i &lt; row; i++) {
            if (queens[i] == col || 
                queens[i] - i == col - row || 
                queens[i] + i == col + row) {
                return false;
            }
        }
        return true;
    }

    private List&lt;String&gt; generateBoard(int[] queens, int n) {
        List&lt;String&gt; board = new ArrayList&lt;&gt;();
        for (int i = 0; i &lt; n; i++) {
            char[] row = new char[n];
            Arrays.fill(row, &#039;.&#039;);
            row[queens[i]] = &#039;Q&#039;;
            board.add(new String(row));
        }
        return board;
    }

    static class BacktrackState {
        enum Phase { ENTER, TRY_POSITION, RECURSE }

        int[] queens;
        int row;
        int col;
        Phase phase;

        BacktrackState(int[] queens, int row, Phase phase) {
            this.queens = queens;
            this.row = row;
            this.phase = phase;
        }
    }
}
