/**
 * 递归栈模拟通用模板
 */
public class RecursiveStackTemplate&lt;T, R&gt; {

    public R simulate(T initialInput) {
        Deque&lt;SimulationState&lt;T, R&gt;&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(createInitialState(initialInput));

        R result = null;

        while (!stack.isEmpty()) {
            SimulationState&lt;T, R&gt; current = stack.peek();

            switch (current.getPhase()) {
                case ENTER:
                    if (isBaseCase(current)) {
                        current.setResult(handleBaseCase(current));
                        current.setPhase(Phase.RETURN);
                    } else {
                        current.setPhase(Phase.PROCESS);
                        // 添加子问题到栈中
                        addSubproblems(stack, current);
                    }
                    break;

                case PROCESS:
                    // 处理子问题返回的结果
                    processSubresults(current);
                    current.setPhase(Phase.RETURN);
                    break;

                case RETURN:
                    SimulationState&lt;T, R&gt; completed = stack.pop();
                    if (!stack.isEmpty()) {
                        // 将结果传递给父问题
                        propagateResult(stack.peek(), completed);
                    } else {
                        // 最终结果
                        result = completed.getResult();
                    }
                    break;
            }
        }

        return result;
    }

    // 抽象方法，由具体实现类重写
    protected abstract SimulationState&lt;T, R&gt; createInitialState(T input);
    protected abstract boolean isBaseCase(SimulationState&lt;T, R&gt; state);
    protected abstract R handleBaseCase(SimulationState&lt;T, R&gt; state);
    protected abstract void addSubproblems(Deque&lt;SimulationState&lt;T, R&gt;&gt; stack, 
                                         SimulationState&lt;T, R&gt; current);
    protected abstract void processSubresults(SimulationState&lt;T, R&gt; state);
    protected abstract void propagateResult(SimulationState&lt;T, R&gt; parent, 
                                          SimulationState&lt;T, R&gt; child);

    enum Phase { ENTER, PROCESS, RETURN }

    static abstract class SimulationState&lt;T, R&gt; {
        protected Phase phase;
        protected R result;

        public Phase getPhase() { return phase; }
        public void setPhase(Phase phase) { this.phase = phase; }
        public R getResult() { return result; }
        public void setResult(R result) { this.result = result; }
    }
}
