方法一：单栈法（推荐）
public class Solution {
    public int calculate(String s) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        int result = 0;
        int sign = 1;  // 1表示正号，-1表示负号

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                // 读取完整的数字
                int num = 0;
                while (i &lt; s.length() &amp;&amp; Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - &#039;0&#039;);
                    i++;
                }
                i--; // 回退一位，因为for循环会自动i++

                // 将数字加到结果中
                result += sign * num;

            } else if (c == &#039;+&#039;) {
                sign = 1;
            } else if (c == &#039;-&#039;) {
                sign = -1;
            } else if (c == &#039;(&#039;) {
                // 遇到左括号，保存当前状态到栈中
                stack.push(result);  // 保存当前结果
                stack.push(sign);    // 保存当前符号

                // 重置状态，开始新的计算
                result = 0;
                sign = 1;
            } else if (c == &#039;)&#039;) {
                // 遇到右括号，恢复之前的状态
                int prevSign = stack.pop();    // 弹出之前的符号
                int prevResult = stack.pop();  // 弹出之前的结果

                // 合并结果：之前的结果 + 之前的符号 * 当前结果
                result = prevResult + prevSign * result;
            }
            // 忽略空格
        }

        return result;
    }
}
方法二：双栈法
public class SolutionTwoStacks {
    public int calculate(String s) {
        Deque&lt;Integer&gt; nums = new ArrayDeque&lt;&gt;();
        Deque&lt;Character&gt; ops = new ArrayDeque&lt;&gt;();

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (c == &#039; &#039;) continue;

            if (Character.isDigit(c)) {
                // 读取完整数字
                int num = 0;
                while (i &lt; s.length() &amp;&amp; Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - &#039;0&#039;);
                    i++;
                }
                i--; // 回退
                nums.push(num);

            } else if (c == &#039;(&#039;) {
                ops.push(c);

            } else if (c == &#039;)&#039;) {
                // 计算直到遇到左括号
                while (!ops.isEmpty() &amp;&amp; ops.peek() != &#039;(&#039;) {
                    calculate(nums, ops);
                }
                ops.pop(); // 弹出左括号

            } else if (c == &#039;+&#039; || c == &#039;-&#039;) {
                // 处理同级或更高优先级的操作符
                while (!ops.isEmpty() &amp;&amp; ops.peek() != &#039;(&#039;) {
                    calculate(nums, ops);
                }
                ops.push(c);
            }
        }

        // 处理剩余的操作符
        while (!ops.isEmpty()) {
            calculate(nums, ops);
        }

        return nums.pop();
    }

    private void calculate(Deque&lt;Integer&gt; nums, Deque&lt;Character&gt; ops) {
        if (nums.size() &lt; 2 || ops.isEmpty()) return;

        int num2 = nums.pop();
        int num1 = nums.pop();
        char op = ops.pop();

        int result = (op == &#039;+&#039;) ? num1 + num2 : num1 - num2;
        nums.push(result);
    }
}
方法三：递归下降解析
public class SolutionRecursive {

    private int index = 0;

    public int calculate(String s) {
        index = 0;
        return parseExpression(s);
    }

    private int parseExpression(String s) {
        int result = parseTerm(s);

        while (index &lt; s.length()) {
            skipWhitespace(s);
            if (index &gt;= s.length()) break;

            char op = s.charAt(index);
            if (op == &#039;+&#039; || op == &#039;-&#039;) {
                index++;
                int term = parseTerm(s);
                result = (op == &#039;+&#039;) ? result + term : result - term;
            } else {
                break;
            }
        }

        return result;
    }

    private int parseTerm(String s) {
        skipWhitespace(s);

        if (index &gt;= s.length()) return 0;

        char c = s.charAt(index);

        if (c == &#039;(&#039;) {
            index++; // 跳过 &#039;(&#039;
            int result = parseExpression(s);
            skipWhitespace(s);
            index++; // 跳过 &#039;)&#039;
            return result;
        } else if (c == &#039;-&#039;) {
            index++; // 跳过 &#039;-&#039;
            return -parseTerm(s);
        } else if (c == &#039;+&#039;) {
            index++; // 跳过 &#039;+&#039;
            return parseTerm(s);
        } else if (Character.isDigit(c)) {
            return parseNumber(s);
        }

        return 0;
    }

    private int parseNumber(String s) {
        int num = 0;
        while (index &lt; s.length() &amp;&amp; Character.isDigit(s.charAt(index))) {
            num = num * 10 + (s.charAt(index) - &#039;0&#039;);
            index++;
        }
        return num;
    }

    private void skipWhitespace(String s) {
        while (index &lt; s.length() &amp;&amp; s.charAt(index) == &#039; &#039;) {
            index++;
        }
    }
}
方法四：状态机解法
public class SolutionStateMachine {

    enum State {
        EXPECT_NUMBER,    // 期待数字
        EXPECT_OPERATOR,  // 期待操作符
        IN_NUMBER,        // 正在读取数字
        IN_PARENTHESES    // 在括号内
    }

    public int calculate(String s) {
        Deque&lt;Integer&gt; values = new ArrayDeque&lt;&gt;();
        Deque&lt;Character&gt; operators = new ArrayDeque&lt;&gt;();

        State state = State.EXPECT_NUMBER;
        int currentNumber = 0;

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (c == &#039; &#039;) continue;

            switch (state) {
                case EXPECT_NUMBER:
                    if (Character.isDigit(c)) {
                        currentNumber = c - &#039;0&#039;;
                        state = State.IN_NUMBER;
                    } else if (c == &#039;(&#039;) {
                        operators.push(c);
                    } else if (c == &#039;-&#039;) {
                        // 一元负号
                        operators.push(c);
                    } else if (c == &#039;+&#039;) {
                        // 一元正号，忽略
                    }
                    break;

                case IN_NUMBER:
                    if (Character.isDigit(c)) {
                        currentNumber = currentNumber * 10 + (c - &#039;0&#039;);
                    } else {
                        values.push(currentNumber);
                        currentNumber = 0;
                        state = State.EXPECT_OPERATOR;
                        i--; // 重新处理当前字符
                    }
                    break;

                case EXPECT_OPERATOR:
                    if (c == &#039;+&#039; || c == &#039;-&#039;) {
                        processOperators(values, operators, c);
                        operators.push(c);
                        state = State.EXPECT_NUMBER;
                    } else if (c == &#039;)&#039;) {
                        processUntilLeftParen(values, operators);
                    } else if (c == &#039;(&#039;) {
                        operators.push(c);
                        state = State.EXPECT_NUMBER;
                    }
                    break;
            }
        }

        // 处理最后一个数字
        if (state == State.IN_NUMBER) {
            values.push(currentNumber);
        }

        // 处理剩余操作符
        while (!operators.isEmpty()) {
            processOperator(values, operators);
        }

        return values.pop();
    }

    private void processOperators(Deque&lt;Integer&gt; values, Deque&lt;Character&gt; operators, char newOp) {
        while (!operators.isEmpty() &amp;&amp; operators.peek() != &#039;(&#039; &amp;&amp; 
               getPrecedence(operators.peek()) &gt;= getPrecedence(newOp)) {
            processOperator(values, operators);
        }
    }

    private void processUntilLeftParen(Deque&lt;Integer&gt; values, Deque&lt;Character&gt; operators) {
        while (!operators.isEmpty() &amp;&amp; operators.peek() != &#039;(&#039;) {
            processOperator(values, operators);
        }
        if (!operators.isEmpty()) {
            operators.pop(); // 弹出 &#039;(&#039;
        }
    }

    private void processOperator(Deque&lt;Integer&gt; values, Deque&lt;Character&gt; operators) {
        if (operators.isEmpty()) return;

        char op = operators.pop();

        if (op == &#039;-&#039; &amp;&amp; values.size() == 1) {
            // 一元负号
            int value = values.pop();
            values.push(-value);
        } else if (values.size() &gt;= 2) {
            // 二元操作符
            int right = values.pop();
            int left = values.pop();
            int result = (op == &#039;+&#039;) ? left + right : left - right;
            values.push(result);
        }
    }

    private int getPrecedence(char op) {
        return (op == &#039;+&#039; || op == &#039;-&#039;) ? 1 : 0;
    }
}
