/**
 * 基本计算器 II - 支持 +, -, *, / 运算
 */
public class BasicCalculatorII {

    public int calculate(String s) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        char operation = &#039;+&#039;;
        int num = 0;

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                num = num * 10 + (c - &#039;0&#039;);
            }

            if (!Character.isDigit(c) &amp;&amp; c != &#039; &#039; || i == s.length() - 1) {
                switch (operation) {
                    case &#039;+&#039;:
                        stack.push(num);
                        break;
                    case &#039;-&#039;:
                        stack.push(-num);
                        break;
                    case &#039;*&#039;:
                        stack.push(stack.pop() * num);
                        break;
                    case &#039;/&#039;:
                        stack.push(stack.pop() / num);
                        break;
                }
                operation = c;
                num = 0;
            }
        }

        int result = 0;
        while (!stack.isEmpty()) {
            result += stack.pop();
        }

        return result;
    }
}
