📚 表达式栈的基本概念
什么是表达式栈？
表达式栈（Expression Stack）是专门用于处理数学表达式求值、转换和解析的栈结构。它是编译器、计算器和数学表达式处理系统的核心组件。
表达式的三种表示法
中缀表达式（Infix）：   3 + 4 * 2
前缀表达式（Prefix）：  + 3 * 4 2
后缀表达式（Postfix）： 3 4 2 * +

转换关系：
中缀 → 后缀 → 求值
  ↓      ↑
  前缀 ←──┘
为什么需要表达式栈？

运算符优先级处理：自动处理复杂的优先级规则
括号匹配：正确处理嵌套的括号结构
表达式转换：在不同表示法间转换
高效求值：避免重复解析，提高计算效率

🔧 表达式栈的核心算法
1. 中缀表达式转后缀表达式（调度场算法）
核心思想： 使用操作符栈来处理运算符的优先级和结合性
/**
 * 中缀表达式转后缀表达式
 * 使用Dijkstra的调度场算法（Shunting Yard Algorithm）
 */
public class InfixToPostfixConverter {

    // 运算符优先级映射
    private static final Map&lt;Character, Integer&gt; PRECEDENCE = Map.of(
        &#039;+&#039;, 1, &#039;-&#039;, 1,
        &#039;*&#039;, 2, &#039;/&#039;, 2,
        &#039;^&#039;, 3
    );

    // 右结合运算符
    private static final Set&lt;Character&gt; RIGHT_ASSOCIATIVE = Set.of(&#039;^&#039;);

    public String infixToPostfix(String infix) {
        StringBuilder postfix = new StringBuilder();
        Deque&lt;Character&gt; operatorStack = new ArrayDeque&lt;&gt;();

        for (char token : infix.toCharArray()) {
            if (Character.isWhitespace(token)) {
                continue;
            }

            if (Character.isDigit(token) || Character.isLetter(token)) {
                // 操作数直接输出
                postfix.append(token).append(&#039; &#039;);

            } else if (token == &#039;(&#039;) {
                // 左括号入栈
                operatorStack.push(token);

            } else if (token == &#039;)&#039;) {
                // 右括号：弹出直到遇到左括号
                while (!operatorStack.isEmpty() &amp;&amp; operatorStack.peek() != &#039;(&#039;) {
                    postfix.append(operatorStack.pop()).append(&#039; &#039;);
                }
                operatorStack.pop(); // 弹出左括号

            } else if (isOperator(token)) {
                // 运算符：根据优先级和结合性处理
                while (!operatorStack.isEmpty() &amp;&amp; 
                       shouldPopOperator(operatorStack.peek(), token)) {
                    postfix.append(operatorStack.pop()).append(&#039; &#039;);
                }
                operatorStack.push(token);
            }
        }

        // 弹出剩余的运算符
        while (!operatorStack.isEmpty()) {
            postfix.append(operatorStack.pop()).append(&#039; &#039;);
        }

        return postfix.toString().trim();
    }

    private boolean isOperator(char c) {
        return PRECEDENCE.containsKey(c);
    }

    private boolean shouldPopOperator(char stackTop, char current) {
        if (stackTop == &#039;(&#039;) return false;

        int stackPrec = PRECEDENCE.getOrDefault(stackTop, 0);
        int currentPrec = PRECEDENCE.getOrDefault(current, 0);

        // 左结合：栈顶优先级 &gt;= 当前优先级
        // 右结合：栈顶优先级 &gt; 当前优先级
        if (RIGHT_ASSOCIATIVE.contains(current)) {
            return stackPrec &gt; currentPrec;
        } else {
            return stackPrec &gt;= currentPrec;
        }
    }
}
算法执行过程图解：
转换表达式：3 + 4 * 2 - 1

步骤1：读取 &#039;3&#039;
输出：3 
栈：[]

步骤2：读取 &#039;+&#039;
输出：3 
栈：[+]

步骤3：读取 &#039;4&#039;
输出：3 4 
栈：[+]

步骤4：读取 &#039;*&#039;
输出：3 4 
栈：[+, *]  (* 优先级高于 +)

步骤5：读取 &#039;2&#039;
输出：3 4 2 
栈：[+, *]

步骤6：读取 &#039;-&#039;
输出：3 4 2 * +   (弹出 * 和 +，因为 - 优先级不高于它们)
栈：[-]

步骤7：读取 &#039;1&#039;
输出：3 4 2 * + 1 
栈：[-]

步骤8：表达式结束
输出：3 4 2 * + 1 -   (弹出剩余的 -)
栈：[]

最终结果：3 4 2 * + 1 -
2. 后缀表达式求值
核心思想： 使用操作数栈，遇到运算符时弹出操作数进行计算
/**
 * 后缀表达式求值器
 */
public class PostfixEvaluator {

    public double evaluate(String postfix) {
        Deque&lt;Double&gt; operandStack = new ArrayDeque&lt;&gt;();
        String[] tokens = postfix.split(&quot;\\s+&quot;);

        for (String token : tokens) {
            if (isNumber(token)) {
                // 操作数入栈
                operandStack.push(Double.parseDouble(token));

            } else if (isOperator(token.charAt(0))) {
                // 运算符：弹出操作数计算
                if (operandStack.size() &lt; 2) {
                    throw new IllegalArgumentException(&quot;Invalid expression&quot;);
                }

                double operand2 = operandStack.pop();
                double operand1 = operandStack.pop();
                double result = performOperation(operand1, operand2, token.charAt(0));

                operandStack.push(result);
            }
        }

        if (operandStack.size() != 1) {
            throw new IllegalArgumentException(&quot;Invalid expression&quot;);
        }

        return operandStack.pop();
    }

    private boolean isNumber(String token) {
        try {
            Double.parseDouble(token);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private boolean isOperator(char c) {
        return &quot;+-*/^&quot;.indexOf(c) != -1;
    }

    private double performOperation(double operand1, double operand2, char operator) {
        switch (operator) {
            case &#039;+&#039;: return operand1 + operand2;
            case &#039;-&#039;: return operand1 - operand2;
            case &#039;*&#039;: return operand1 * operand2;
            case &#039;/&#039;: 
                if (operand2 == 0) throw new ArithmeticException(&quot;Division by zero&quot;);
                return operand1 / operand2;
            case &#039;^&#039;: return Math.pow(operand1, operand2);
            default: throw new IllegalArgumentException(&quot;Unknown operator: &quot; + operator);
        }
    }
}
求值过程图解：
计算后缀表达式：3 4 2 * + 1 -

步骤1：读取 &#039;3&#039;
栈：[3]

步骤2：读取 &#039;4&#039;
栈：[3, 4]

步骤3：读取 &#039;2&#039;
栈：[3, 4, 2]

步骤4：读取 &#039;*&#039;
弹出 2 和 4，计算 4 * 2 = 8，结果入栈
栈：[3, 8]

步骤5：读取 &#039;+&#039;
弹出 8 和 3，计算 3 + 8 = 11，结果入栈
栈：[11]

步骤6：读取 &#039;1&#039;
栈：[11, 1]

步骤7：读取 &#039;-&#039;
弹出 1 和 11，计算 11 - 1 = 10，结果入栈
栈：[10]

最终结果：10
3. 中缀表达式直接求值
核心思想： 使用两个栈（操作数栈和运算符栈）同时处理
/**
 * 中缀表达式直接求值器
 */
public class InfixEvaluator {

    private static final Map&lt;Character, Integer&gt; PRECEDENCE = Map.of(
        &#039;+&#039;, 1, &#039;-&#039;, 1,
        &#039;*&#039;, 2, &#039;/&#039;, 2,
        &#039;^&#039;, 3
    );

    public double evaluate(String expression) {
        Deque&lt;Double&gt; operandStack = new ArrayDeque&lt;&gt;();
        Deque&lt;Character&gt; operatorStack = new ArrayDeque&lt;&gt;();

        for (int i = 0; i &lt; expression.length(); i++) {
            char c = expression.charAt(i);

            if (Character.isWhitespace(c)) {
                continue;
            }

            if (Character.isDigit(c)) {
                // 解析完整的数字
                StringBuilder number = new StringBuilder();
                while (i &lt; expression.length() &amp;&amp; 
                       (Character.isDigit(expression.charAt(i)) || 
                        expression.charAt(i) == &#039;.&#039;)) {
                    number.append(expression.charAt(i++));
                }
                i--; // 回退一位
                operandStack.push(Double.parseDouble(number.toString()));

            } else if (c == &#039;(&#039;) {
                operatorStack.push(c);

            } else if (c == &#039;)&#039;) {
                // 计算直到遇到左括号
                while (!operatorStack.isEmpty() &amp;&amp; operatorStack.peek() != &#039;(&#039;) {
                    performOperation(operandStack, operatorStack);
                }
                operatorStack.pop(); // 弹出左括号

            } else if (isOperator(c)) {
                // 处理运算符优先级
                while (!operatorStack.isEmpty() &amp;&amp; 
                       hasHigherPrecedence(operatorStack.peek(), c)) {
                    performOperation(operandStack, operatorStack);
                }
                operatorStack.push(c);
            }
        }

        // 处理剩余的运算符
        while (!operatorStack.isEmpty()) {
            performOperation(operandStack, operatorStack);
        }

        return operandStack.pop();
    }

    private void performOperation(Deque&lt;Double&gt; operandStack, 
                                 Deque&lt;Character&gt; operatorStack) {
        if (operandStack.size() &lt; 2 || operatorStack.isEmpty()) {
            throw new IllegalArgumentException(&quot;Invalid expression&quot;);
        }

        double operand2 = operandStack.pop();
        double operand1 = operandStack.pop();
        char operator = operatorStack.pop();

        double result = calculate(operand1, operand2, operator);
        operandStack.push(result);
    }

    private double calculate(double operand1, double operand2, char operator) {
        switch (operator) {
            case &#039;+&#039;: return operand1 + operand2;
            case &#039;-&#039;: return operand1 - operand2;
            case &#039;*&#039;: return operand1 * operand2;
            case &#039;/&#039;: 
                if (operand2 == 0) throw new ArithmeticException(&quot;Division by zero&quot;);
                return operand1 / operand2;
            case &#039;^&#039;: return Math.pow(operand1, operand2);
            default: throw new IllegalArgumentException(&quot;Unknown operator: &quot; + operator);
        }
    }

    private boolean isOperator(char c) {
        return PRECEDENCE.containsKey(c);
    }

    private boolean hasHigherPrecedence(char stackTop, char current) {
        if (stackTop == &#039;(&#039;) return false;

        int stackPrec = PRECEDENCE.getOrDefault(stackTop, 0);
        int currentPrec = PRECEDENCE.getOrDefault(current, 0);

        return stackPrec &gt;= currentPrec;
    }
}
4. 带函数的表达式求值
/**
 * 支持函数的表达式求值器
 */
public class FunctionExpressionEvaluator {

    private static final Map&lt;String, Function&lt;Double, Double&gt;&gt; FUNCTIONS = Map.of(
        &quot;sin&quot;, Math::sin,
        &quot;cos&quot;, Math::cos,
        &quot;tan&quot;, Math::tan,
        &quot;log&quot;, Math::log,
        &quot;sqrt&quot;, Math::sqrt,
        &quot;abs&quot;, Math::abs
    );

    public double evaluate(String expression) {
        Deque&lt;Double&gt; operandStack = new ArrayDeque&lt;&gt;();
        Deque&lt;Object&gt; operatorStack = new ArrayDeque&lt;&gt;(); // 可以存储运算符或函数

        for (int i = 0; i &lt; expression.length(); i++) {
            char c = expression.charAt(i);

            if (Character.isWhitespace(c)) {
                continue;
            }

            if (Character.isDigit(c)) {
                // 解析数字
                i = parseNumber(expression, i, operandStack) - 1;

            } else if (Character.isLetter(c)) {
                // 解析函数名
                i = parseFunction(expression, i, operatorStack) - 1;

            } else if (c == &#039;(&#039;) {
                operatorStack.push(c);

            } else if (c == &#039;)&#039;) {
                // 处理括号内的表达式
                while (!operatorStack.isEmpty() &amp;&amp; 
                       !operatorStack.peek().equals(&#039;(&#039;)) {
                    performOperation(operandStack, operatorStack);
                }
                operatorStack.pop(); // 弹出左括号

                // 检查是否有函数需要执行
                if (!operatorStack.isEmpty() &amp;&amp; 
                    operatorStack.peek() instanceof String) {
                    performFunction(operandStack, operatorStack);
                }

            } else if (isOperator(c)) {
                while (!operatorStack.isEmpty() &amp;&amp; 
                       hasHigherPrecedence(operatorStack.peek(), c)) {
                    performOperation(operandStack, operatorStack);
                }
                operatorStack.push(c);
            }
        }

        while (!operatorStack.isEmpty()) {
            performOperation(operandStack, operatorStack);
        }

        return operandStack.pop();
    }

    private int parseNumber(String expression, int start, Deque&lt;Double&gt; operandStack) {
        StringBuilder number = new StringBuilder();
        int i = start;

        while (i &lt; expression.length() &amp;&amp; 
               (Character.isDigit(expression.charAt(i)) || 
                expression.charAt(i) == &#039;.&#039;)) {
            number.append(expression.charAt(i++));
        }

        operandStack.push(Double.parseDouble(number.toString()));
        return i;
    }

    private int parseFunction(String expression, int start, Deque&lt;Object&gt; operatorStack) {
        StringBuilder function = new StringBuilder();
        int i = start;

        while (i &lt; expression.length() &amp;&amp; Character.isLetter(expression.charAt(i))) {
            function.append(expression.charAt(i++));
        }

        String funcName = function.toString();
        if (FUNCTIONS.containsKey(funcName)) {
            operatorStack.push(funcName);
        } else {
            throw new IllegalArgumentException(&quot;Unknown function: &quot; + funcName);
        }

        return i;
    }

    private void performFunction(Deque&lt;Double&gt; operandStack, Deque&lt;Object&gt; operatorStack) {
        if (operandStack.isEmpty() || operatorStack.isEmpty()) {
            throw new IllegalArgumentException(&quot;Invalid function call&quot;);
        }

        String funcName = (String) operatorStack.pop();
        double operand = operandStack.pop();

        Function&lt;Double, Double&gt; function = FUNCTIONS.get(funcName);
        double result = function.apply(operand);

        operandStack.push(result);
    }

    private void performOperation(Deque&lt;Double&gt; operandStack, Deque&lt;Object&gt; operatorStack) {
        if (operandStack.size() &lt; 2 || operatorStack.isEmpty()) {
            return;
        }

        Object op = operatorStack.pop();
        if (op instanceof Character) {
            double operand2 = operandStack.pop();
            double operand1 = operandStack.pop();
            char operator = (Character) op;

            double result = calculate(operand1, operand2, operator);
            operandStack.push(result);
        }
    }

    private double calculate(double operand1, double operand2, char operator) {
        switch (operator) {
            case &#039;+&#039;: return operand1 + operand2;
            case &#039;-&#039;: return operand1 - operand2;
            case &#039;*&#039;: return operand1 * operand2;
            case &#039;/&#039;: 
                if (operand2 == 0) throw new ArithmeticException(&quot;Division by zero&quot;);
                return operand1 / operand2;
            case &#039;^&#039;: return Math.pow(operand1, operand2);
            default: throw new IllegalArgumentException(&quot;Unknown operator: &quot; + operator);
        }
    }

    private boolean isOperator(char c) {
        return &quot;+-*/^&quot;.indexOf(c) != -1;
    }

    private boolean hasHigherPrecedence(Object stackTop, char current) {
        if (!(stackTop instanceof Character) || stackTop.equals(&#039;(&#039;)) {
            return false;
        }

        char stackOp = (Character) stackTop;
        return getPrecedence(stackOp) &gt;= getPrecedence(current);
    }

    private int getPrecedence(char operator) {
        switch (operator) {
            case &#039;+&#039;: case &#039;-&#039;: return 1;
            case &#039;*&#039;: case &#039;/&#039;: return 2;
            case &#039;^&#039;: return 3;
            default: return 0;
        }
    }
}
