💻 代码实现
方法一：状态栈法（推荐）
public class Solution {
    public String decodeString(String s) {
        Deque&lt;String&gt; stringStack = new ArrayDeque&lt;&gt;();  // 存储字符串状态
        Deque&lt;Integer&gt; numStack = new ArrayDeque&lt;&gt;();    // 存储数字状态

        StringBuilder currentStr = new StringBuilder();
        int currentNum = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                // 累积数字（可能是多位数）
                currentNum = currentNum * 10 + (c - &#039;0&#039;);

            } else if (c == &#039;[&#039;) {
                // 遇到左括号，保存当前状态
                stringStack.push(currentStr.toString());
                numStack.push(currentNum);

                // 重置状态，开始新的解码
                currentStr = new StringBuilder();
                currentNum = 0;

            } else if (c == &#039;]&#039;) {
                // 遇到右括号，恢复之前状态并构建结果
                String prevStr = stringStack.pop();
                int repeatCount = numStack.pop();

                // 构建重复字符串
                StringBuilder temp = new StringBuilder(prevStr);
                for (int i = 0; i &lt; repeatCount; i++) {
                    temp.append(currentStr);
                }

                currentStr = temp;

            } else {
                // 普通字符，直接添加
                currentStr.append(c);
            }
        }

        return currentStr.toString();
    }
}
方法二：单栈优化版
public class SolutionOptimized {

    static class State {
        StringBuilder str;
        int num;

        State(StringBuilder str, int num) {
            this.str = str;
            this.num = num;
        }
    }

    public String decodeString(String s) {
        Deque&lt;State&gt; stack = new ArrayDeque&lt;&gt;();
        StringBuilder currentStr = new StringBuilder();
        int currentNum = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                currentNum = currentNum * 10 + (c - &#039;0&#039;);

            } else if (c == &#039;[&#039;) {
                // 保存当前状态
                stack.push(new State(currentStr, currentNum));
                currentStr = new StringBuilder();
                currentNum = 0;

            } else if (c == &#039;]&#039;) {
                // 恢复状态并构建结果
                State prevState = stack.pop();
                StringBuilder temp = new StringBuilder(prevState.str);

                // 重复当前字符串
                for (int i = 0; i &lt; prevState.num; i++) {
                    temp.append(currentStr);
                }

                currentStr = temp;

            } else {
                currentStr.append(c);
            }
        }

        return currentStr.toString();
    }
}
方法三：递归解法
public class SolutionRecursive {

    private int index = 0;

    public String decodeString(String s) {
        index = 0;
        return decode(s);
    }

    private String decode(String s) {
        StringBuilder result = new StringBuilder();
        int num = 0;

        while (index &lt; s.length()) {
            char c = s.charAt(index++);

            if (Character.isDigit(c)) {
                num = num * 10 + (c - &#039;0&#039;);

            } else if (c == &#039;[&#039;) {
                // 递归解码括号内容
                String decoded = decode(s);

                // 重复解码的字符串
                for (int i = 0; i &lt; num; i++) {
                    result.append(decoded);
                }

                num = 0; // 重置数字

            } else if (c == &#039;]&#039;) {
                // 结束当前层递归
                break;

            } else {
                // 普通字符
                result.append(c);
            }
        }

        return result.toString();
    }
}
方法四：字符串替换法（暴力）
public class SolutionBruteForce {

    public String decodeString(String s) {
        // 持续替换直到没有括号
        while (s.contains(&quot;[&quot;)) {
            s = replaceInnermost(s);
        }
        return s;
    }

    private String replaceInnermost(String s) {
        // 找到最内层的括号
        int start = -1;
        for (int i = 0; i &lt; s.length(); i++) {
            if (s.charAt(i) == &#039;[&#039;) {
                start = i;
            } else if (s.charAt(i) == &#039;]&#039;) {
                // 找到对应的数字
                int numStart = start - 1;
                while (numStart &gt;= 0 &amp;&amp; Character.isDigit(s.charAt(numStart))) {
                    numStart--;
                }
                numStart++;

                // 提取数字和字符串
                int num = Integer.parseInt(s.substring(numStart, start));
                String str = s.substring(start + 1, i);

                // 构建重复字符串
                StringBuilder repeated = new StringBuilder();
                for (int j = 0; j &lt; num; j++) {
                    repeated.append(str);
                }

                // 替换原字符串
                return s.substring(0, numStart) + repeated.toString() + s.substring(i + 1);
            }
        }

        return s;
    }
}
方法五：状态机解法
public class SolutionStateMachine {

    enum State {
        READING_CHAR,    // 读取普通字符
        READING_NUMBER,  // 读取数字
        IN_BRACKETS      // 在括号内
    }

    public String decodeString(String s) {
        Deque&lt;StringBuilder&gt; stringStack = new ArrayDeque&lt;&gt;();
        Deque&lt;Integer&gt; numStack = new ArrayDeque&lt;&gt;();

        StringBuilder currentStr = new StringBuilder();
        int currentNum = 0;
        State state = State.READING_CHAR;

        for (char c : s.toCharArray()) {
            switch (state) {
                case READING_CHAR:
                    if (Character.isDigit(c)) {
                        currentNum = c - &#039;0&#039;;
                        state = State.READING_NUMBER;
                    } else {
                        currentStr.append(c);
                    }
                    break;

                case READING_NUMBER:
                    if (Character.isDigit(c)) {
                        currentNum = currentNum * 10 + (c - &#039;0&#039;);
                    } else if (c == &#039;[&#039;) {
                        stringStack.push(currentStr);
                        numStack.push(currentNum);
                        currentStr = new StringBuilder();
                        currentNum = 0;
                        state = State.IN_BRACKETS;
                    }
                    break;

                case IN_BRACKETS:
                    if (Character.isDigit(c)) {
                        currentNum = c - &#039;0&#039;;
                        state = State.READING_NUMBER;
                    } else if (c == &#039;[&#039;) {
                        stringStack.push(currentStr);
                        numStack.push(currentNum);
                        currentStr = new StringBuilder();
                        currentNum = 0;
                    } else if (c == &#039;]&#039;) {
                        StringBuilder prevStr = stringStack.pop();
                        int repeatCount = numStack.pop();

                        for (int i = 0; i &lt; repeatCount; i++) {
                            prevStr.append(currentStr);
                        }

                        currentStr = prevStr;
                        state = stringStack.isEmpty() ? State.READING_CHAR : State.IN_BRACKETS;
                    } else {
                        currentStr.append(c);
                    }
                    break;
            }
        }

        return currentStr.toString();
    }
}
