public class GameStateFactory implements StateFactory&lt;State&gt; {

    @Override
    public State createState(StateType type, Object... params) {
        if (!(type instanceof GameStateType)) {
            throw new IllegalArgumentException(&quot;Invalid state type&quot;);
        }

        GameStateType gameStateType = (GameStateType) type;

        switch (gameStateType) {
            case MAIN_MENU:
                return new MainMenuState();

            case GAME_PLAYING:
                String levelName = params.length &gt; 0 ? (String) params[0] : &quot;default&quot;;
                return new GamePlayingState(levelName);

            case PAUSE_MENU:
                return new PauseMenuState();

            case SETTINGS:
                return new SettingsState();

            case GAME_OVER:
                int score = params.length &gt; 0 ? (Integer) params[0] : 0;
                return new GameOverState(score);

            case LOADING:
                String targetLevel = params.length &gt; 0 ? (String) params[0] : &quot;&quot;;
                return new LoadingState(targetLevel);

            default:
                throw new IllegalArgumentException(&quot;Unknown state type: &quot; + type);
        }
    }
}
