/**
 * 支持异步加载的状态栈
 */
public class AsyncStateStack&lt;T extends State&gt; extends StateStack&lt;T&gt; {

    private final ExecutorService loadingExecutor;
    private final Map&lt;StateType, CompletableFuture&lt;T&gt;&gt; loadingStates;

    public AsyncStateStack(StateFactory&lt;T&gt; stateFactory) {
        super(stateFactory);
        this.loadingExecutor = Executors.newCachedThreadPool();
        this.loadingStates = new ConcurrentHashMap&lt;&gt;();
    }

    /**
     * 异步预加载状态
     */
    public CompletableFuture&lt;T&gt; preloadState(StateType type, Object... params) {
        return loadingStates.computeIfAbsent(type, k -&gt; 
            CompletableFuture.supplyAsync(() -&gt; {
                try {
                    T state = stateFactory.createState(type, params);
                    state.preload(); // 预加载资源
                    return state;
                } catch (Exception e) {
                    throw new RuntimeException(&quot;Failed to preload state: &quot; + type, e);
                }
            }, loadingExecutor)
        );
    }

    /**
     * 异步推入状态
     */
    public CompletableFuture&lt;Void&gt; pushStateAsync(StateType type, Object... params) {
        CompletableFuture&lt;T&gt; stateFuture = loadingStates.get(type);

        if (stateFuture == null) {
            // 如果没有预加载，立即开始加载
            stateFuture = preloadState(type, params);
        }

        return stateFuture.thenAccept(state -&gt; {
            // 在主线程中推入状态
            Platform.runLater(() -&gt; {
                loadingStates.remove(type);
                pushPreloadedState(state);
            });
        });
    }

    private void pushPreloadedState(T state) {
        T currentState = getCurrentState();

        if (currentState != null) {
            currentState.onPause();
        }

        stateStack.push(state);
        state.onEnter(currentState);
        state.onActivate();
    }

    /**
     * 批量预加载状态
     */
    public CompletableFuture&lt;Void&gt; preloadStates(StateType... types) {
        CompletableFuture&lt;?&gt;[] futures = Arrays.stream(types)
            .map(this::preloadState)
            .toArray(CompletableFuture[]::new);

        return CompletableFuture.allOf(futures);
    }

    /**
     * 获取加载进度
     */
    public LoadingProgress getLoadingProgress() {
        int total = loadingStates.size();
        int completed = 0;

        for (CompletableFuture&lt;T&gt; future : loadingStates.values()) {
            if (future.isDone()) {
                completed++;
            }
        }

        return new LoadingProgress(completed, total);
    }

    public void shutdown() {
        loadingExecutor.shutdown();
        try {
            if (!loadingExecutor.awaitTermination(5, TimeUnit.SECONDS)) {
                loadingExecutor.shutdownNow();
            }
        } catch (InterruptedException e) {
            loadingExecutor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static class LoadingProgress {
        private final int completed;
        private final int total;

        public LoadingProgress(int completed, int total) {
            this.completed = completed;
            this.total = total;
        }

        public int getCompleted() { return completed; }
        public int getTotal() { return total; }
        public float getPercentage() { 
            return total == 0 ? 1.0f : (float) completed / total; 
        }
        public boolean isComplete() { return completed == total; }
    }
}
