1. LeetCode 407 - 接雨水 II（困难）
问题描述：
给定一个 m x n 的矩阵，表示一个二维高度图，计算雨后能够接多少雨水。
解题思路：

使用优先队列（最小堆）
从边界开始，逐步向内部扩展
维护当前的水位线

public class Solution407 {
    public int trapRainWater(int[][] heightMap) {
        if (heightMap == null || heightMap.length == 0 || heightMap[0].length == 0) {
            return 0;
        }

        int m = heightMap.length, n = heightMap[0].length;
        boolean[][] visited = new boolean[m][n];
        PriorityQueue&lt;int[]&gt; pq = new PriorityQueue&lt;&gt;((a, b) -&gt; a[2] - b[2]);

        // 将边界加入优先队列
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                    pq.offer(new int[]{i, j, heightMap[i][j]});
                    visited[i][j] = true;
                }
            }
        }

        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int totalWater = 0;

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int x = curr[0], y = curr[1], height = curr[2];

            for (int[] dir : dirs) {
                int nx = x + dir[0], ny = y + dir[1];

                if (nx &gt;= 0 &amp;&amp; nx &lt; m &amp;&amp; ny &gt;= 0 &amp;&amp; ny &lt; n &amp;&amp; !visited[nx][ny]) {
                    totalWater += Math.max(0, height - heightMap[nx][ny]);
                    pq.offer(new int[]{nx, ny, Math.max(height, heightMap[nx][ny])});
                    visited[nx][ny] = true;
                }
            }
        }

        return totalWater;
    }
}
2. LeetCode 11 - 盛最多水的容器（中等）
问题描述：
给定 n 个非负整数，每个数代表坐标中的一个点 (i, ai)。找出其中的两条线，使得它们与 x 轴共同构成的容器可以容纳最多的水。
解题思路：

双指针法
移动较短的边

public class Solution11 {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxWater = 0;

        while (left &lt; right) {
            int width = right - left;
            int minHeight = Math.min(height[left], height[right]);
            maxWater = Math.max(maxWater, width * minHeight);

            if (height[left] &lt; height[right]) {
                left++;
            } else {
                right--;
            }
        }

        return maxWater;
    }
}
3. LeetCode 85 - 最大矩形（困难）
问题描述：
给定一个仅包含 0 和 1 的二维二进制矩阵，找出只包含 1 的最大矩形，并返回其面积。
解题思路：

转化为柱状图中最大矩形问题
对每一行应用单调栈算法

public class Solution85 {
    public int maximalRectangle(char[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0) {
            return 0;
        }

        int m = matrix.length, n = matrix[0].length;
        int[] heights = new int[n];
        int maxArea = 0;

        for (int i = 0; i &lt; m; i++) {
            // 更新高度数组
            for (int j = 0; j &lt; n; j++) {
                if (matrix[i][j] == &#039;1&#039;) {
                    heights[j]++;
                } else {
                    heights[j] = 0;
                }
            }

            // 计算当前行的最大矩形面积
            maxArea = Math.max(maxArea, largestRectangleArea(heights));
        }

        return maxArea;
    }

    private int largestRectangleArea(int[] heights) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        int maxArea = 0;

        for (int i = 0; i &lt;= heights.length; i++) {
            int h = (i == heights.length) ? 0 : heights[i];

            while (!stack.isEmpty() &amp;&amp; h &lt; heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, height * width);
            }

            stack.push(i);
        }

        return maxArea;
    }
}
4. 变形问题：接雨水的变种
4.1 圆形数组接雨水
public class CircularRainWater {
    public int trapCircular(int[] height) {
        if (height == null || height.length &lt;= 2) {
            return 0;
        }

        int n = height.length;
        int totalWater = 0;

        // 找到最高点
        int maxHeight = 0, maxIndex = 0;
        for (int i = 0; i &lt; n; i++) {
            if (height[i] &gt; maxHeight) {
                maxHeight = height[i];
                maxIndex = i;
            }
        }

        // 从最高点开始，分别向两边计算
        totalWater += trapOneSide(height, maxIndex, maxIndex + n, true);

        return totalWater;
    }

    private int trapOneSide(int[] height, int start, int end, boolean forward) {
        int n = height.length;
        int water = 0;
        int maxHeight = 0;

        for (int i = start; i != end; i = (i + 1) % n) {
            maxHeight = Math.max(maxHeight, height[i]);
            water += Math.max(0, maxHeight - height[i]);
        }

        return water;
    }
}
