### 方法二：双指针法

```java
public class SolutionTwoPointers {
    public int trap(int[] height) {
        if (height == null || height.length &lt;= 2) {
            return 0;
        }

        int left = 0, right = height.length - 1;
        int leftMax = 0, rightMax = 0;
        int totalWater = 0;

        while (left &lt; right) {
            if (height[left] &lt; height[right]) {
                // 左边较矮，处理左边
                if (height[left] &gt;= leftMax) {
                    leftMax = height[left];
                } else {
                    totalWater += leftMax - height[left];
                }
                left++;
            } else {
                // 右边较矮，处理右边
                if (height[right] &gt;= rightMax) {
                    rightMax = height[right];
                } else {
                    totalWater += rightMax - height[right];
                }
                right--;
            }
        }

        return totalWater;
    }
}
方法三：动态规划法
public class SolutionDP {
    public int trap(int[] height) {
        if (height == null || height.length &lt;= 2) {
            return 0;
        }

        int n = height.length;
        int[] leftMax = new int[n];   // 每个位置左边的最大高度
        int[] rightMax = new int[n];  // 每个位置右边的最大高度

        // 计算左边最大高度
        leftMax[0] = height[0];
        for (int i = 1; i &lt; n; i++) {
            leftMax[i] = Math.max(leftMax[i - 1], height[i]);
        }

        // 计算右边最大高度
        rightMax[n - 1] = height[n - 1];
        for (int i = n - 2; i &gt;= 0; i--) {
            rightMax[i] = Math.max(rightMax[i + 1], height[i]);
        }

        // 计算雨水量
        int totalWater = 0;
        for (int i = 0; i &lt; n; i++) {
            int waterLevel = Math.min(leftMax[i], rightMax[i]);
            if (waterLevel &gt; height[i]) {
                totalWater += waterLevel - height[i];
            }
        }

        return totalWater;
    }
}
方法四：暴力解法
public class SolutionBruteForce {
    public int trap(int[] height) {
        if (height == null || height.length &lt;= 2) {
            return 0;
        }

        int totalWater = 0;

        // 对每个位置计算能接的雨水
        for (int i = 1; i &lt; height.length - 1; i++) {
            // 找左边最大高度
            int leftMax = 0;
            for (int j = 0; j &lt; i; j++) {
                leftMax = Math.max(leftMax, height[j]);
            }

            // 找右边最大高度
            int rightMax = 0;
            for (int j = i + 1; j &lt; height.length; j++) {
                rightMax = Math.max(rightMax, height[j]);
            }

            // 计算当前位置能接的雨水
            int waterLevel = Math.min(leftMax, rightMax);
            if (waterLevel &gt; height[i]) {
                totalWater += waterLevel - height[i];
            }
        }

        return totalWater;
    }
}
方法五：分治法
public class SolutionDivideConquer {
    public int trap(int[] height) {
        if (height == null || height.length &lt;= 2) {
            return 0;
        }

        return trapHelper(height, 0, height.length - 1);
    }

    private int trapHelper(int[] height, int left, int right) {
        if (left &gt;= right) {
            return 0;
        }

        // 找到最高点
        int maxIndex = left;
        for (int i = left + 1; i &lt;= right; i++) {
            if (height[i] &gt; height[maxIndex]) {
                maxIndex = i;
            }
        }

        // 分别计算左右两部分
        int leftWater = trapOneSide(height, left, maxIndex, true);
        int rightWater = trapOneSide(height, maxIndex, right, false);

        return leftWater + rightWater;
    }

    private int trapOneSide(int[] height, int start, int end, boolean leftToRight) {
        int water = 0;
        int maxHeight = 0;

        if (leftToRight) {
            for (int i = start; i &lt; end; i++) {
                maxHeight = Math.max(maxHeight, height[i]);
                water += Math.max(0, maxHeight - height[i]);
            }
        } else {
            for (int i = end; i &gt; start; i--) {
                maxHeight = Math.max(maxHeight, height[i]);
                water += Math.max(0, maxHeight - height[i]);
            }
        }

        return water;
    }
}
