性能测试代码
public class StackPerformanceTest {
    public static void testTraversalPerformance() {
        TreeNode root = buildLargeTree(10000); // 构建大型测试树

        // 测试Stack性能
        long start = System.nanoTime();
        List&lt;Integer&gt; result1 = preorderWithStack(root);
        long stackTime = System.nanoTime() - start;

        // 测试ArrayDeque性能
        start = System.nanoTime();
        List&lt;Integer&gt; result2 = preorderWithArrayDeque(root);
        long dequeTime = System.nanoTime() - start;

        System.out.println(&quot;Stack耗时: &quot; + stackTime / 1000000 + &quot; ms&quot;);
        System.out.println(&quot;ArrayDeque耗时: &quot; + dequeTime / 1000000 + &quot; ms&quot;);
        System.out.println(&quot;性能提升: &quot; + (stackTime - dequeTime) * 100 / stackTime + &quot;%&quot;);
    }

    private static List&lt;Integer&gt; preorderWithStack(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        Stack&lt;TreeNode&gt; stack = new Stack&lt;&gt;();
        if (root != null) stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            result.add(node.val);
            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);
        }
        return result;
    }

    private static List&lt;Integer&gt; preorderWithArrayDeque(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();
        if (root != null) stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            result.add(node.val);
            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);
        }
        return result;
    }
}
优化技巧

使用ArrayDeque替代Stack

