/**
 * 浏览器历史记录管理
 */
public class BrowserHistory {
    private Deque&lt;String&gt; history = new ArrayDeque&lt;&gt;();
    private Deque&lt;String&gt; forward = new ArrayDeque&lt;&gt;();

    public void visit(String url) {
        history.push(url);
        forward.clear();  // 清空前进历史
    }

    public String back() {
        if (history.size() &gt; 1) {
            String current = history.pop();
            forward.push(current);
            return history.peek();
        }
        return history.peek();
    }

    public String forward() {
        if (!forward.isEmpty()) {
            String url = forward.pop();
            history.push(url);
            return url;
        }
        return history.peek();
    }
}
