1.1 括号匹配问题
public class BracketMatcher {
    /**
     * 检查括号是否匹配
     * 核心思想：左括号入栈，右括号出栈匹配
     */
    public boolean isValid(String s) {
        Deque&lt;Character&gt; stack = new ArrayDeque&lt;&gt;();
        Map&lt;Character, Character&gt; pairs = Map.of(&#039;)&#039;, &#039;(&#039;, &#039;]&#039;, &#039;[&#039;, &#039;}&#039;, &#039;{&#039;);

        for (char c : s.toCharArray()) {
            if (pairs.containsValue(c)) {
                // 左括号：压栈
                stack.push(c);
            } else if (pairs.containsKey(c)) {
                // 右括号：检查匹配
                if (stack.isEmpty() || stack.pop() != pairs.get(c)) {
                    return false;
                }
            }
        }

        return stack.isEmpty();
    }

    /**
     * 扩展：找出最长有效括号长度
     */
    public int longestValidParentheses(String s) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(-1); // 哨兵
        int maxLen = 0;

        for (int i = 0; i &lt; s.length(); i++) {
            if (s.charAt(i) == &#039;(&#039;) {
                stack.push(i);
            } else {
                stack.pop();
                if (stack.isEmpty()) {
                    stack.push(i); // 新的起点
                } else {
                    maxLen = Math.max(maxLen, i - stack.peek());
                }
            }
        }

        return maxLen;
    }
}
1.2 表达式求值
public class ExpressionEvaluator {
    /**
     * 基本计算器（支持 +, -, *, /）
     * 核心思想：用栈处理运算符优先级
     */
    public int calculate(String s) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        char operator = &#039;+&#039;;
        int num = 0;

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                num = num * 10 + (c - &#039;0&#039;);
            }

            if (c == &#039;+&#039; || c == &#039;-&#039; || c == &#039;*&#039; || c == &#039;/&#039; || i == s.length() - 1) {
                switch (operator) {
                    case &#039;+&#039;: stack.push(num); break;
                    case &#039;-&#039;: stack.push(-num); break;
                    case &#039;*&#039;: stack.push(stack.pop() * num); break;
                    case &#039;/&#039;: stack.push(stack.pop() / num); break;
                }
                operator = c;
                num = 0;
            }
        }

        return stack.stream().mapToInt(Integer::intValue).sum();
    }

    /**
     * 支持括号的计算器
     */
    public int calculateWithParentheses(String s) {
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();
        Deque&lt;Character&gt; ops = new ArrayDeque&lt;&gt;();

        for (int i = 0; i &lt; s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                int num = 0;
                while (i &lt; s.length() &amp;&amp; Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - &#039;0&#039;);
                    i++;
                }
                i--; // 回退一位
                stack.push(num);
            } else if (c == &#039;(&#039;) {
                ops.push(c);
            } else if (c == &#039;)&#039;) {
                while (!ops.isEmpty() &amp;&amp; ops.peek() != &#039;(&#039;) {
                    stack.push(applyOperation(ops.pop(), stack.pop(), stack.pop()));
                }
                ops.pop(); // 移除 &#039;(&#039;
            } else if (c == &#039;+&#039; || c == &#039;-&#039; || c == &#039;*&#039; || c == &#039;/&#039;) {
                while (!ops.isEmpty() &amp;&amp; hasPrecedence(c, ops.peek())) {
                    stack.push(applyOperation(ops.pop(), stack.pop(), stack.pop()));
                }
                ops.push(c);
            }
        }

        while (!ops.isEmpty()) {
            stack.push(applyOperation(ops.pop(), stack.pop(), stack.pop()));
        }

        return stack.pop();
    }

    private boolean hasPrecedence(char op1, char op2) {
        if (op2 == &#039;(&#039; || op2 == &#039;)&#039;) return false;
        if ((op1 == &#039;*&#039; || op1 == &#039;/&#039;) &amp;&amp; (op2 == &#039;+&#039; || op2 == &#039;-&#039;)) return false;
        return true;
    }

    private int applyOperation(char op, int b, int a) {
        switch (op) {
            case &#039;+&#039;: return a + b;
            case &#039;-&#039;: return a - b;
            case &#039;*&#039;: return a * b;
            case &#039;/&#039;: return a / b;
        }
        return 0;
    }
}
2. 树和图遍历类
2.1 二叉树遍历
public class TreeTraversal {
    /**
     * 前序遍历（迭代版本）
     * 核心思想：根节点先处理，右子树先入栈
     */
    public List&lt;Integer&gt; preorderTraversal(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            result.add(node.val);

            // 先压右子树，再压左子树（保证左子树先处理）
            if (node.right != null) stack.push(node.right);
            if (node.left != null) stack.push(node.left);
        }

        return result;
    }

    /**
     * 中序遍历（迭代版本）
     * 核心思想：一直向左走到底，然后处理节点
     */
    public List&lt;Integer&gt; inorderTraversal(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        Deque&lt;TreeNode&gt; stack = new ArrayDeque&lt;&gt;();
        TreeNode current = root;

        while (current != null || !stack.isEmpty()) {
            // 一直向左走，压栈
            while (current != null) {
                stack.push(current);
                current = current.left;
            }

            // 处理栈顶节点
            current = stack.pop();
            result.add(current.val);
            current = current.right;
        }

        return result;
    }

    /**
     * 后序遍历（双栈法）
     * 核心思想：用两个栈实现逆序
     */
    public List&lt;Integer&gt; postorderTraversal(TreeNode root) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; stack1 = new ArrayDeque&lt;&gt;();
        Deque&lt;TreeNode&gt; stack2 = new ArrayDeque&lt;&gt;();

        stack1.push(root);

        while (!stack1.isEmpty()) {
            TreeNode node = stack1.pop();
            stack2.push(node);

            if (node.left != null) stack1.push(node.left);
            if (node.right != null) stack1.push(node.right);
        }

        while (!stack2.isEmpty()) {
            result.add(stack2.pop().val);
        }

        return result;
    }
}
2.2 图的深度优先搜索
public class GraphDFS {
    /**
     * 图的DFS遍历
     * 核心思想：用栈模拟递归的深度优先搜索
     */
    public List&lt;Integer&gt; dfsIterative(int[][] graph, int start) {
        List&lt;Integer&gt; result = new ArrayList&lt;&gt;();
        boolean[] visited = new boolean[graph.length];
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();

        stack.push(start);

        while (!stack.isEmpty()) {
            int node = stack.pop();

            if (!visited[node]) {
                visited[node] = true;
                result.add(node);

                // 逆序添加邻居（保证按顺序访问）
                for (int i = graph[node].length - 1; i &gt;= 0; i--) {
                    int neighbor = graph[node][i];
                    if (!visited[neighbor]) {
                        stack.push(neighbor);
                    }
                }
            }
        }

        return result;
    }

    /**
     * 岛屿数量问题
     * 核心思想：用栈进行DFS，标记连通区域
     */
    public int numIslands(char[][] grid) {
        if (grid == null || grid.length == 0) return 0;

        int count = 0;
        int rows = grid.length, cols = grid[0].length;

        for (int i = 0; i &lt; rows; i++) {
            for (int j = 0; j &lt; cols; j++) {
                if (grid[i][j] == &#039;1&#039;) {
                    count++;
                    dfsMarkIsland(grid, i, j);
                }
            }
        }

        return count;
    }

    private void dfsMarkIsland(char[][] grid, int startRow, int startCol) {
        Deque&lt;int[]&gt; stack = new ArrayDeque&lt;&gt;();
        stack.push(new int[]{startRow, startCol});

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!stack.isEmpty()) {
            int[] pos = stack.pop();
            int row = pos[0], col = pos[1];

            if (row &lt; 0 || row &gt;= grid.length || col &lt; 0 || col &gt;= grid[0].length || 
                grid[row][col] != &#039;1&#039;) {
                continue;
            }

            grid[row][col] = &#039;0&#039;; // 标记为已访问

            // 添加四个方向的邻居
            for (int[] dir : directions) {
                stack.push(new int[]{row + dir[0], col + dir[1]});
            }
        }
    }
}
3. 回溯和状态管理类
3.1 路径回溯
public class PathBacktracking {
    /**
     * 二叉树的所有路径
     * 核心思想：用栈保存当前路径，回溯时弹出
     */
    public List&lt;String&gt; binaryTreePaths(TreeNode root) {
        List&lt;String&gt; result = new ArrayList&lt;&gt;();
        if (root == null) return result;

        Deque&lt;TreeNode&gt; nodeStack = new ArrayDeque&lt;&gt;();
        Deque&lt;String&gt; pathStack = new ArrayDeque&lt;&gt;();

        nodeStack.push(root);
        pathStack.push(String.valueOf(root.val));

        while (!nodeStack.isEmpty()) {
            TreeNode node = nodeStack.pop();
            String path = pathStack.pop();

            // 叶子节点：添加路径
            if (node.left == null &amp;&amp; node.right == null) {
                result.add(path);
            }

            // 继续探索子节点
            if (node.left != null) {
                nodeStack.push(node.left);
                pathStack.push(path + &quot;-&gt;&quot; + node.left.val);
            }

            if (node.right != null) {
                nodeStack.push(node.right);
                pathStack.push(path + &quot;-&gt;&quot; + node.right.val);
            }
        }

        return result;
    }

    /**
     * 迷宫路径查找
     * 核心思想：用栈保存路径，遇到死路时回溯
     */
    public boolean hasPath(int[][] maze, int[] start, int[] destination) {
        Deque&lt;int[]&gt; stack = new ArrayDeque&lt;&gt;();
        boolean[][] visited = new boolean[maze.length][maze[0].length];

        stack.push(start);

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!stack.isEmpty()) {
            int[] pos = stack.pop();

            if (pos[0] == destination[0] &amp;&amp; pos[1] == destination[1]) {
                return true;
            }

            if (visited[pos[0]][pos[1]]) continue;
            visited[pos[0]][pos[1]] = true;

            for (int[] dir : directions) {
                int newRow = pos[0];
                int newCol = pos[1];

                // 一直滚动到撞墙或边界
                while (newRow &gt;= 0 &amp;&amp; newRow &lt; maze.length &amp;&amp; 
                       newCol &gt;= 0 &amp;&amp; newCol &lt; maze[0].length &amp;&amp; 
                       maze[newRow][newCol] == 0) {
                    newRow += dir[0];
                    newCol += dir[1];
                }

                // 回退一步（撞墙前的位置）
                newRow -= dir[0];
                newCol -= dir[1];

                if (!visited[newRow][newCol]) {
                    stack.push(new int[]{newRow, newCol});
                }
            }
        }

        return false;
    }
}
