实现代码：
public class ExpressionCalculator {
    private Map&lt;String, Function&lt;Double[], Double&gt;&gt; functions;

    public ExpressionCalculator() {
        initializeFunctions();
    }

    public double evaluate(String expression) {
        String postfix = infixToPostfix(expression);
        return evaluatePostfix(postfix);
    }

    private String infixToPostfix(String infix) {
        // 实现中缀转后缀算法
        StringBuilder postfix = new StringBuilder();
        Deque&lt;String&gt; stack = new ArrayDeque&lt;&gt;();

        String[] tokens = tokenize(infix);
        for (String token : tokens) {
            if (isNumber(token)) {
                postfix.append(token).append(&quot; &quot;);
            } else if (isFunction(token)) {
                stack.push(token);
            } else if (token.equals(&quot;(&quot;)) {
                stack.push(token);
            } else if (token.equals(&quot;)&quot;)) {
                while (!stack.isEmpty() &amp;&amp; !stack.peek().equals(&quot;(&quot;)) {
                    postfix.append(stack.pop()).append(&quot; &quot;);
                }
                stack.pop(); // 移除 &quot;(&quot;
                if (!stack.isEmpty() &amp;&amp; isFunction(stack.peek())) {
                    postfix.append(stack.pop()).append(&quot; &quot;);
                }
            } else if (isOperator(token)) {
                while (!stack.isEmpty() &amp;&amp; !stack.peek().equals(&quot;(&quot;) &amp;&amp;
                       getPrecedence(stack.peek()) &gt;= getPrecedence(token)) {
                    postfix.append(stack.pop()).append(&quot; &quot;);
                }
                stack.push(token);
            }
        }

        while (!stack.isEmpty()) {
            postfix.append(stack.pop()).append(&quot; &quot;);
        }

        return postfix.toString().trim();
    }

    private double evaluatePostfix(String postfix) {
        // 实现后缀表达式求值
        Deque&lt;Double&gt; stack = new ArrayDeque&lt;&gt;();
        String[] tokens = postfix.split(&quot; &quot;);

        for (String token : tokens) {
            if (isNumber(token)) {
                stack.push(Double.parseDouble(token));
            } else if (isOperator(token)) {
                double b = stack.pop();
                double a = stack.pop();
                stack.push(applyOperator(token, a, b));
            } else if (isFunction(token)) {
                int paramCount = getFunctionParamCount(token);
                Double[] params = new Double[paramCount];
                for (int i = paramCount - 1; i &gt;= 0; i--) {
                    params[i] = stack.pop();
                }
                stack.push(functions.get(token).apply(params));
            }
        }

        return stack.pop();
    }

    private void initializeFunctions() {
        functions = new HashMap&lt;&gt;();
        functions.put(&quot;sin&quot;, params -&gt; Math.sin(params[0]));
        functions.put(&quot;cos&quot;, params -&gt; Math.cos(params[0]));
        functions.put(&quot;sqrt&quot;, params -&gt; Math.sqrt(params[0]));
        functions.put(&quot;max&quot;, params -&gt; Math.max(params[0], params[1]));
        functions.put(&quot;min&quot;, params -&gt; Math.min(params[0], params[1]));
    }

    // 辅助方法实现...
}
项目2：文本编辑器撤销重做
项目描述： 实现一个支持撤销重做功能的文本编辑器
技术要点：

命令模式设计
双栈实现撤销重做
内存优化策略
批量操作处理

实现代码：
public class TextEditor {
    private StringBuilder content;
    private Deque&lt;Command&gt; undoStack;
    private Deque&lt;Command&gt; redoStack;
    private int maxUndoSteps;

    public TextEditor(int maxUndoSteps) {
        this.content = new StringBuilder();
        this.undoStack = new ArrayDeque&lt;&gt;();
        this.redoStack = new ArrayDeque&lt;&gt;();
        this.maxUndoSteps = maxUndoSteps;
    }

    public void insert(int position, String text) {
        executeCommand(new InsertCommand(position, text));
    }

    public void delete(int position, int length) {
        executeCommand(new DeleteCommand(position, length));
    }

    public void replace(int position, int length, String newText) {
        executeCommand(new ReplaceCommand(position, length, newText));
    }

    public void undo() {
        if (!undoStack.isEmpty()) {
            Command command = undoStack.pop();
            command.undo(content);
            redoStack.push(command);
        }
    }

    public void redo() {
        if (!redoStack.isEmpty()) {
            Command command = redoStack.pop();
            command.execute(content);
            undoStack.push(command);
        }
    }

    private void executeCommand(Command command) {
        command.execute(content);
        undoStack.push(command);
        redoStack.clear();

        // 限制撤销步数
        if (undoStack.size() &gt; maxUndoSteps) {
            // 移除最早的命令
            Deque&lt;Command&gt; temp = new ArrayDeque&lt;&gt;();
            for (int i = 0; i &lt; maxUndoSteps; i++) {
                temp.push(undoStack.pop());
            }
            undoStack.clear();
            while (!temp.isEmpty()) {
                undoStack.addLast(temp.pop());
            }
        }
    }

    // 命令接口和实现类...
    interface Command {
        void execute(StringBuilder content);
        void undo(StringBuilder content);
    }

    class InsertCommand implements Command {
        private int position;
        private String text;

        public InsertCommand(int position, String text) {
            this.position = position;
            this.text = text;
        }

        @Override
        public void execute(StringBuilder content) {
            content.insert(position, text);
        }

        @Override
        public void undo(StringBuilder content) {
            content.delete(position, position + text.length());
        }
    }

    // 其他命令实现...
}
项目3：浏览器历史记录管理
项目描述： 实现一个浏览器历史记录管理系统
技术要点：

双栈管理前进后退
URL验证和处理
历史记录持久化
内存管理优化

实现代码：
public class BrowserHistory {
    private Deque&lt;String&gt; backStack;
    private Deque&lt;String&gt; forwardStack;
    private String currentUrl;
    private int maxHistorySize;

    public BrowserHistory(String homepage, int maxHistorySize) {
        this.backStack = new ArrayDeque&lt;&gt;();
        this.forwardStack = new ArrayDeque&lt;&gt;();
        this.currentUrl = homepage;
        this.maxHistorySize = maxHistorySize;
    }

    public void visit(String url) {
        if (currentUrl != null) {
            backStack.push(currentUrl);
            limitStackSize(backStack);
        }
        currentUrl = url;
        forwardStack.clear();
    }

    public String back(int steps) {
        for (int i = 0; i &lt; steps &amp;&amp; !backStack.isEmpty(); i++) {
            forwardStack.push(currentUrl);
            currentUrl = backStack.pop();
        }
        limitStackSize(forwardStack);
        return currentUrl;
    }

    public String forward(int steps) {
        for (int i = 0; i &lt; steps &amp;&amp; !forwardStack.isEmpty(); i++) {
            backStack.push(currentUrl);
            currentUrl = forwardStack.pop();
        }
        limitStackSize(backStack);
        return currentUrl;
    }

    public String getCurrentUrl() {
        return currentUrl;
    }

    public List&lt;String&gt; getHistory() {
        List&lt;String&gt; history = new ArrayList&lt;&gt;();

        // 添加后退历史
        List&lt;String&gt; backHistory = new ArrayList&lt;&gt;(backStack);
        Collections.reverse(backHistory);
        history.addAll(backHistory);

        // 添加当前页面
        history.add(currentUrl);

        // 添加前进历史
        history.addAll(forwardStack);

        return history;
    }

    private void limitStackSize(Deque&lt;String&gt; stack) {
        while (stack.size() &gt; maxHistorySize) {
            // 移除最早的记录
            String[] temp = stack.toArray(new String[0]);
            stack.clear();
            for (int i = 1; i &lt; temp.length; i++) {
                stack.addLast(temp[i]);
            }
        }
    }

    // 历史记录搜索
    public List&lt;String&gt; searchHistory(String keyword) {
        return getHistory().stream()
                .filter(url -&gt; url.toLowerCase().contains(keyword.toLowerCase()))
                .collect(Collectors.toList());
    }

    // 清除历史记录
    public void clearHistory() {
        backStack.clear();
        forwardStack.clear();
    }
}
