2. 状态记录模式
核心思想： 栈存储元素，哈希表记录元素的状态信息
/**
 * 带状态的栈结构
 */
public class StatefulStack&lt;T&gt; {
    private Deque&lt;T&gt; stack;
    private Map&lt;T, ElementState&gt; stateMap;

    public StatefulStack() {
        stack = new ArrayDeque&lt;&gt;();
        stateMap = new HashMap&lt;&gt;();
    }

    /**
     * 元素状态枚举
     */
    public enum ElementState {
        ACTIVE,     // 活跃状态
        PROCESSED,  // 已处理
        MARKED,     // 已标记
        LOCKED      // 锁定状态
    }

    /**
     * 入栈并设置状态
     */
    public void push(T element, ElementState state) {
        stack.push(element);
        stateMap.put(element, state);
    }

    /**
     * 入栈（默认活跃状态）
     */
    public void push(T element) {
        push(element, ElementState.ACTIVE);
    }

    /**
     * 出栈
     */
    public T pop() {
        if (stack.isEmpty()) {
            throw new RuntimeException(&quot;栈为空&quot;);
        }

        T element = stack.pop();
        stateMap.remove(element);
        return element;
    }

    /**
     * 更新元素状态
     */
    public boolean updateState(T element, ElementState newState) {
        if (!stateMap.containsKey(element)) {
            return false;
        }
        stateMap.put(element, newState);
        return true;
    }

    /**
     * 获取元素状态
     */
    public ElementState getState(T element) {
        return stateMap.get(element);
    }

    /**
     * 检查元素是否在栈中且为指定状态
     */
    public boolean isInState(T element, ElementState state) {
        return stateMap.getOrDefault(element, null) == state;
    }

    /**
     * 获取指定状态的所有元素
     */
    public List&lt;T&gt; getElementsByState(ElementState state) {
        return stateMap.entrySet().stream()
                .filter(entry -&gt; entry.getValue() == state)
                .map(Map.Entry::getKey)
                .collect(Collectors.toList());
    }

    /**
     * 弹出指定状态的栈顶元素
     */
    public T popByState(ElementState state) {
        while (!stack.isEmpty()) {
            T top = stack.peek();
            if (stateMap.get(top) == state) {
                return pop();
            } else {
                // 如果栈顶不是目标状态，暂时移除
                T temp = pop();
                // 这里可以根据需求决定如何处理
            }
        }
        return null;
    }
}
