问题描述： 找到每个右括号对应的最近左括号位置
/**
 * 括号匹配问题的栈+哈希表解法
 */
public class BracketMatcher {

    /**
     * 找到每个右括号对应的左括号位置
     */
    public int[] findMatchingBrackets(String s) {
        int n = s.length();
        int[] result = new int[n];
        Arrays.fill(result, -1);

        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();  // 存储左括号位置
        Map&lt;Character, Character&gt; pairs = new HashMap&lt;&gt;();
        pairs.put(&#039;)&#039;, &#039;(&#039;);
        pairs.put(&#039;]&#039;, &#039;[&#039;);
        pairs.put(&#039;}&#039;, &#039;{&#039;);

        for (int i = 0; i &lt; n; i++) {
            char ch = s.charAt(i);

            if (ch == &#039;(&#039; || ch == &#039;[&#039; || ch == &#039;{&#039;) {
                // 左括号入栈
                stack.push(i);
            } else if (pairs.containsKey(ch)) {
                // 右括号匹配
                if (!stack.isEmpty()) {
                    int leftPos = stack.pop();
                    if (s.charAt(leftPos) == pairs.get(ch)) {
                        result[i] = leftPos;  // 记录匹配位置
                    }
                }
            }
        }

        return result;
    }

    /**
     * 检查括号是否有效并返回详细信息
     */
    public BracketInfo validateBrackets(String s) {
        Deque&lt;Character&gt; stack = new ArrayDeque&lt;&gt;();
        Map&lt;Character, Integer&gt; count = new HashMap&lt;&gt;();

        for (char ch : s.toCharArray()) {
            if (ch == &#039;(&#039; || ch == &#039;[&#039; || ch == &#039;{&#039;) {
                stack.push(ch);
                count.put(ch, count.getOrDefault(ch, 0) + 1);
            } else {
                char expected = getMatchingLeft(ch);
                if (stack.isEmpty() || stack.pop() != expected) {
                    return new BracketInfo(false, count, stack.size());
                }
            }
        }

        return new BracketInfo(stack.isEmpty(), count, stack.size());
    }

    private char getMatchingLeft(char right) {
        switch (right) {
            case &#039;)&#039;: return &#039;(&#039;;
            case &#039;]&#039;: return &#039;[&#039;;
            case &#039;}&#039;: return &#039;{&#039;;
            default: return &#039; &#039;;
        }
    }

    static class BracketInfo {
        boolean isValid;
        Map&lt;Character, Integer&gt; bracketCount;
        int unmatchedCount;

        BracketInfo(boolean isValid, Map&lt;Character, Integer&gt; count, int unmatched) {
            this.isValid = isValid;
            this.bracketCount = count;
            this.unmatchedCount = unmatched;
        }
    }
}
2. 下一个更大元素的位置记录
问题描述： 对于数组中每个元素，找到它右边第一个更大元素的位置
/**
 * 下一个更大元素问题的增强版
 */
public class NextGreaterElementTracker {

    /**
     * 找到下一个更大元素及其位置
     */
    public Map&lt;Integer, ElementInfo&gt; findNextGreaterWithInfo(int[] nums) {
        Map&lt;Integer, ElementInfo&gt; result = new HashMap&lt;&gt;();
        Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;();  // 存储索引
        Map&lt;Integer, Integer&gt; valueToIndex = new HashMap&lt;&gt;();  // 值到索引的映射

        for (int i = 0; i &lt; nums.length; i++) {
            // 处理栈中小于当前元素的所有元素
            while (!stack.isEmpty() &amp;&amp; nums[stack.peek()] &lt; nums[i]) {
                int index = stack.pop();
                int value = nums[index];

                result.put(value, new ElementInfo(
                    nums[i],           // 下一个更大元素
                    i,                 // 下一个更大元素位置
                    i - index          // 距离
                ));
            }

            stack.push(i);
            valueToIndex.put(nums[i], i);
        }

        // 处理没有下一个更大元素的情况
        while (!stack.isEmpty()) {
            int index = stack.pop();
            int value = nums[index];
            result.put(value, new ElementInfo(-1, -1, -1));
        }

        return result;
    }

    static class ElementInfo {
        int nextGreater;     // 下一个更大元素值
        int position;        // 下一个更大元素位置
        int distance;        // 距离

        ElementInfo(int nextGreater, int position, int distance) {
            this.nextGreater = nextGreater;
            this.position = position;
            this.distance = distance;
        }

        @Override
        public String toString() {
            return String.format(&quot;NextGreater: %d, Position: %d, Distance: %d&quot;, 
                               nextGreater, position, distance);
        }
    }
}
3. 滑动窗口最大值
问题描述： 在滑动窗口中维护最大值
/**
 * 滑动窗口最大值的栈+哈希表实现
 */
public class SlidingWindowMaximum {
    private Deque&lt;Integer&gt; deque;           // 单调递减双端队列
    private Map&lt;Integer, Integer&gt; count;    // 元素计数

    public SlidingWindowMaximum() {
        deque = new ArrayDeque&lt;&gt;();
        count = new HashMap&lt;&gt;();
    }

    /**
     * 添加元素到窗口
     */
    public void addElement(int val) {
        // 维护单调递减性
        while (!deque.isEmpty() &amp;&amp; deque.peekLast() &lt; val) {
            int removed = deque.pollLast();
            count.put(removed, count.get(removed) - 1);
            if (count.get(removed) == 0) {
                count.remove(removed);
            }
        }

        deque.offerLast(val);
        count.put(val, count.getOrDefault(val, 0) + 1);
    }

    /**
     * 从窗口移除元素
     */
    public void removeElement(int val) {
        if (count.containsKey(val)) {
            count.put(val, count.get(val) - 1);
            if (count.get(val) == 0) {
                count.remove(val);
                deque.remove(val);  // 从双端队列中移除
            }
        }
    }

    /**
     * 获取当前窗口最大值
     */
    public int getMaximum() {
        return deque.isEmpty() ? Integer.MIN_VALUE : deque.peekFirst();
    }

    /**
     * 滑动窗口最大值主方法
     */
    public int[] maxSlidingWindow(int[] nums, int k) {
        if (nums.length == 0 || k == 0) return new int[0];

        int[] result = new int[nums.length - k + 1];
        SlidingWindowMaximum window = new SlidingWindowMaximum();

        // 初始化第一个窗口
        for (int i = 0; i &lt; k; i++) {
            window.addElement(nums[i]);
        }
        result[0] = window.getMaximum();

        // 滑动窗口
        for (int i = k; i &lt; nums.length; i++) {
            window.removeElement(nums[i - k]);  // 移除窗口左边元素
            window.addElement(nums[i]);         // 添加窗口右边元素
            result[i - k + 1] = window.getMaximum();
        }

        return result;
    }
}
🔍 栈+哈希表的设计模式
1. 设计原则



































模式类型栈的作用哈希表的作用适用场景位置记录维护顺序记录位置快速定位、去重状态管理存储元素记录状态状态机、流程控制频率统计分组存储统计频率频率相关问题缓存优化LRU顺序快速查找缓存系统
2. 实现模板
/**
 * 栈+哈希表通用模板
 */
public class StackHashMapTemplate&lt;K, V&gt; {
    private Deque&lt;K&gt; stack;
    private Map&lt;K, V&gt; hashMap;

    public StackHashMapTemplate() {
        stack = new ArrayDeque&lt;&gt;();
        hashMap = new HashMap&lt;&gt;();
    }

    // 核心操作：保持栈和哈希表同步
    public void push(K key, V value) {
        // 1. 处理重复元素（根据需求）
        if (hashMap.containsKey(key)) {
            handleDuplicate(key, value);
        }

        // 2. 更新栈
        stack.push(key);

        // 3. 更新哈希表
        hashMap.put(key, value);

        // 4. 维护一致性
        maintainConsistency();
    }

    public K pop() {
        if (stack.isEmpty()) {
            throw new RuntimeException(&quot;栈为空&quot;);
        }

        K key = stack.pop();
        hashMap.remove(key);
        return key;
    }

    // 快速查找
    public boolean contains(K key) {
        return hashMap.containsKey(key);
    }

    public V getValue(K key) {
        return hashMap.get(key);
    }

    // 根据具体需求实现
    protected void handleDuplicate(K key, V value) {
        // 默认实现：移除旧元素
        stack.remove(key);
    }

    protected void maintainConsistency() {
        // 确保栈和哈希表的一致性
        assert stack.size() == hashMap.size();
    }
}
🚀 性能分析与优化
时间复杂度

基本操作：O(1) - 入栈、出栈、查找
删除中间元素：O(n) - 需要重建索引
批量操作：O(n) - 线性时间

空间复杂度

额外空间：O(n) - 哈希表存储
总空间：O(2n) - 栈+哈希表

优化策略

延迟删除：标记删除而非立即删除
批量更新：积累操作后批量处理
内存池：重用对象减少GC压力
压缩存储：使用更紧凑的数据结构

💡 学习要点与最佳实践
1. 设计要点

同步维护：确保栈和哈希表的一致性
重复处理：明确重复元素的处理策略
内存管理：及时清理无用数据

2. 常见陷阱

状态不一致：栈和哈希表状态不同步
内存泄漏：忘记清理哈希表中的数据
并发问题：多线程环境下的数据竞争

3. 调试技巧

状态检查：定期验证数据结构一致性
日志记录：记录关键操作的执行过程
单元测试：针对边界情况编写测试

4. 扩展思考

多级索引：使用多个哈希表建立不同维度的索引
持久化：如何将状态持久化到磁盘
分布式：在分布式环境中的应用

栈+哈希表结构通过巧妙结合两种数据结构的优势，为解决复杂的查找和顺序维护问题提供了高效的解决方案。掌握这种混合数据结构的设计思想，将大大提升处理复杂算法问题的能力！

栈和哈希表/题解2.0.0-每日温度.content:
题解：LeetCode 739 - 每日温度
1. 问题分析
这道题目要求我们找出每一天需要等待多少天才能遇到更高的温度。本质上，这是一个寻找下一个更大元素的问题，非常适合使用单调栈来解决。
问题特点：

需要找出数组中每个元素右侧第一个比它大的元素的位置
关注的是元素之间的相对位置（天数差）
如果没有更大元素，结果为0

2. 单调栈解决方案
2.1 核心思路
使用单调递减栈（从栈底到栈顶温度递减）来解决这个问题：

遍历温度数组
对于当前温度，如果它大于栈顶温度，则找到了栈顶温度的”下一个更高温度”
计算两者的下标差值，即等待天数
重复比较直到栈为空或当前温度不大于栈顶温度
将当前温度入栈，继续处理下一个温度

2.2 算法流程

初始化一个空栈和一个长度为n的结果数组（初始值全为0）
从左到右遍历温度数组：

当栈不为空且当前温度大于栈顶温度对应的温度时：

弹出栈顶元素（下标）
计算当前下标与弹出下标的差值，更新结果数组
继续比较栈顶


将当前下标入栈


返回结果数组

2.3 图解工作原理
以示例 [73, 74, 75, 71, 69, 72, 76, 73] 为例：
初始状态：
栈: []
结果: [0, 0, 0, 0, 0, 0, 0, 0]

处理 temperatures[0] = 73:
栈: [0]
结果: [0, 0, 0, 0, 0, 0, 0, 0]

处理 temperatures[1] = 74:
74 &gt; 73，弹出栈顶元素0
结果[0] = 1 - 0 = 1
栈: [1]
结果: [1, 0, 0, 0, 0, 0, 0, 0]

处理 temperatures[2] = 75:
75 &gt; 74，弹出栈顶元素1
结果[1] = 2 - 1 = 1
栈: [2]
结果: [1, 1, 0, 0, 0, 0, 0, 0]

处理 temperatures[3] = 71:
71 &lt; 75，直接入栈
栈: [2, 3]
结果: [1, 1, 0, 0, 0, 0, 0, 0]

处理 temperatures[4] = 69:
69 &lt; 71，直接入栈
栈: [2, 3, 4]
结果: [1, 1, 0, 0, 0, 0, 0, 0]

处理 temperatures[5] = 72:
72 &gt; 69，弹出栈顶元素4
结果[4] = 5 - 4 = 1
72 &gt; 71，弹出栈顶元素3
结果[3] = 5 - 3 = 2
72 &lt; 75，直接入栈
栈: [2, 5]
结果: [1, 1, 0, 2, 1, 0, 0, 0]

处理 temperatures[6] = 76:
76 &gt; 72，弹出栈顶元素5
结果[5] = 6 - 5 = 1
76 &gt; 75，弹出栈顶元素2
结果[2] = 6 - 2 = 4
栈: [6]
结果: [1, 1, 4, 2, 1, 1, 0, 0]

处理 temperatures[7] = 73:
73 &lt; 76，直接入栈
栈: [6, 7]
结果: [1, 1, 4, 2, 1, 1, 0, 0]

最终结果: [1, 1, 4, 2, 1, 1, 0, 0]

3. 代码实现
class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] answer = new int[n];
        // 单调栈，存储下标
        Stack&lt;Integer&gt; stack = new Stack&lt;&gt;();

        for (int i = 0; i &lt; n; i++) {
            // 当前温度大于栈顶温度，找到了栈顶温度的下一个更高温度
            while (!stack.isEmpty() &amp;&amp; temperatures[i] &gt; temperatures[stack.peek()]) {
                int prevIndex = stack.pop();
                // 计算等待天数
                answer[prevIndex] = i - prevIndex;
            }
            // 将当前下标入栈
            stack.push(i);
        }

        return answer;
    }
}
4. 复杂度分析

时间复杂度: O(n)，其中n是温度数组的长度。虽然有嵌套循环，但每个元素最多入栈和出栈一次，所以总操作次数是线性的。
空间复杂度: O(n)，最坏情况下（温度递减序列），栈会存储所有元素的下标。

5. 优化思路
5.1 数组模拟栈
可以使用数组来模拟栈，避免Java中Stack类的额外开销：
class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] answer = new int[n];
        // 用数组模拟栈，top表示栈顶位置
        int[] stack = new int[n];
        int top = -1;

        for (int i = 0; i &lt; n; i++) {
            while (top &gt;= 0 &amp;&amp; temperatures[i] &gt; temperatures[stack[top]]) {
                int prevIndex = stack[top--];
                answer[prevIndex] = i - prevIndex;
            }
            stack[++top] = i;
        }

        return answer;
    }
}
5.2 逆序遍历
也可以从右向左遍历，利用已计算的结果：
class Solution {
    public int[] dailyTemperatures(int[] temperatures) {
        int n = temperatures.length;
        int[] answer = new int[n];

        // 从右向左遍历
        for (int i = n - 2; i &gt;= 0; i--) {
            int j = i + 1;
            while (j &lt; n &amp;&amp; temperatures[j] &lt;= temperatures[i]) {
                // 如果下一天温度不高于今天，跳到下一个更高温度的那天
                if (answer[j] &gt; 0) {
                    j += answer[j];
                } else {
                    // 如果没有更高温度，直接结束
                    j = n;
                }
            }
            // 如果找到了更高温度，计算天数差
            if (j &lt; n) {
                answer[i] = j - i;
            }
        }

        return answer;
    }
}
6. 总结
6.1 解题关键点

识别问题类型：寻找下一个更大元素，适合使用单调栈
选择正确的单调栈类型：单调递减栈（从栈底到栈顶递减）
存储下标而非值：便于计算天数差
结果初始化为0：处理没有更高温度的情况

6.2 单调栈应用特点
这道题展示了单调栈的典型应用场景：

寻找数组中元素的下一个更大/更小元素
关注元素之间的相对位置关系
O(n)时间复杂度解决看似需要O(n²)的问题

6.3 扩展思考
这种”寻找下一个更大元素”的模式在很多问题中都有应用，如：

LeetCode 496: 下一个更大元素 I
LeetCode 503: 下一个更大元素 II（循环数组）
LeetCode 901: 股票价格跨度
LeetCode 84: 柱状图中最大的矩形

掌握单调栈的核心思想，可以解决一系列相关问题。

栈和哈希表/题解2.0.0-移除无效的括号.content:
题解：LeetCode 1249 - 移除无效的括号
1. 问题分析
这道题要求从字符串中删除最少数目的无效括号，使得结果字符串的括号是匹配的。本质上，这是一个识别并移除无效括号的问题，非常适合使用栈+哈希表来解决。
问题特点：

需要识别哪些括号是无效的
要求删除最少数量的括号
字符串中包含字母和括号
需要保留所有字母

2. 栈+哈希表解决方案
2.1 核心思路
使用栈来匹配括号，使用**哈希表(Set)**来记录需要删除的括号位置：

使用栈存储左括号的索引
遇到右括号时尝试匹配栈顶的左括号
无法匹配的括号都是无效的，记录它们的索引
最后根据记录的索引构建有效字符串

2.2 算法流程

初始化一个空栈和一个哈希表(Set)
第一次遍历字符串：

遇到左括号：将索引压入栈
遇到右括号：

如果栈不为空，弹出栈顶（匹配成功）
如果栈为空，记录当前索引为无效右括号


遇到字母：直接跳过


处理栈中剩余的左括号：

栈中剩余的都是无效左括号，记录它们的索引


第二次遍历字符串：

跳过所有记录在哈希表中的无效括号索引
构建最终的有效字符串



2.3 图解工作原理
以示例 &quot;()())&quot; 为例：
初始状态：
栈: []
无效索引集合: {}

处理 s[0] = &#039;(&#039; (索引 0)
栈: [0]
无效索引集合: {}

处理 s[1] = &#039;)&#039; (索引 1)
栈不为空，弹出栈顶 0，匹配成功
栈: []
无效索引集合: {}

处理 s[2] = &#039;(&#039; (索引 2)
栈: [2]
无效索引集合: {}

处理 s[3] = &#039;)&#039; (索引 3)
栈不为空，弹出栈顶 2，匹配成功
栈: []
无效索引集合: {}

处理 s[4] = &#039;)&#039; (索引 4)
栈为空，无法匹配，记录为无效
栈: []
无效索引集合: {4}

处理剩余左括号：
栈为空，无剩余左括号

第二次遍历 - 构建结果：
索引 0: &#039;(&#039; 不在无效集合中，加入结果
索引 1: &#039;)&#039; 不在无效集合中，加入结果  
索引 2: &#039;(&#039; 不在无效集合中，加入结果
索引 3: &#039;)&#039; 不在无效集合中，加入结果
索引 4: &#039;)&#039; 在无效集合中，跳过

最终结果: &quot;()()&quot;

3. 代码实现
public String minRemoveToMakeValid(String s) {
    // 第一步：使用栈找出所有无效括号的索引
    Set&lt;Integer&gt; invalidIndices = new HashSet&lt;&gt;();
    Stack&lt;Integer&gt; stack = new Stack&lt;&gt;();

    for (int i = 0; i &lt; s.length(); i++) {
        char c = s.charAt(i);

        if (c == &#039;(&#039;) {
            // 左括号入栈
            stack.push(i);
        } else if (c == &#039;)&#039;) {
            if (!stack.isEmpty()) {
                // 匹配成功，弹出左括号
                stack.pop();
            } else {
                // 无法匹配的右括号
                invalidIndices.add(i);
            }
        }
        // 字母直接跳过
    }

    // 栈中剩余的都是无效的左括号
    while (!stack.isEmpty()) {
        invalidIndices.add(stack.pop());
    }

    // 第二步：构建结果字符串
    StringBuilder result = new StringBuilder();
    for (int i = 0; i &lt; s.length(); i++) {
        if (!invalidIndices.contains(i)) {
            result.append(s.charAt(i));
        }
    }

    return result.toString();
}
4. 优化方案
4.1 两次遍历优化版
可以通过两次遍历来避免使用哈希表，减少空间使用：
public String minRemoveToMakeValid(String s) {
    // 第一次遍历：从左到右，移除无效的右括号
    StringBuilder firstPass = new StringBuilder();
    int leftCount = 0;

    for (char c : s.toCharArray()) {
        if (c == &#039;(&#039;) {
            firstPass.append(c);
            leftCount++;
        } else if (c == &#039;)&#039;) {
            if (leftCount &gt; 0) {
                firstPass.append(c);
                leftCount--;
            }
            // 否则跳过这个无效的右括号
        } else {
            firstPass.append(c);
        }
    }

    // 第二次遍历：从右到左，移除多余的左括号
    StringBuilder result = new StringBuilder();
    int rightCount = 0;

    for (int i = firstPass.length() - 1; i &gt;= 0; i--) {
        char c = firstPass.charAt(i);

        if (c == &#039;)&#039;) {
            result.append(c);
            rightCount++;
        } else if (c == &#039;(&#039;) {
            if (rightCount &gt; 0) {
                result.append(c);
                rightCount--;
            }
            // 否则跳过这个多余的左括号
        } else {
            result.append(c);
        }
    }

    return result.reverse().toString();
}
4.2 计数法
另一种优化方法是使用计数法，只需要一次遍历就能确定需要删除的括号数量：
public String minRemoveToMakeValid(String s) {
    char[] chars = s.toCharArray();
    int openCount = 0;

    // 第一次遍历：处理多余的右括号
    for (int i = 0; i &lt; chars.length; i++) {
        if (chars[i] == &#039;(&#039;) {
            openCount++;
        } else if (chars[i] == &#039;)&#039;) {
            if (openCount == 0) {
                // 无效的右括号，标记为删除
                chars[i] = &#039;*&#039;;
            } else {
                openCount--;
            }
        }
    }

    // 第二次遍历：处理多余的左括号（从右到左）
    openCount = 0;
    for (int i = chars.length - 1; i &gt;= 0; i--) {
        if (chars[i] == &#039;)&#039;) {
            openCount++;
        } else if (chars[i] == &#039;(&#039;) {
            if (openCount == 0) {
                // 无效的左括号，标记为删除
                chars[i] = &#039;*&#039;;
            } else {
                openCount--;
            }
        }
    }

    // 构建结果
    StringBuilder result = new StringBuilder();
    for (char c : chars) {
        if (c != &#039;*&#039;) {
            result.append(c);
        }
    }

    return result.toString();
}
5. 复杂度分析
栈+哈希表解法：

时间复杂度：O(n)，其中n是字符串的长度。需要两次遍历字符串。
空间复杂度：O(n)，最坏情况下所有括号都无效，需要存储所有索引。

两次遍历优化版：

时间复杂度：O(n)，需要三次遍历（两次正向，一次反转）。
空间复杂度：O(n)，需要两个StringBuilder来存储中间结果。

计数法：

时间复杂度：O(n)，需要两次遍历。
空间复杂度：O(n)，需要一个字符数组来标记删除位置。

6. 总结
6.1 解题关键点

识别无效括号：使用栈来匹配括号，无法匹配的括号就是无效的
记录需要删除的位置：使用哈希表或其他方法记录无效括号的位置
构建有效字符串：跳过无效括号，保留其他字符

6.2 栈+哈希表应用特点
这道题展示了栈+哈希表的典型应用场景：

栈用于处理括号匹配问题
哈希表用于快速查找和标记需要处理的元素
两者结合可以高效地识别和处理无效括号

6.3 扩展思考
这种括号处理的模式在很多问题中都有应用，如：

LeetCode 20: 有效的括号
LeetCode 32: 最长有效括号
LeetCode 301: 删除无效的括号（进阶版，要求所有可能的解）

掌握栈处理括号的核心思想，可以解决一系列相关问题。

算法优化思想/算法优化思想-滚动数组与增量更新.content:
算法优化思想-滚动数组与增量更新
核心洞察
在分析”最大矩形”问题时，我们发现了一个重要的算法优化思想：将二维问题通过滚动数组和增量更新转化为高效的一维问题。
1. 问题背景
原始问题

输入：char[][] matrix - 二维字符数组（‘0’和’1’）
目标：找出只包含’1’的最大矩形面积
挑战：如何避免暴力枚举所有可能的矩形

核心转化思想
二维最大矩形问题 → 多个一维柱状图最大矩形问题

2. heights数组的本质理解
2.1 类比前缀和的思想
传统前缀和：
// 一维前缀和
prefixSum[i] = prefixSum[i-1] + nums[i]
heights的”垂直前缀和”：
// 二维垂直前缀和（带重置机制）
if (matrix[i][j] == &#039;1&#039;) {
    heights[j] = heights[j] + 1;  // 累积向上的连续1
} else {
    heights[j] = 0;               // 重置（连续性断开）
}
2.2 关键区别






























方面传统前缀和heights”前缀和”方向水平累加垂直累加连续性总是累加遇到0就重置语义区间和连续高度应用快速区间查询柱状图构建
3. 滚动数组优化
3.1 空间优化对比
❌ 朴素思路（空间浪费）
// 保存所有行的高度信息
int[][] allHeights = new int[m][n];  // O(m*n) 空间

for (int i = 0; i &lt; m; i++) {
    for (int j = 0; j &lt; n; j++) {
        allHeights[i][j] = calculateHeight(matrix, i, j);
    }
}
✅ 滚动数组优化
// 只保存当前行的高度信息
int[] heights = new int[n];  // O(n) 空间

for (int i = 0; i &lt; m; i++) {
    updateHeights(heights, matrix[i]);  // 增量更新
    maxArea = Math.max(maxArea, largestRectangle(heights));
}
3.2 滚动数组的核心思想
状态转移：每一行的heights都基于前一行的结果进行更新
// 状态转移方程
heights[j] = (matrix[i][j] == &#039;1&#039;) ? heights[j] + 1 : 0
空间复用：同一个数组在不同时刻代表不同行的状态
4. 增量更新的威力
4.1 时间复杂度对比
❌ 暴力重新计算
// 每次都重新计算每列的高度
for (int i = 0; i &lt; m; i++) {
    for (int j = 0; j &lt; n; j++) {
        int height = 0;
        for (int k = i; k &gt;= 0; k--) {  // 向上扫描 O(m)
            if (matrix[k][j] == &#039;1&#039;) height++;
            else break;
        }
        heights[j] = height;
    }
}
// 总时间复杂度：O(m²n)
✅ 增量更新
// 基于前一行结果进行增量更新
for (int i = 0; i &lt; m; i++) {
    updateHeights(heights, matrix[i]);  // O(n)
    // 使用当前heights计算最大矩形 O(n)
}
// 总时间复杂度：O(mn)
4.2 增量更新的实现
private void updateHeights(int[] heights, char[] row) {
    for (int j = 0; j &lt; row.length; j++) {
        if (row[j] == &#039;1&#039;) {
            heights[j]++;           // 连续1，高度累加
        } else {
            heights[j] = 0;         // 遇到0，高度重置
        }
    }
}
核心思想：

累积性：利用前一行的计算结果
重置性：遇到断点立即重置状态
高效性：避免重复计算

5. 可视化理解
5.1 heights数组的演变过程
原始矩阵：           heights数组的&quot;滚动更新&quot;：
1 0 1 0 0           
1 0 1 1 1           第0行后: [1, 0, 1, 0, 0]  ← 初始状态
1 1 1 1 1           第1行后: [2, 0, 2, 1, 1]  ← 增量更新
1 0 0 1 0           第2行后: [3, 1, 3, 2, 2]  ← 增量更新
                    第3行后: [4, 0, 0, 3, 0]  ← 增量更新

每一步都是基于前一步结果的O(n)更新！

5.2 第j=2列的高度变化
第0行: matrix[0][2]=&#039;1&#039; → heights[2]=1
       ■

第1行: matrix[1][2]=&#039;1&#039; → heights[2]=2  
       ■
       ■

第2行: matrix[2][2]=&#039;1&#039; → heights[2]=3
       ■
       ■  
       ■

第3行: matrix[3][2]=&#039;0&#039; → heights[2]=0  (重置)

6. 算法设计模式总结
6.1 优化策略组合
问题转化 + 滚动数组 + 增量更新 = 高效算法


问题转化：二维 → 一维，降低问题复杂度
滚动数组：复用空间，O(mn) → O(n)
增量更新：避免重复计算，O(m²n) → O(mn)

6.2 通用思维模式
识别优化机会

重复计算：是否存在大量重复的子问题？
状态依赖：当前状态是否只依赖前一个状态？
空间浪费：是否保存了不必要的历史信息？

应用优化策略

动态规划 + 滚动数组 → 空间优化
前缀和思想 + 增量更新 → 时间优化
问题转化 + 经典算法 → 复杂度降维

7. 相关应用场景
7.1 类似的滚动数组优化

最长公共子序列：二维DP → 一维滚动数组
背包问题：二维DP → 一维滚动数组
编辑距离：二维DP → 一维滚动数组

7.2 类似的增量更新

滑动窗口：增量维护窗口状态
单调队列/栈：增量维护单调性
前缀和/差分数组：增量计算区间信息

8. 核心收获
8.1 算法思维

转化思维：复杂问题 → 经典问题
优化思维：时间换空间 vs 空间换时间
状态思维：当前状态如何从前一状态推导

8.2 实现技巧

滚动数组：用一维数组模拟多维状态
增量更新：基于前一结果进行O(1)或O(n)更新
状态重置：在适当时机重置状态以保证正确性


总结：这种”滚动数组 + 增量更新”的组合模式，是算法优化中的经典范式。它不仅体现在这道题中，更是许多高效算法的核心思想。掌握这种思维模式，能够帮助我们在面对复杂问题时，找到优雅而高效的解决方案。

