int sock_sendmsg(struct socket *sock, struct msghdr *msg, size_t size) {
    struct kiocb iocb;
    struct sock_iocb siocb;
    int ret;

    // 初始化异步I/O控制块
    init_sync_kiocb(&amp;iocb, sock-&gt;file);
    iocb.private = &amp;siocb;
    siocb.sock = sock;
    siocb.scm = NULL;
    siocb.msg = msg;
    siocb.size = size;

    // 调用协议特定的sendmsg函数
    ret = sock-&gt;ops-&gt;sendmsg(&amp;iocb, sock, msg, size);

    return ret;
}
