4. tcp_sendmsg详细实现
4.1 tcp_sendmsg核心逻辑
int tcp_sendmsg(struct kiocb *iocb, struct sock *sk, 
                struct msghdr *msg, size_t size) {
    struct tcp_sock *tp = tcp_sk(sk);
    struct sk_buff *skb;
    int flags, err, copied = 0;
    int mss_now = 0, size_goal, copied_syn = 0, offset = 0;
    bool sg;
    long timeo;

    // 1. 检查socket状态
    lock_sock(sk);

    flags = msg-&gt;msg_flags;
    if (flags &amp; MSG_FASTOPEN) {
        err = tcp_sendmsg_fastopen(sk, msg, &amp;copied_syn, size);
        if (err == -EINPROGRESS &amp;&amp; copied_syn &gt; 0)
            goto out;
        else if (err)
            goto out_err;
        offset = copied_syn;
    }

    timeo = sock_sndtimeo(sk, flags &amp; MSG_DONTWAIT);

    // 2. 等待TCP连接建立
    if (((1 &lt;&lt; sk-&gt;sk_state) &amp; ~(TCPF_ESTABLISHED | TCPF_CLOSE_WAIT)) &amp;&amp;
        !tcp_passive_fastopen(sk)) {
        if ((err = sk_stream_wait_connect(sk, &amp;timeo)) != 0)
            goto do_error;
    }

    // 3. 处理紧急数据
    if (unlikely(tp-&gt;repair)) {
        if (tp-&gt;repair_queue == TCP_RECV_QUEUE) {
            copied = tcp_send_rcvq(sk, msg, size);
            goto out;
        }

        err = -EINVAL;
        if (tp-&gt;repair_queue == TCP_NO_QUEUE)
            goto out_err;
    }

    // 4. 获取MSS和目标大小
    mss_now = tcp_send_mss(sk, &amp;size_goal, flags);

    // 5. 主要数据发送循环
    sg = !!(sk-&gt;sk_route_caps &amp; NETIF_F_SG);

    while (msg_data_left(msg)) {
        int copy = 0;
        int max = size_goal;

        // 获取或分配sk_buff
        skb = tcp_write_queue_tail(sk);
        if (tcp_send_head(sk)) {
            if (skb-&gt;ip_summed == CHECKSUM_NONE)
                max = mss_now;
            copy = max - skb-&gt;len;
        }

        if (copy &lt;= 0) {
new_segment:
            // 分配新的sk_buff
            if (!sk_stream_memory_free(sk))
                goto wait_for_sndbuf;

            skb = sk_stream_alloc_skb(sk,
                                    select_size(sk, sg),
                                    sk-&gt;sk_allocation);
            if (!skb)
                goto wait_for_memory;

            // 设置skb属性
            skb_entail(sk, skb);
            copy = size_goal;
            max = size_goal;
        }

        // 6. 拷贝数据到sk_buff
        if (copy &gt; msg_data_left(msg))
            copy = msg_data_left(msg);

        // 关键：数据拷贝函数
        err = skb_add_data_nocache(sk, skb, &amp;msg-&gt;msg_iter, copy);
        if (err)
            goto do_fault;

        // 更新统计信息
        if (!copied)
            TCP_SKB_CB(skb)-&gt;tcp_flags &amp;= ~TCPHDR_PSH;

        tp-&gt;write_seq += copy;
        TCP_SKB_CB(skb)-&gt;end_seq += copy;
        tcp_skb_pcount_set(skb, 0);

        copied += copy;
        if (!msg_data_left(msg)) {
            tcp_tx_timestamp(sk, skb);
            goto out;
        }

        // 检查是否需要立即发送
        if (forced_push(tp)) {
            tcp_mark_push(tp, skb);
            __tcp_push_pending_frames(sk, mss_now, TCP_NAGLE_PUSH);
        } else if (skb == tcp_send_head(sk))
            tcp_push_one(sk, mss_now);
        continue;

wait_for_sndbuf:
        set_bit(SOCK_NOSPACE, &amp;sk-&gt;sk_socket-&gt;flags);
wait_for_memory:
        if (copied)
            tcp_push(sk, flags &amp; ~MSG_MORE, mss_now, 
                     TCP_NAGLE_PUSH, size_goal);

        if ((err = sk_stream_wait_memory(sk, &amp;timeo)) != 0)
            goto do_error;

        mss_now = tcp_send_mss(sk, &amp;size_goal, flags);
    }

out:
    // 7. 发送数据
    if (copied &amp;&amp; !(flags &amp; MSG_SENDPAGE_NOTLAST))
        tcp_push(sk, flags, mss_now, tp-&gt;nonagle, size_goal);

    release_sock(sk);
    return copied + copied_syn;

do_fault:
    if (!skb-&gt;len) {
        tcp_unlink_write_queue(skb, sk);
        sk_wmem_free_skb(sk, skb);
    }

do_error:
    if (copied + copied_syn)
        goto out;
out_err:
    err = sk_stream_error(sk, flags, err);
    release_sock(sk);
    return err;
}
5. 关键函数详解
5.1 skb_add_data_nocache实现
static inline int skb_add_data_nocache(struct sock *sk, struct sk_buff *skb,
                                      struct iov_iter *from, int copy) {
    int err, offset = skb-&gt;len;

    // 扩展skb数据区域
    err = skb_do_copy_data_nocache(sk, skb, from, 
                                  skb_put(skb, copy), copy,
                                  offset);
    if (err)
        __skb_trim(skb, offset);  // 失败时回滚

    return err;
}

static int skb_do_copy_data_nocache(struct sock *sk, struct sk_buff *skb,
                                   struct iov_iter *from, char *to,
                                   int copy, int offset) {
    // 检查是否需要计算校验和
    if (skb-&gt;ip_summed == CHECKSUM_NONE) {
        __wsum csum = 0;
        // 拷贝数据并计算校验和
        if (csum_and_copy_from_iter(to, copy, &amp;csum, from) != copy)
            return -EFAULT;
        skb-&gt;csum = csum_block_add(skb-&gt;csum, csum, offset);
    } else {
        // 硬件校验和卸载，直接拷贝
        if (copy_from_iter(to, copy, from) != copy)
            return -EFAULT;
    }
    return 0;
}
5.2 tcp_push实现
static inline void tcp_push(struct sock *sk, int flags, int mss_now,
                           int nonagle, int size_goal) {
    if (tcp_send_head(sk)) {
        struct tcp_sock *tp = tcp_sk(sk);

        // 设置PSH标志
        if (!(flags &amp; MSG_MORE) || forced_push(tp))
            tcp_mark_push(tp, tcp_write_queue_tail(sk));

        // 设置紧急指针
        tcp_mark_urg(tp, flags);

        // 触发实际发送
        __tcp_push_pending_frames(sk, mss_now, nonagle);
    }
}

void __tcp_push_pending_frames(struct sock *sk, unsigned int cur_mss,
                              int nonagle) {
    if (unlikely(sk-&gt;sk_state == TCP_CLOSE))
        return;

    if (tcp_write_xmit(sk, cur_mss, nonagle, 0,
                      sk_gfp_atomic(sk, GFP_ATOMIC)))
        tcp_check_probe_timer(sk);
}
6. recv系统调用实现
6.1 sys_recvfrom内核实现
SYSCALL_DEFINE6(recvfrom, int, fd, void __user *, ubuf, size_t, size,
                unsigned int, flags, struct sockaddr __user *, addr,
                int __user *, addr_len) {
    struct socket *sock;
    struct iovec iov;
    struct msghdr msg;
    struct sockaddr_storage address;
    int err, err2;
    int fput_needed;

    // 1. 参数验证
    if (size &gt; INT_MAX)
        size = INT_MAX;

    // 2. 查找socket
    sock = sockfd_lookup_light(fd, &amp;err, &amp;fput_needed);
    if (!sock)
        goto out;

    // 3. 构造消息结构
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_iovlen = 1;
    msg.msg_iov = &amp;iov;
    iov.iov_len = size;
    iov.iov_base = ubuf;
    msg.msg_name = (struct sockaddr *)&amp;address;
    msg.msg_namelen = sizeof(address);

    // 4. 设置标志
    if (sock-&gt;file-&gt;f_flags &amp; O_NONBLOCK)
        flags |= MSG_DONTWAIT;

    // 5. 调用接收函数
    err = sock_recvmsg(sock, &amp;msg, size, flags);

    // 6. 拷贝地址信息到用户空间
    if (err &gt;= 0 &amp;&amp; addr != NULL) {
        err2 = move_addr_to_user(&amp;address,
                                msg.msg_namelen, addr, addr_len);
        if (err2 &lt; 0)
            err = err2;
    }

    fput_light(sock-&gt;file, fput_needed);
out:
    return err;
}
6.2 tcp_recvmsg实现
int tcp_recvmsg(struct kiocb *iocb, struct sock *sk, struct msghdr *msg,
                size_t len, int nonblock, int flags, int *addr_len) {
    struct tcp_sock *tp = tcp_sk(sk);
    int copied = 0;
    u32 peek_seq;
    u32 *seq;
    unsigned long used;
    int err;
    int target;        /* Read at least this many bytes */
    long timeo;
    struct task_struct *user_recv = NULL;
    struct sk_buff *skb;
    u32 urg_hole = 0;

    // 1. 参数检查和初始化
    lock_sock(sk);

    err = -ENOTCONN;
    if (sk-&gt;sk_state == TCP_LISTEN)
        goto out;

    timeo = sock_rcvtimeo(sk, nonblock);

    // 2. 处理紧急数据
    if (flags &amp; MSG_OOB)
        goto recv_urg;

    if (unlikely(tp-&gt;repair)) {
        err = -EPERM;
        if (!(flags &amp; MSG_PEEK))
            goto out;

        if (tp-&gt;repair_queue == TCP_SEND_QUEUE)
            goto recv_sndq;

        err = -EINVAL;
        if (tp-&gt;repair_queue == TCP_NO_QUEUE)
            goto out;
    }

    seq = &amp;tp-&gt;copied_seq;
    if (flags &amp; MSG_PEEK) {
        peek_seq = tp-&gt;copied_seq;
        seq = &amp;peek_seq;
    }

    target = sock_rcvlowat(sk, flags &amp; MSG_WAITALL, len);

    // 3. 主接收循环
    do {
        u32 offset;

        // 检查接收队列
        skb_queue_walk(&amp;sk-&gt;sk_receive_queue, skb) {
            offset = *seq - TCP_SKB_CB(skb)-&gt;seq;

            // 检查数据是否可用
            if (TCP_SKB_CB(skb)-&gt;tcp_flags &amp; TCPHDR_SYN) {
                pr_err_once(&quot;%s: found a SYN, please report !\n&quot;, __func__);
                offset--;
            }
            if (offset &lt; skb-&gt;len)
                goto found_ok_skb;

            // 处理FIN
            if (TCP_SKB_CB(skb)-&gt;tcp_flags &amp; TCPHDR_FIN)
                goto found_fin_ok;
        }

        // 4. 没有数据可读，检查是否需要等待
        if (copied &gt;= target &amp;&amp; !sk-&gt;sk_backlog.tail)
            break;

        if (copied) {
            if (sk-&gt;sk_err ||
                sk-&gt;sk_state == TCP_CLOSE ||
                (sk-&gt;sk_shutdown &amp; RCV_SHUTDOWN) ||
                !timeo ||
                signal_pending(current))
                break;
        } else {
            if (sock_flag(sk, SOCK_DONE))
                break;

            if (sk-&gt;sk_err) {
                copied = sock_error(sk);
                break;
            }

            if (sk-&gt;sk_shutdown &amp; RCV_SHUTDOWN)
                break;

            if (sk-&gt;sk_state == TCP_CLOSE) {
                if (!sock_flag(sk, SOCK_DONE)) {
                    copied = -ENOTCONN;
                    break;
                }
                break;
            }

            if (!timeo) {
                copied = -EAGAIN;
                break;
            }

            if (signal_pending(current)) {
                copied = sock_intr_errno(timeo);
                break;
            }
        }

        // 5. 等待数据到达
        tcp_cleanup_rbuf(sk, copied);

        if (!sysctl_tcp_low_latency &amp;&amp; tp-&gt;ucopy.task == user_recv) {
            if (tp-&gt;rcv_nxt == tp-&gt;copied_seq &amp;&amp;
                len - copied &lt;= tp-&gt;ucopy.len) {

                tcp_prequeue_process(sk);

                if (tp-&gt;rcv_nxt == tp-&gt;copied_seq &amp;&amp;
                    len - copied &lt;= tp-&gt;ucopy.len) {
                    tp-&gt;ucopy.len = len - copied;

                    if (tp-&gt;ucopy.len == 0) {
                        tp-&gt;ucopy.task = NULL;
                        tp-&gt;ucopy.len = 0;
                    } else {
                        sk_wait_data(sk, &amp;timeo);
                    }

                    continue;
                }
            }
        }

        sk_wait_data(sk, &amp;timeo);
        continue;

    found_ok_skb:
        // 6. 找到可读数据，开始拷贝
        used = skb-&gt;len - offset;
        if (len &lt; used)
            used = len;

        // 拷贝数据到用户空间
        if (!(flags &amp; MSG_TRUNC)) {
            err = skb_copy_datagram_msg(skb, offset, msg, used);
            if (err) {
                if (!copied)
                    copied = -EFAULT;
                break;
            }
        }

        *seq += used;
        copied += used;
        len -= used;

        // 检查是否读取完整个skb
        if (used + offset &lt; skb-&gt;len)
            continue;

        // 处理TCP标志
        if (TCP_SKB_CB(skb)-&gt;tcp_flags &amp; TCPHDR_FIN)
            goto found_fin_ok;

        // 如果不是peek模式，释放skb
        if (!(flags &amp; MSG_PEEK))
            sk_eat_skb(sk, skb);
        continue;

    found_fin_ok:
        ++*seq;
        if (!(flags &amp; MSG_PEEK))
            sk_eat_skb(sk, skb);
        break;

    } while (len &gt; 0);

    // 7. 清理和返回
    tcp_cleanup_rbuf(sk, copied);

    release_sock(sk);
    return copied;

out:
    release_sock(sk);
    return err;

recv_urg:
    err = tcp_recv_urg(sk, msg, len, flags);
    goto out;

recv_sndq:
    err = tcp_peek_sndq(sk, msg, len);
    goto out;
}
7. 网络中断处理
7.1 网络数据包到达处理
// 网络中断处理函数
static irqreturn_t network_interrupt_handler(int irq, void *dev_id) {
    struct net_device *dev = dev_id;
    struct sk_buff *skb;

    // 从网卡读取数据包
    while ((skb = dev-&gt;netdev_ops-&gt;ndo_rx_read(dev)) != NULL) {
        // 设置skb属性
        skb-&gt;dev = dev;
        skb-&gt;protocol = eth_type_trans(skb, dev);

        // 将数据包加入处理队列
        netif_rx(skb);
    }

    return IRQ_HANDLED;
}

// 软中断处理网络数据包
static void net_rx_action(struct softirq_action *h) {
    struct list_head *list = &amp;__get_cpu_var(softnet_data).poll_list;
    unsigned long time_limit = jiffies + 2;
    int budget = netdev_budget;

    local_irq_disable();

    while (!list_empty(list)) {
        struct napi_struct *n;
        int work, weight;

        if (unlikely(budget &lt;= 0 || time_after(jiffies, time_limit)))
            goto softnet_break;

        local_irq_enable();

        n = list_first_entry(list, struct napi_struct, poll_list);

        weight = n-&gt;weight;

        work = 0;
        if (test_bit(NAPI_STATE_SCHED, &amp;n-&gt;state)) {
            work = n-&gt;poll(n, weight);
            trace_napi_poll(n);
        }

        WARN_ON_ONCE(work &gt; weight);

        budget -= work;

        local_irq_disable();

        if (unlikely(work == weight)) {
            if (unlikely(napi_disable_pending(n))) {
                local_irq_enable();
                napi_complete(n);
                local_irq_disable();
            } else {
                if (n-&gt;gro_list) {
                    local_irq_enable();
                    napi_gro_flush(n, false);
                    local_irq_disable();
                }
                list_move_tail(&amp;n-&gt;poll_list, list);
            }
        }
    }

    local_irq_enable();

softnet_break:
    __raise_softirq_irqoff(NET_RX_SOFTIRQ);

    local_irq_enable();
}
