                connectionSetupTime +    // 连接建立时间 (3-way handshake)
                dataTransmissionTime +   // 数据传输时间
                ackWaitTime +           // 等待确认时间
                connectionTeardownTime; // 连接关闭时间

            // UDP延迟组成
            int udpLatency = 
                dataTransmissionTime;   // 仅数据传输时间

            System.out.println(&quot;TCP总延迟: &quot; + tcpLatency + &quot;ms&quot;);
            System.out.println(&quot;UDP总延迟: &quot; + udpLatency + &quot;ms&quot;);
            System.out.println(&quot;UDP延迟优势: &quot; + (tcpLatency - udpLatency) + &quot;ms&quot;);
        }
    }

    public class ThroughputComparison {
        public void measureThroughput() {
            // TCP有效载荷比例
            double tcpEfficiency = (double) dataSize / (dataSize + tcpHeaderSize + ipHeaderSize);

            // UDP有效载荷比例
            double udpEfficiency = (double) dataSize / (dataSize + udpHeaderSize + ipHeaderSize);

            System.out.println(&quot;TCP传输效率: &quot; + (tcpEfficiency * 100) + &quot;%&quot;);
            System.out.println(&quot;UDP传输效率: &quot; + (udpEfficiency * 100) + &quot;%&quot;);

            // 考虑重传的实际吞吐量
            double tcpActualThroughput = tcpEfficiency * (1 - packetLossRate);
            double udpActualThroughput = udpEfficiency; // 不重传

            System.out.println(&quot;TCP实际吞吐量: &quot; + tcpActualThroughput);
            System.out.println(&quot;UDP实际吞吐量: &quot; + udpActualThroughput);
        }
    }
