5.1 TCP优化
public class TCPOptimization {
    /*
     * TCP性能优化技术：
     * 
     * 1. 窗口缩放
     * 2. 选择性确认 (SACK)
     * 3. 时间戳选项
     * 4. TCP快速打开 (TFO)
     */

    public class WindowScaling {
        // RFC 1323: 窗口缩放选项
        public void enableWindowScaling() {
            // 窗口缩放因子 (0-14)
            int windowScale = 7; // 2^7 = 128倍缩放

            // 最大窗口大小
            int maxWindow = 65535 * (1 &lt;&lt; windowScale); // 8MB

            // 在SYN段中协商窗口缩放
            TCPOption windowScaleOption = new TCPOption();
            windowScaleOption.kind = 3;     // 窗口缩放选项
            windowScaleOption.length = 3;
            windowScaleOption.data = new byte[]{(byte) windowScale};
        }
    }

    public class SelectiveAcknowledgment {
        // RFC 2018: 选择性确认
        private final List&lt;SACKBlock&gt; sackBlocks = new ArrayList&lt;&gt;();

        public void processSACK(TCPSegment segment) {
            if (segment.hasSACKOption()) {
                List&lt;SACKBlock&gt; blocks = parseSACKBlocks(segment);

                for (SACKBlock block : blocks) {
                    // 标记已接收的数据块
                    markAsReceived(block.leftEdge, block.rightEdge);
                }

                // 重传未确认的段
                retransmitMissingSegments();
            }
        }

        static class SACKBlock {
            int leftEdge;   // 块的左边界
            int rightEdge;  // 块的右边界
        }
    }

    public class TCPFastOpen {
        // RFC 7413: TCP快速打开
        private final Map&lt;String, byte[]&gt; cookieCache = new HashMap&lt;&gt;();

        public void sendWithTFO(String serverIP, byte[] data) {
            byte[] cookie = cookieCache.get(serverIP);

            if (cookie != null) {
                // 使用缓存的cookie直接发送数据
                TCPSegment synData = new TCPSegment();
                synData.syn = true;
                synData.data = data;
                synData.options = createTFOOption(cookie);

                sendSegment(synData);
            } else {
                // 首次连接，请求cookie
                requestTFOCookie(serverIP);
            }
        }
    }
}
5.2 UDP优化
public class UDPOptimization {
    /*
     * UDP性能优化技术：
     * 
     * 1. 应用层可靠性
     * 2. 自适应速率控制
     * 3. 数据包聚合
     * 4. 前向纠错 (FEC)
     */

    public class ReliableUDP {
        private final Map&lt;Integer, UDPPacket&gt; sentPackets = new HashMap&lt;&gt;();
        private final Set&lt;Integer&gt; ackedPackets = new HashSet&lt;&gt;();
        private int sequenceNumber = 0;

        public void sendReliably(byte[] data) {
            UDPPacket packet = new UDPPacket();
            packet.sequenceNumber = sequenceNumber++;
            packet.data = data;
            packet.timestamp = System.currentTimeMillis();

            // 发送数据包
            sendUDPPacket(packet);
            sentPackets.put(packet.sequenceNumber, packet);

            // 启动重传定时器
            scheduleRetransmission(packet.sequenceNumber);
        }

        public void receiveAck(int ackNumber) {
            ackedPackets.add(ackNumber);
            sentPackets.remove(ackNumber);
            cancelRetransmission(ackNumber);
        }

        private void scheduleRetransmission(int seqNum) {
            Timer timer = new Timer();
            timer.schedule(new TimerTask() {
                @Override
                public void run() {
                    if (!ackedPackets.contains(seqNum)) {
                        UDPPacket packet = sentPackets.get(seqNum);
                        if (packet != null) {
                            sendUDPPacket(packet); // 重传
                        }
                    }
                }
            }, calculateRTO());
        }
    }

    public class AdaptiveRateControl {
        private double sendingRate = 1.0; // 包/秒
        private long lastLossTime = 0;
        private int consecutiveLosses = 0;

        public void adjustRate(boolean packetLost) {
            if (packetLost) {
                consecutiveLosses++;
                lastLossTime = System.currentTimeMillis();

                // 减少发送速率
                sendingRate *= 0.8;
                sendingRate = Math.max(sendingRate, 0.1);

            } else {
                consecutiveLosses = 0;

                // 缓慢增加发送速率
                if (System.currentTimeMillis() - lastLossTime &gt; 1000) {
                    sendingRate *= 1.05;
                    sendingRate = Math.min(sendingRate, 100.0);
                }
            }
        }

        public long getInterPacketInterval() {
            return (long) (1000.0 / sendingRate);
        }
    }
}
6. 小结
传输层协议的核心特点：
6.1 TCP协议优势

可靠性：保证数据完整性和顺序
流量控制：防止接收方缓冲区溢出
拥塞控制：避免网络拥塞
连接管理：规范的连接建立和释放

6.2 UDP协议优势

简单高效：最小的协议开销
实时性好：无连接建立延迟
支持广播：一对多通信
保持边界：维护消息完整性

6.3 选择原则

可靠性优先：选择TCP（Web浏览、文件传输、邮件）
实时性优先：选择UDP（视频流、在线游戏、DNS）
简单查询：选择UDP（SNMP、DHCP）
大数据传输：选择TCP（文件下载、数据库同步）

传输层为应用层提供了端到端的数据传输服务，是网络通信可靠性的重要保障。

