1.1 sk_buff结构体详解
struct sk_buff {
    union {
        struct {
            /* 链表指针 */
            struct sk_buff *next;
            struct sk_buff *prev;

            union {
                ktime_t tstamp;
                struct skb_mstamp skb_mstamp;
            };
        };
        struct rb_node rbnode; /* 红黑树节点，用于TCP乱序队列 */
        struct list_head list;
    };

    /* 关联的socket */
    struct sock *sk;

    /* 网络设备 */
    struct net_device *dev;

    /* 数据指针 - 核心部分 */
    unsigned char *head;        /* 缓冲区开始位置 */
    unsigned char *data;        /* 数据开始位置 */
    unsigned char *tail;        /* 数据结束位置 */
    unsigned char *end;         /* 缓冲区结束位置 */

    /* 长度信息 */
    unsigned int len;           /* 数据总长度 */
    unsigned int data_len;      /* 分片数据长度 */

    /* 校验和 */
    __wsum csum;
    __u8 csum_valid:1;
    __u8 csum_complete_sw:1;
    __u8 csum_level:2;
    __u8 csum_bad:1;

    /* IP相关 */
    __u8 ip_summed:2;
    __u8 nohdr:1;
    __u8 nfctinfo:3;
    __u8 pkt_type:3;
    __u8 fclone:2;
    __u8 ipvs_property:1;
    __u8 peeked:1;
    __u8 nf_trace:1;

    /* 协议信息 */
    __be16 protocol;            /* 协议类型 */

    /* 析构函数 */
    void (*destructor)(struct sk_buff *skb);

    /* 网络命名空间 */
    struct net *dev_net;

    /* 控制缓冲区 */
    char cb[48] __aligned(8);   /* 控制缓冲区，各层协议私有数据 */

    /* 分片信息 */
    unsigned long _skb_refdst;
    void (*destructor)(struct sk_buff *skb);
    struct sec_path *sp;

    /* 队列映射 */
    __u16 queue_mapping;
