    /* VLAN信息 */
    __be16 vlan_proto;
    __u16 vlan_tci;

    /* 传输层头部偏移 */
    __u16 transport_header;
    __u16 network_header;
    __u16 mac_header;

    /* 分片相关 */
    struct skb_shared_info *shinfo;
};
1.2 sk_buff内存布局
sk_buff结构体内存布局：

+-------------------+
|   sk_buff 结构    |  &lt;- 控制信息
+-------------------+
|                   |
|   head            |  &lt;- 指向数据缓冲区开始
|   data            |  &lt;- 指向有效数据开始  
|   tail            |  &lt;- 指向有效数据结束
|   end             |  &lt;- 指向数据缓冲区结束
|                   |
+-------------------+
|                   |
|   数据缓冲区       |  &lt;- 实际网络数据
|                   |
+-------------------+
| skb_shared_info   |  &lt;- 分片信息
+-------------------+

内存指针关系：
head &lt;= data &lt;= tail &lt;= end

可用空间：
- headroom: data - head  (用于添加头部)
- tailroom: end - tail   (用于添加尾部)
- 数据长度: tail - data

