// HTTP请求完整流程模拟
public class HTTPCommunicationFlow {

    public static class HTTPClient {
        private String serverHost;
        private int serverPort;

        public HTTPClient(String host, int port) {
            this.serverHost = host;
            this.serverPort = port;
        }

        public String sendHTTPRequest(String path) {
            try {
                // 1. 应用层：构造HTTP请求
                String httpRequest = buildHTTPRequest(path);
                System.out.println(&quot;应用层：构造HTTP请求&quot;);
                System.out.println(httpRequest);

                // 2. 传输层：建立TCP连接
                Socket socket = new Socket(serverHost, serverPort);
                System.out.println(&quot;传输层：建立TCP连接到 &quot; + serverHost + &quot;:&quot; + serverPort);

                // 3. 传输层：发送数据
                OutputStream out = socket.getOutputStream();
                out.write(httpRequest.getBytes());
                out.flush();
                System.out.println(&quot;传输层：发送TCP段&quot;);

                // 4. 传输层：接收响应
                InputStream in = socket.getInputStream();
                BufferedReader reader = new BufferedReader(new InputStreamReader(in));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = reader.readLine()) != null) {
                    response.append(line).append(&quot;\n&quot;);
                }
                System.out.println(&quot;传输层：接收TCP段&quot;);

                // 5. 应用层：解析HTTP响应
                String httpResponse = response.toString();
                System.out.println(&quot;应用层：解析HTTP响应&quot;);
                System.out.println(httpResponse);

                // 6. 传输层：关闭连接
                socket.close();
                System.out.println(&quot;传输层：关闭TCP连接&quot;);

                return httpResponse;

            } catch (IOException e) {
                System.err.println(&quot;通信错误：&quot; + e.getMessage());
                return null;
            }
        }

        private String buildHTTPRequest(String path) {
            return &quot;GET &quot; + path + &quot; HTTP/1.1\r\n&quot; +
                   &quot;Host: &quot; + serverHost + &quot;\r\n&quot; +
                   &quot;Connection: close\r\n&quot; +
                   &quot;\r\n&quot;;
        }
    }

    // 协议栈处理流程
    public static class ProtocolStackProcessor {

        public void processOutgoingData(String httpRequest) {
            System.out.println(&quot;\n=== 发送端协议栈处理 ===&quot;);

            // 应用层
            byte[] appData = httpRequest.getBytes();
            System.out.println(&quot;应用层：HTTP请求数据 (&quot; + appData.length + &quot; 字节)&quot;);

            // 传输层（TCP）
            TCPSegment tcpSegment = new TCPSegment(12345, 80, 1000, appData);
            byte[] tcpData = tcpSegment.encapsulate();
            System.out.println(&quot;传输层：添加TCP头部 (&quot; + tcpData.length + &quot; 字节)&quot;);

            // 网络层（IP）
            IPPacket ipPacket = new IPPacket(&quot;192.168.1.100&quot;, &quot;93.184.216.34&quot;, tcpData);
            byte[] ipData = ipPacket.encapsulate();
            System.out.println(&quot;网络层：添加IP头部 (&quot; + ipData.length + &quot; 字节)&quot;);

            // 数据链路层（以太网）
            EthernetFrame ethFrame = new EthernetFrame(&quot;aa:bb:cc:dd:ee:ff&quot;, &quot;11:22:33:44:55:66&quot;, ipData);
            byte[] frameData = ethFrame.encapsulate();
            System.out.println(&quot;数据链路层：添加以太网头部 (&quot; + frameData.length + &quot; 字节)&quot;);

            // 物理层
            System.out.println(&quot;物理层：转换为电信号并发送&quot;);
        }

        public void processIncomingData(byte[] frameData) {
            System.out.println(&quot;\n=== 接收端协议栈处理 ===&quot;);

            // 物理层
            System.out.println(&quot;物理层：接收电信号并转换为数字数据&quot;);

            // 数据链路层
            System.out.println(&quot;数据链路层：处理以太网帧，移除以太网头部&quot;);

            // 网络层
            System.out.println(&quot;网络层：处理IP数据包，移除IP头部&quot;);

            // 传输层
            System.out.println(&quot;传输层：处理TCP段，移除TCP头部&quot;);

            // 应用层
            System.out.println(&quot;应用层：处理HTTP响应数据&quot;);
        }
    }
}
