2.2 HTTP消息格式
public class HTTPMessage {
    /*
     * HTTP请求格式：
     * 
     * GET /index.html HTTP/1.1
     * Host: www.example.com
     * User-Agent: Mozilla/5.0
     * Accept: text/html,application/xhtml+xml
     * Connection: keep-alive
     * 
     * [请求体]
     */

    public static class HTTPRequest {
        // 请求行
        String method;          // GET, POST, PUT, DELETE等
        String uri;             // 请求的资源路径
        String version;         // HTTP版本

        // 请求头
        Map&lt;String, String&gt; headers = new HashMap&lt;&gt;();

        // 请求体
        byte[] body;

        public HTTPRequest(String method, String uri, String version) {
            this.method = method;
            this.uri = uri;
            this.version = version;
        }

        public void addHeader(String name, String value) {
            headers.put(name, value);
        }

        public String toHTTPString() {
            StringBuilder sb = new StringBuilder();

            // 请求行
            sb.append(method).append(&quot; &quot;).append(uri).append(&quot; &quot;).append(version).append(&quot;\r\n&quot;);

            // 请求头
            for (Map.Entry&lt;String, String&gt; header : headers.entrySet()) {
                sb.append(header.getKey()).append(&quot;: &quot;).append(header.getValue()).append(&quot;\r\n&quot;);
            }

            // 空行分隔头部和体
            sb.append(&quot;\r\n&quot;);

            // 请求体
            if (body != null) {
                sb.append(new String(body));
            }

            return sb.toString();
        }
    }

    /*
     * HTTP响应格式：
     * 
     * HTTP/1.1 200 OK
     * Content-Type: text/html
     * Content-Length: 1234
     * Server: Apache/2.4.41
     * Date: Mon, 01 Jan 2024 12:00:00 GMT
     * 
     * &lt;html&gt;...&lt;/html&gt;
     */

    public static class HTTPResponse {
        // 状态行
        String version;         // HTTP版本
        int statusCode;         // 状态码
        String reasonPhrase;    // 状态描述

        // 响应头
        Map&lt;String, String&gt; headers = new HashMap&lt;&gt;();

        // 响应体
        byte[] body;

        public HTTPResponse(String version, int statusCode, String reasonPhrase) {
            this.version = version;
            this.statusCode = statusCode;
            this.reasonPhrase = reasonPhrase;
        }

        public String toHTTPString() {
            StringBuilder sb = new StringBuilder();

            // 状态行
            sb.append(version).append(&quot; &quot;).append(statusCode).append(&quot; &quot;).append(reasonPhrase).append(&quot;\r\n&quot;);

            // 响应头
            for (Map.Entry&lt;String, String&gt; header : headers.entrySet()) {
                sb.append(header.getKey()).append(&quot;: &quot;).append(header.getValue()).append(&quot;\r\n&quot;);
            }

            // 空行分隔头部和体
            sb.append(&quot;\r\n&quot;);

            // 响应体
            if (body != null) {
                sb.append(new String(body));
            }

            return sb.toString();
        }
    }
}
