public class DNSProtocol {
    /*
     * DNS (Domain Name System) 特性：
     * 
     * 1. 分层结构：根域、顶级域、二级域
     * 2. 分布式数据库：全球分布的DNS服务器
     * 3. 缓存机制：提高查询效率
     * 4. 递归和迭代查询：不同的查询方式
     * 5. 多种记录类型：A、AAAA、CNAME、MX等
     */

    public enum DNSRecordType {
        A(1),       // IPv4地址
