        CNAME(5),   // 别名
        MX(15),     // 邮件交换
        AAAA(28),   // IPv6地址
        PTR(12),    // 指针记录（反向查询）
        TXT(16);    // 文本记录

        private final int value;

        DNSRecordType(int value) {
            this.value = value;
        }

        public int getValue() { return value; }
    }
}
5.2 DNS消息格式
public class DNSMessage {
    /*
     * DNS消息格式：
     * 
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |                      ID                       |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |QR|   Opcode  |AA|TC|RD|RA|   Z    |   RCODE   |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |                    QDCOUNT                    |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |                    ANCOUNT                    |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |                    NSCOUNT                    |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     * |                    ARCOUNT                    |
     * +--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+--+
     */

    public static class DNSHeader {
        short id;           // 查询标识
        boolean qr;         // 查询/响应标志
        byte opcode;        // 操作码
        boolean aa;         // 权威答案
        boolean tc;         // 截断标志
        boolean rd;         // 期望递归
        boolean ra;         // 递归可用
        byte rcode;         // 响应码

        short qdcount;      // 问题数
        short ancount;      // 答案数
        short nscount;      // 权威记录数
        short arcount;      // 附加记录数

        public byte[] toBytes() {
            ByteBuffer buffer = ByteBuffer.allocate(12);

            buffer.putShort(id);

            // 标志字段
            int flags = 0;
            if (qr) flags |= 0x8000;
            flags |= (opcode &amp; 0x0F) &lt;&lt; 11;
            if (aa) flags |= 0x0400;
            if (tc) flags |= 0x0200;
            if (rd) flags |= 0x0100;
            if (ra) flags |= 0x0080;
            flags |= rcode &amp; 0x0F;
            buffer.putShort((short) flags);

            buffer.putShort(qdcount);
            buffer.putShort(ancount);
            buffer.putShort(nscount);
            buffer.putShort(arcount);

            return buffer.array();
        }
    }

    public static class DNSQuestion {
        String qname;       // 查询名称
        short qtype;        // 查询类型
        short qclass;       // 查询类别 (通常为1，表示Internet)

        public DNSQuestion(String domain, DNSRecordType type) {
            this.qname = domain;
            this.qtype = (short) type.getValue();
            this.qclass = 1; // IN (Internet)
        }

        public byte[] toBytes() {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();

            // 编码域名
            String[] labels = qname.split(&quot;\\.&quot;);
            for (String label : labels) {
                baos.write(label.length());
                baos.write(label.getBytes(), 0, label.length());
            }
            baos.write(0); // 结束标志

            // 添加类型和类别
            ByteBuffer buffer = ByteBuffer.allocate(4);
            buffer.putShort(qtype);
            buffer.putShort(qclass);
            baos.write(buffer.array(), 0, 4);

            return baos.toByteArray();
        }
    }

    public static class DNSRecord {
        String name;        // 记录名称
        short type;         // 记录类型
        short rclass;       // 记录类别
        int ttl;            // 生存时间
        short rdlength;     // 数据长度
        byte[] rdata;       // 记录数据

        public static DNSRecord createARecord(String name, String ipAddress, int ttl) {
            DNSRecord record = new DNSRecord();
            record.name = name;
            record.type = (short) DNSRecordType.A.getValue();
            record.rclass = 1;
            record.ttl = ttl;

            // 将IP地址转换为字节数组
            String[] parts = ipAddress.split(&quot;\\.&quot;);
            record.rdata = new byte[4];
            for (int i = 0; i &lt; 4; i++) {
                record.rdata[i] = (byte) Integer.parseInt(parts[i]);
            }
            record.rdlength = 4;

            return record;
        }

        public String getIPAddress() {
            if (type == DNSRecordType.A.getValue() &amp;&amp; rdata.length == 4) {
                return String.format(&quot;%d.%d.%d.%d&quot;,
                    rdata[0] &amp; 0xFF, rdata[1] &amp; 0xFF,
                    rdata[2] &amp; 0xFF, rdata[3] &amp; 0xFF);
            }
            return null;
        }
    }
}
5.3 DNS客户端实现
public class DNSClient {
    private final String dnsServer;
    private final int dnsPort;
    private final Random random = new Random();

    public DNSClient(String dnsServer, int dnsPort) {
        this.dnsServer = dnsServer;
        this.dnsPort = dnsPort;
    }

    public List&lt;String&gt; resolveA(String domain) {
        try {
            // 构造DNS查询
            DNSMessage.DNSHeader header = new DNSMessage.DNSHeader();
            header.id = (short) random.nextInt(65536);
            header.rd = true; // 期望递归查询
            header.qdcount = 1;

            DNSMessage.DNSQuestion question = new DNSMessage.DNSQuestion(domain, DNSRecordType.A);

            // 组装查询消息
            ByteArrayOutputStream queryStream = new ByteArrayOutputStream();
            queryStream.write(header.toBytes());
            queryStream.write(question.toBytes());
            byte[] queryData = queryStream.toByteArray();

            // 发送UDP查询
            try (DatagramSocket socket = new DatagramSocket()) {
                DatagramPacket queryPacket = new DatagramPacket(
                    queryData, queryData.length,
                    InetAddress.getByName(dnsServer), dnsPort);
                socket.send(queryPacket);

                // 接收响应
                byte[] responseBuffer = new byte[512];
                DatagramPacket responsePacket = new DatagramPacket(responseBuffer, responseBuffer.length);
                socket.setSoTimeout(5000); // 5秒超时
                socket.receive(responsePacket);

                // 解析响应
                return parseDNSResponse(responsePacket.getData(), responsePacket.getLength());
            }

        } catch (Exception e) {
            e.printStackTrace();
            return new ArrayList&lt;&gt;();
        }
    }

    private List&lt;String&gt; parseDNSResponse(byte[] data, int length) {
        List&lt;String&gt; addresses = new ArrayList&lt;&gt;();
        ByteBuffer buffer = ByteBuffer.wrap(data, 0, length);

        // 解析头部
        short id = buffer.getShort();
        short flags = buffer.getShort();
        short qdcount = buffer.getShort();
        short ancount = buffer.getShort();
        short nscount = buffer.getShort();
        short arcount = buffer.getShort();

        // 检查响应码
        int rcode = flags &amp; 0x0F;
        if (rcode != 0) {
            System.err.println(&quot;DNS query failed with rcode: &quot; + rcode);
            return addresses;
        }

        // 跳过问题部分
        for (int i = 0; i &lt; qdcount; i++) {
            skipDNSName(buffer);
            buffer.getShort(); // qtype
            buffer.getShort(); // qclass
        }

        // 解析答案部分
        for (int i = 0; i &lt; ancount; i++) {
            skipDNSName(buffer);
            short type = buffer.getShort();
            short rclass = buffer.getShort();
            int ttl = buffer.getInt();
            short rdlength = buffer.getShort();

            if (type == DNSRecordType.A.getValue() &amp;&amp; rdlength == 4) {
                // 读取IPv4地址
                byte[] addr = new byte[4];
                buffer.get(addr);
                String ipAddress = String.format(&quot;%d.%d.%d.%d&quot;,
                    addr[0] &amp; 0xFF, addr[1] &amp; 0xFF,
                    addr[2] &amp; 0xFF, addr[3] &amp; 0xFF);
                addresses.add(ipAddress);
            } else {
                // 跳过其他类型的记录
                buffer.position(buffer.position() + rdlength);
            }
        }

        return addresses;
    }

    private void skipDNSName(ByteBuffer buffer) {
        while (true) {
            byte length = buffer.get();
            if (length == 0) break;

            if ((length &amp; 0xC0) == 0xC0) {
                // 压缩指针
                buffer.get(); // 跳过低字节
                break;
            } else {
                // 普通标签
                buffer.position(buffer.position() + length);
            }
        }
    }
}
6. 邮件协议详解
6.1 SMTP协议
public class SMTPProtocol {
    /*
     * SMTP (Simple Mail Transfer Protocol) 特性：
     * 
     * 1. 推送协议：发送邮件到服务器
     * 2. 文本协议：命令和响应都是文本
     * 3. 连接导向：基于TCP连接
     * 4. 状态机：严格的命令序列
     */

    public class SMTPClient {
        private Socket socket;
        private BufferedReader reader;
        private PrintWriter writer;

        public boolean connect(String smtpServer, int port) {
            try {
                socket = new Socket(smtpServer, port);
                reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                writer = new PrintWriter(socket.getOutputStream(), true);

                // 读取服务器欢迎消息
                String response = reader.readLine();
                return response.startsWith(&quot;220&quot;);

            } catch (IOException e) {
                return false;
            }
        }

        public boolean sendEmail(String from, String to, String subject, String body) {
            try {
                // HELO命令
                writer.println(&quot;HELO client.example.com&quot;);
                if (!readResponse().startsWith(&quot;250&quot;)) return false;

                // MAIL FROM命令
                writer.println(&quot;MAIL FROM:&lt;&quot; + from + &quot;&gt;&quot;);
                if (!readResponse().startsWith(&quot;250&quot;)) return false;

                // RCPT TO命令
                writer.println(&quot;RCPT TO:&lt;&quot; + to + &quot;&gt;&quot;);
                if (!readResponse().startsWith(&quot;250&quot;)) return false;

                // DATA命令
                writer.println(&quot;DATA&quot;);
                if (!readResponse().startsWith(&quot;354&quot;)) return false;

                // 发送邮件内容
                writer.println(&quot;From: &quot; + from);
                writer.println(&quot;To: &quot; + to);
                writer.println(&quot;Subject: &quot; + subject);
                writer.println(&quot;Date: &quot; + new Date());
                writer.println(&quot;Content-Type: text/plain; charset=UTF-8&quot;);
                writer.println();
                writer.println(body);
                writer.println(&quot;.&quot;); // 结束标志

                if (!readResponse().startsWith(&quot;250&quot;)) return false;

                // QUIT命令
                writer.println(&quot;QUIT&quot;);
                readResponse();

                return true;

            } catch (IOException e) {
                return false;
            } finally {
                closeConnection();
            }
        }

        private String readResponse() throws IOException {
            return reader.readLine();
        }

        private void closeConnection() {
            try {
                if (socket != null) socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
6.2 POP3协议
public class POP3Protocol {
    /*
     * POP3 (Post Office Protocol 3) 特性：
     * 
     * 1. 拉取协议：从服务器下载邮件
     * 2. 离线处理：下载后删除服务器邮件
     * 3. 简单协议：基本的邮件操作
     * 4. 单向同步：不支持多设备同步
     */

    public class POP3Client {
        private Socket socket;
        private BufferedReader reader;
        private PrintWriter writer;

        public boolean connect(String pop3Server, int port) {
            try {
                socket = new Socket(pop3Server, port);
                reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                writer = new PrintWriter(socket.getOutputStream(), true);

                // 读取服务器欢迎消息
                String response = reader.readLine();
                return response.startsWith(&quot;+OK&quot;);

            } catch (IOException e) {
                return false;
            }
        }

        public boolean login(String username, String password) {
            try {
                // USER命令
                writer.println(&quot;USER &quot; + username);
                if (!readResponse().startsWith(&quot;+OK&quot;)) return false;

                // PASS命令
                writer.println(&quot;PASS &quot; + password);
                return readResponse().startsWith(&quot;+OK&quot;);

            } catch (IOException e) {
                return false;
            }
        }

        public int getMessageCount() {
            try {
                writer.println(&quot;STAT&quot;);
                String response = readResponse();
                if (response.startsWith(&quot;+OK&quot;)) {
                    String[] parts = response.split(&quot; &quot;);
                    return Integer.parseInt(parts[1]);
                }
            } catch (IOException | NumberFormatException e) {
                e.printStackTrace();
            }
            return 0;
        }

        public String retrieveMessage(int messageNumber) {
            try {
                writer.println(&quot;RETR &quot; + messageNumber);
                String response = readResponse();

                if (response.startsWith(&quot;+OK&quot;)) {
                    StringBuilder message = new StringBuilder();
                    String line;
                    while ((line = reader.readLine()) != null) {
                        if (&quot;.&quot;.equals(line)) break;
                        message.append(line).append(&quot;\n&quot;);
                    }
                    return message.toString();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
            return null;
        }

        public boolean deleteMessage(int messageNumber) {
            try {
                writer.println(&quot;DELE &quot; + messageNumber);
                return readResponse().startsWith(&quot;+OK&quot;);
            } catch (IOException e) {
                return false;
            }
        }

        private String readResponse() throws IOException {
            return reader.readLine();
        }
    }
}
7. 应用层协议性能优化
7.1 HTTP性能优化
public class HTTPOptimization {
    /*
     * HTTP性能优化技术：
     * 
     * 1. 连接复用：Keep-Alive
     * 2. 压缩传输：Gzip, Brotli
     * 3. 缓存策略：强缓存、协商缓存
     * 4. 资源合并：CSS/JS合并
     * 5. CDN加速：内容分发网络
     */

    public class ConnectionPooling {
        private final Map&lt;String, Queue&lt;Socket&gt;&gt; connectionPool = new HashMap&lt;&gt;();
        private final int maxConnectionsPerHost = 10;
        private final long connectionTimeout = 30000; // 30秒

        public Socket getConnection(String host, int port) {
            String key = host + &quot;:&quot; + port;
            Queue&lt;Socket&gt; connections = connectionPool.get(key);

            if (connections != null &amp;&amp; !connections.isEmpty()) {
                Socket socket = connections.poll();
                if (isConnectionValid(socket)) {
                    return socket;
                }
            }

            // 创建新连接
            try {
                Socket socket = new Socket(host, port);
                socket.setKeepAlive(true);
                socket.setSoTimeout((int) connectionTimeout);
                return socket;
            } catch (IOException e) {
                return null;
            }
        }

        public void returnConnection(String host, int port, Socket socket) {
            String key = host + &quot;:&quot; + port;
            Queue&lt;Socket&gt; connections = connectionPool.computeIfAbsent(key, k -&gt; new LinkedList&lt;&gt;());

            if (connections.size() &lt; maxConnectionsPerHost &amp;&amp; isConnectionValid(socket)) {
                connections.offer(socket);
            } else {
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private boolean isConnectionValid(Socket socket) {
            return socket != null &amp;&amp; socket.isConnected() &amp;&amp; !socket.isClosed();
        }
    }

    public class CompressionHandler {
        public byte[] compressResponse(byte[] data, String acceptEncoding) {
            if (acceptEncoding != null) {
                if (acceptEncoding.contains(&quot;gzip&quot;)) {
                    return gzipCompress(data);
                } else if (acceptEncoding.contains(&quot;deflate&quot;)) {
                    return deflateCompress(data);
                }
            }
            return data;
        }

        private byte[] gzipCompress(byte[] data) {
            try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                 GZIPOutputStream gzipOut = new GZIPOutputStream(baos)) {

                gzipOut.write(data);
                gzipOut.finish();
                return baos.toByteArray();

            } catch (IOException e) {
                return data; // 压缩失败，返回原数据
            }
        }
    }
}
7.2 DNS优化
public class DNSOptimization {
    /*
     * DNS优化技术：
     * 
     * 1. DNS缓存：减少查询次数
     * 2. 预解析：提前解析域名
     * 3. 负载均衡：多IP轮询
     * 4. 故障转移：备用DNS服务器
     */

    public class DNSCache {
        private final Map&lt;String, CacheEntry&gt; cache = new ConcurrentHashMap&lt;&gt;();
        private final ScheduledExecutorService cleanupExecutor = Executors.newScheduledThreadPool(1);

        public DNSCache() {
            // 定期清理过期缓存
            cleanupExecutor.scheduleAtFixedRate(this::cleanupExpiredEntries, 60, 60, TimeUnit.SECONDS);
        }

        public List&lt;String&gt; resolve(String domain) {
            CacheEntry entry = cache.get(domain);

            if (entry != null &amp;&amp; !entry.isExpired()) {
                return new ArrayList&lt;&gt;(entry.addresses);
            }

            // 缓存未命中或已过期，执行DNS查询
            List&lt;String&gt; addresses = performDNSQuery(domain);
            if (!addresses.isEmpty()) {
                cache.put(domain, new CacheEntry(addresses, calculateTTL(domain)));
            }

            return addresses;
        }

        public void preResolve(List&lt;String&gt; domains) {
            // 预解析域名
            for (String domain : domains) {
                CompletableFuture.runAsync(() -&gt; resolve(domain));
            }
        }

        private void cleanupExpiredEntries() {
            cache.entrySet().removeIf(entry -&gt; entry.getValue().isExpired());
        }

        static class CacheEntry {
            final List&lt;String&gt; addresses;
            final long expiryTime;

            CacheEntry(List&lt;String&gt; addresses, int ttl) {
                this.addresses = new ArrayList&lt;&gt;(addresses);
                this.expiryTime = System.currentTimeMillis() + ttl * 1000L;
            }

            boolean isExpired() {
                return System.currentTimeMillis() &gt; expiryTime;
            }
        }
    }
}
8. 小结
应用层协议的核心特点：
8.1 协议特性对比
┌─────────────┬─────────────┬─────────────┬─────────────┐
│   协议      │    用途     │    特点     │   端口      │
├─────────────┼─────────────┼─────────────┼─────────────┤
│ HTTP/HTTPS  │ Web浏览     │ 无状态      │ 80/443      │
│ FTP         │ 文件传输    │ 双连接      │ 21/20       │
│ SMTP        │ 邮件发送    │ 推送协议    │ 25/587      │
│ POP3/IMAP   │ 邮件接收    │ 拉取协议    │ 110/143     │
│ DNS         │ 域名解析    │ 分布式      │ 53          │
│ SSH         │ 远程登录    │ 加密传输    │ 22          │
│ Telnet      │ 远程登录    │ 明文传输    │ 23          │
└─────────────┴─────────────┴─────────────┴─────────────┘

8.2 选择原则

Web应用：HTTP/HTTPS（安全性优先选HTTPS）
文件传输：FTP/SFTP（安全性优先选SFTP）
邮件系统：SMTP+POP3/IMAP
域名解析：DNS（必需服务）
远程管理：SSH（安全）或Telnet（简单）

8.3 性能优化要点

连接复用：减少连接建立开销
数据压缩：减少传输数据量
缓存机制：减少重复请求
负载均衡：提高系统可用性
安全传输：保护数据安全

应用层协议直接为用户应用提供服务，是网络协议栈的最终体现。

