简易协议实现示例
1. 最简单的协议实现
让我们从一个最简单的”问候协议”开始，理解协议的本质。
1.1 协议定义
问候协议（Greeting Protocol）规范：
1. 语法格式：
   请求：HELLO &lt;name&gt;
   响应：HI &lt;name&gt;, NICE TO MEET YOU

2. 语义规则：
   - HELLO：问候命令
   - &lt;name&gt;：发送者姓名
   - HI：响应标识
   - NICE TO MEET YOU：固定回复

3. 时序规则：
   - 客户端先发送HELLO
   - 服务器必须回复HI
   - 一次完整交互后连接关闭

1.2 Java实现示例
服务器端实现
import java.io.*;
import java.net.*;

public class GreetingServer {
    private static final int PORT = 8080;

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println(&quot;问候协议服务器启动，监听端口: &quot; + PORT);

        while (true) {
            Socket clientSocket = serverSocket.accept();
            handleClient(clientSocket);
        }
    }

    private static void handleClient(Socket clientSocket) throws IOException {
        BufferedReader in = new BufferedReader(
            new InputStreamReader(clientSocket.getInputStream()));
        PrintWriter out = new PrintWriter(
            clientSocket.getOutputStream(), true);

        // 读取客户端请求
        String request = in.readLine();
        System.out.println(&quot;收到请求: &quot; + request);

        // 协议解析和处理
        String response = processGreetingProtocol(request);

        // 发送响应
        out.println(response);
        System.out.println(&quot;发送响应: &quot; + response);

        // 关闭连接
        clientSocket.close();
    }

    private static String processGreetingProtocol(String request) {
        // 协议解析：检查格式是否符合 &quot;HELLO &lt;name&gt;&quot;
        if (request == null || !request.startsWith(&quot;HELLO &quot;)) {
            return &quot;ERROR: INVALID FORMAT&quot;;
        }

        // 提取姓名
        String name = request.substring(6); // 去掉&quot;HELLO &quot;

        // 生成协议响应
        return &quot;HI &quot; + name + &quot;, NICE TO MEET YOU&quot;;
    }
}
