1.3 协议交互过程
客户端                    服务器
   │                        │
   │──── HELLO Alice ────→  │  (1) 发送请求
   │                        │  (2) 解析协议
   │                        │  (3) 生成响应
   │ ←── HI Alice, NICE ──── │  (4) 发送响应
   │     TO MEET YOU        │
   │                        │
   └──── 连接关闭 ────────── │

2. 进阶协议：简易HTTP协议
2.1 协议规范
请求格式：
GET /path HTTP/1.0
Host: hostname

响应格式：
HTTP/1.0 200 OK
Content-Type: text/html
Content-Length: &lt;length&gt;

&lt;html content&gt;

2.2 实现示例
public class SimpleHttpServer {
    private static final int PORT = 8080;

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println(&quot;简易HTTP服务器启动，端口: &quot; + PORT);

        while (true) {
            Socket clientSocket = serverSocket.accept();
            handleHttpRequest(clientSocket);
        }
    }

    private static void handleHttpRequest(Socket clientSocket) throws IOException {
        BufferedReader in = new BufferedReader(
            new InputStreamReader(clientSocket.getInputStream()));
        PrintWriter out = new PrintWriter(
            clientSocket.getOutputStream(), true);

        // 读取HTTP请求行
        String requestLine = in.readLine();
        System.out.println(&quot;请求行: &quot; + requestLine);

        // 读取请求头（简化处理）
        String line;
        while ((line = in.readLine()) != null &amp;&amp; !line.isEmpty()) {
            System.out.println(&quot;请求头: &quot; + line);
        }

        // 解析请求
        HttpRequest request = parseHttpRequest(requestLine);

        // 生成响应
        String response = generateHttpResponse(request);

        // 发送响应
        out.print(response);
        out.flush();

        clientSocket.close();
    }

    private static HttpRequest parseHttpRequest(String requestLine) {
        String[] parts = requestLine.split(&quot; &quot;);
        return new HttpRequest(parts[0], parts[1], parts[2]);
    }

    private static String generateHttpResponse(HttpRequest request) {
        String content = &quot;&lt;html&gt;&lt;body&gt;&lt;h1&gt;Hello from Simple HTTP Server!&lt;/h1&gt;&quot; +
                        &quot;&lt;p&gt;You requested: &quot; + request.path + &quot;&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;&quot;;

        return &quot;HTTP/1.0 200 OK\r\n&quot; +
               &quot;Content-Type: text/html\r\n&quot; +
               &quot;Content-Length: &quot; + content.length() + &quot;\r\n&quot; +
               &quot;\r\n&quot; +
               content;
    }

    static class HttpRequest {
        String method;
        String path;
        String version;

        HttpRequest(String method, String path, String version) {
            this.method = method;
            this.path = path;
            this.version = version;
        }
    }
}
3. 协议设计的关键要素
3.1 消息格式设计
// 协议消息的通用结构
public class ProtocolMessage {
    private MessageHeader header;  // 消息头
    private MessageBody body;      // 消息体

    // 消息头包含元信息
    static class MessageHeader {
        int version;        // 协议版本
        int messageType;    // 消息类型
        int messageLength;  // 消息长度
        int sequenceId;     // 序列号
    }

    // 消息体包含实际数据
    static class MessageBody {
        byte[] data;        // 实际数据
    }
}
3.2 状态机实现
public class ProtocolStateMachine {
    enum State {
        INIT,           // 初始状态
        CONNECTED,      // 已连接
        AUTHENTICATED,  // 已认证
        DATA_TRANSFER,  // 数据传输
        CLOSED          // 已关闭
    }

    private State currentState = State.INIT;

    public void handleMessage(Message msg) {
        switch (currentState) {
            case INIT:
                if (msg.type == MessageType.CONNECT) {
                    currentState = State.CONNECTED;
                    sendConnectAck();
                }
                break;

            case CONNECTED:
                if (msg.type == MessageType.AUTH) {
                    if (authenticate(msg)) {
                        currentState = State.AUTHENTICATED;
                        sendAuthSuccess();
                    }
                }
                break;

            case AUTHENTICATED:
                if (msg.type == MessageType.DATA) {
                    currentState = State.DATA_TRANSFER;
                    processData(msg);
                }
                break;

            // ... 其他状态处理
        }
    }
}
3.3 错误处理机制
public class ProtocolErrorHandler {
    enum ErrorCode {
        INVALID_FORMAT(400, &quot;Invalid message format&quot;),
        UNAUTHORIZED(401, &quot;Authentication required&quot;),
        NOT_FOUND(404, &quot;Resource not found&quot;),
        SERVER_ERROR(500, &quot;Internal server error&quot;);

        private final int code;
        private final String message;

        ErrorCode(int code, String message) {
            this.code = code;
            this.message = message;
        }
    }

    public String generateErrorResponse(ErrorCode error) {
        return String.format(&quot;ERROR %d %s\r\n&quot;, error.code, error.message);
    }
}
4. 协议性能优化
4.1 连接复用
// HTTP/1.1 的 Keep-Alive 机制
public class ConnectionPool {
    private Map&lt;String, Socket&gt; connections = new HashMap&lt;&gt;();

    public Socket getConnection(String host, int port) throws IOException {
        String key = host + &quot;:&quot; + port;
        Socket socket = connections.get(key);

        if (socket == null || socket.isClosed()) {
            socket = new Socket(host, port);
            connections.put(key, socket);
        }

        return socket;
    }
}
4.2 数据压缩
// 简单的数据压缩示例
public class ProtocolCompression {
    public byte[] compress(String data) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        GZIPOutputStream gzipOut = new GZIPOutputStream(baos);
        gzipOut.write(data.getBytes(&quot;UTF-8&quot;));
        gzipOut.close();
        return baos.toByteArray();
    }

    public String decompress(byte[] compressed) throws IOException {
        ByteArrayInputStream bais = new ByteArrayInputStream(compressed);
        GZIPInputStream gzipIn = new GZIPInputStream(bais);
        return new String(gzipIn.readAllBytes(), &quot;UTF-8&quot;);
    }
}
5. 协议测试和调试
5.1 协议测试工具
public class ProtocolTester {
    public static void testGreetingProtocol() {
        // 测试正常情况
        String response1 = processGreetingProtocol(&quot;HELLO Alice&quot;);
        assert response1.equals(&quot;HI Alice, NICE TO MEET YOU&quot;);

        // 测试异常情况
        String response2 = processGreetingProtocol(&quot;INVALID&quot;);
        assert response2.equals(&quot;ERROR: INVALID FORMAT&quot;);

