网卡硬件数据传输详解
概述
本文档详细解析网卡硬件层面的数据传输机制，重点说明从网卡驱动调用到物理信号传输的完整过程。这是操作系统跨系统字节数据移动的最底层实现。
1. 网卡硬件传输架构
1.1 传输层次结构
应用数据
    ↓
网卡驱动层 (e1000_xmit_frame)
    ↓
DMA映射层 (e1000_tx_map)
    ↓
硬件描述符层 (e1000_tx_queue)
    ↓
网卡硬件层 (发送描述符 + 寄存器写入)
    ↓
物理层 (信号编码与传输)
    ↓
物理介质 (网线/光纤/无线)

1.2 关键组件说明

发送描述符 (TX Descriptor): 描述待发送数据的元数据结构
DMA引擎: 直接内存访问，绕过CPU进行数据传输
寄存器操作: 通过写入特定寄存器触发硬件动作
物理层编码器: 将数字信号转换为物理信号

2. 发送描述符结构详解
2.1 e1000网卡发送描述符
// Intel e1000网卡发送描述符结构
struct e1000_tx_desc {
    __le64 buffer_addr;     // DMA缓冲区物理地址
    union {
        __le32 data;
        struct {
            __le16 length;      // 数据包长度
            u8 cso;            // 校验和偏移
            u8 cmd;            // 命令字段
        } flags;
    } lower;
    union {
        __le32 data;
        struct {
            u8 status;         // 状态字段
            u8 css;           // 校验和起始位置
            __le16 special;    // 特殊字段(VLAN等)
        } fields;
    } upper;
};
2.2 描述符字段含义






























字段作用说明buffer_addrDMA地址指向实际数据的物理内存地址length数据长度当前描述符对应的数据包大小cmd命令标志控制TSO、校验和、VLAN等功能status状态标志硬件完成传输后设置的状态位
2.3 描述符设置过程
// e1000_tx_queue函数中的描述符设置
static void e1000_tx_queue(struct e1000_adapter *adapter,
                           struct e1000_tx_ring *tx_ring,
                           int count, int tx_flags)
{
    struct e1000_tx_desc *tx_desc = NULL;
    struct e1000_tx_buffer *buffer_info;
    u32 txd_upper = 0, txd_lower = E1000_TXD_CMD_IFCS;

    // 设置TSO标志
    if (tx_flags &amp; E1000_TX_FLAGS_TSO) {
        txd_lower |= E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D;
        txd_upper |= E1000_TXD_POPTS_TXSM &lt;&lt; 8;
    }

    // 设置校验和标志
    if (tx_flags &amp; E1000_TX_FLAGS_CSUM) {
        txd_lower |= E1000_TXD_CMD_DEXT | E1000_TXD_DTYP_D;
        txd_upper |= E1000_TXD_POPTS_TXSM &lt;&lt; 8;
    }

    // 设置VLAN标志
    if (tx_flags &amp; E1000_TX_FLAGS_VLAN) {
        txd_lower |= E1000_TXD_CMD_VLE;
        txd_upper |= (tx_flags &amp; E1000_TX_FLAGS_VLAN_MASK);
    }

    // 填充描述符
    for (i = 0; i &lt; count; i++) {
        buffer_info = &amp;tx_ring-&gt;buffer_info[i];
        tx_desc = E1000_TX_DESC(*tx_ring, i);

        tx_desc-&gt;buffer_addr = cpu_to_le64(buffer_info-&gt;dma);
        tx_desc-&gt;lower.data = cpu_to_le32(txd_lower | buffer_info-&gt;length);
        tx_desc-&gt;upper.data = cpu_to_le32(txd_upper);
    }

    // 设置最后一个描述符的EOP标志
    tx_desc-&gt;lower.data |= cpu_to_le32(E1000_TXD_CMD_EOP);
}
3. 寄存器操作机制
3.1 关键寄存器说明
// e1000网卡关键寄存器定义
#define E1000_TDH      0x03810  // 发送描述符头指针
#define E1000_TDT      0x03818  // 发送描述符尾指针
#define E1000_TDLEN    0x03808  // 发送描述符长度
#define E1000_TDBAL    0x03800  // 发送描述符基地址低32位
#define E1000_TDBAH    0x03804  // 发送描述符基地址高32位
3.2 寄存器写入触发传输
// 通过写入TDT寄存器触发网卡开始传输
static void e1000_tx_queue_trigger(struct e1000_adapter *adapter,
                                   struct e1000_tx_ring *tx_ring,
                                   int count)
{
    // 更新尾指针，通知网卡有新的描述符可处理
    writel(tx_ring-&gt;next_to_use, adapter-&gt;hw.hw_addr + E1000_TDT);

    // 内存屏障确保写入完成
    mmiowb();
}
3.3 寄存器操作时序
1. CPU设置发送描述符
   ↓
2. CPU写入TDT寄存器 (writel)
   ↓
3. 网卡硬件检测到TDT变化
   ↓
4. 网卡开始读取描述符
   ↓
5. 网卡通过DMA读取数据
   ↓
6. 网卡更新TDH寄存器
   ↓
7. 网卡设置描述符状态位

4. 网卡硬件工作流程
4.1 硬件三步工作过程
步骤1: 硬件读取描述符
// 网卡硬件伪代码 - 描述符读取
void hardware_read_descriptors(struct e1000_hw *hw)
{
    u32 tdh = E1000_READ_REG(hw, E1000_TDH);  // 读取头指针
    u32 tdt = E1000_READ_REG(hw, E1000_TDT);  // 读取尾指针

    // 检查是否有新的描述符需要处理
    while (tdh != tdt) {
        struct e1000_tx_desc *desc = &amp;tx_ring[tdh];

        // 读取描述符内容
        u64 buffer_addr = le64_to_cpu(desc-&gt;buffer_addr);
        u16 length = le16_to_cpu(desc-&gt;lower.flags.length);
        u8 cmd = desc-&gt;lower.flags.cmd;

        // 处理当前描述符
        hardware_process_descriptor(buffer_addr, length, cmd);

        // 移动到下一个描述符
        tdh = (tdh + 1) % TX_RING_SIZE;
    }
}
步骤2: 硬件DMA读取数据
// 网卡硬件伪代码 - DMA数据读取
void hardware_dma_read_data(u64 dma_addr, u16 length)
{
    // 通过DMA引擎从内存读取数据到网卡内部缓冲区
    for (int i = 0; i &lt; length; i += DMA_BURST_SIZE) {
        u32 burst_size = min(DMA_BURST_SIZE, length - i);

        // 发起DMA读取请求
        dma_read_request(dma_addr + i, burst_size);

        // 等待DMA完成
        wait_for_dma_completion();

        // 将数据存储到网卡内部FIFO
        store_to_tx_fifo(dma_data, burst_size);
    }
}
步骤3: 物理层编码传输
// 网卡硬件伪代码 - 物理层传输
void hardware_physical_transmit(u8 *frame_data, u16 frame_length)
{
    // 添加以太网前导码和帧起始定界符
    add_preamble_and_sfd();

    // 对每个字节进行物理编码
    for (int i = 0; i &lt; frame_length; i++) {
        u8 byte = frame_data[i];

        // 根据物理层标准进行编码
        switch (phy_standard) {
            case PHY_10BASE_T:
                manchester_encode(byte);
                break;
            case PHY_100BASE_TX:
                nrz_encode(byte);
                break;
            case PHY_1000BASE_T:
                pam5_encode(byte);
                break;
        }

        // 发送编码后的信号
        transmit_signal_to_medium();
    }

    // 添加帧校验序列
    add_frame_check_sequence();
}
5. 物理层信号传输详解
5.1 有线以太网信号传输
// 有线以太网物理层传输伪代码
void phy_transmit_frame(u8 *frame_data, u16 length)
{
    // 1. 信号编码
    switch (link_speed) {
        case SPEED_10:
            // 10Mbps: 曼彻斯特编码
            for (int i = 0; i &lt; length; i++) {
                manchester_encode_byte(frame_data[i]);
            }
            break;

        case SPEED_100:
            // 100Mbps: 4B/5B编码 + MLT-3
            for (int i = 0; i &lt; length; i++) {
                u8 encoded = encode_4b5b(frame_data[i]);
                mlt3_line_encode(encoded);
            }
            break;

        case SPEED_1000:
            // 1000Mbps: 8B/10B编码 + PAM-5
            for (int i = 0; i &lt; length; i++) {
                u16 encoded = encode_8b10b(frame_data[i]);
                pam5_modulate(encoded);
            }
            break;
    }

    // 2. 差分信号输出
    differential_signal_output(encoded_data);

    // 3. 通过变压器耦合到网线
    transformer_coupling_to_wire();
}
5.2 无线网络信号传输
// 无线网络物理层传输伪代码
void wifi_transmit_frame(u8 *frame_data, u16 length)
{
    // 1. 数字调制
    switch (modulation_type) {
        case BPSK:
            bpsk_modulate(frame_data, length);
            break;
        case QPSK:
            qpsk_modulate(frame_data, length);
            break;
        case QAM16:
            qam16_modulate(frame_data, length);
            break;
        case QAM64:
            qam64_modulate(frame_data, length);
            break;
    }

    // 2. OFDM子载波调制
    ofdm_subcarrier_mapping(modulated_symbols);

    // 3. IFFT变换
    ifft_transform(ofdm_symbols);

    // 4. 添加循环前缀
    add_cyclic_prefix();

    // 5. 数字到模拟转换
    dac_conversion(digital_signal);

    // 6. 射频上变频
    rf_upconversion(baseband_signal, carrier_frequency);

    // 7. 功率放大
    power_amplification(rf_signal);

    // 8. 天线辐射
    antenna_radiation(amplified_signal);
}
