7. 关键性能优化机制
7.1 零拷贝技术
// 零拷贝优化 - 直接使用用户空间缓冲区
static int e1000_zero_copy_xmit(struct sk_buff *skb)
{
    // 直接映射用户空间页面，避免内核拷贝
    for (int i = 0; i &lt; skb_shinfo(skb)-&gt;nr_frags; i++) {
        skb_frag_t *frag = &amp;skb_shinfo(skb)-&gt;frags[i];
        dma_addr_t dma = skb_frag_dma_map(dev, frag, 0, 
                                         skb_frag_size(frag), 
                                         DMA_TO_DEVICE);
        // 直接使用DMA地址，无需拷贝
        tx_desc-&gt;buffer_addr = cpu_to_le64(dma);
    }
}
7.2 批量处理优化
// 批量描述符处理
static void e1000_batch_tx_clean(struct e1000_adapter *adapter)
{
    int budget = 64;  // 每次最多处理64个描述符

    while (budget-- &gt; 0) {
        struct e1000_tx_desc *desc = &amp;tx_ring[clean_index];

        if (!(desc-&gt;upper.fields.status &amp; E1000_TXD_STAT_DD))
            break;  // 硬件尚未完成

        // 批量清理已完成的描述符
        clean_tx_descriptor(desc);
        clean_index = (clean_index + 1) % TX_RING_SIZE;
    }
}
8. 总结
网卡硬件数据传输是操作系统跨系统字节数据移动的最底层实现，涉及：

描述符机制: 通过发送描述符描述待传输数据的元信息
DMA技术: 绕过CPU直接进行内存到网卡的数据传输
寄存器操作: 通过写入特定寄存器触发硬件动作
物理层编码: 将数字数据转换为适合传输介质的物理信号
信号传输: 通过电信号、光信号或无线电波进行实际传输

这个过程实现了从应用程序的字节数据到物理介质上信号传输的完整转换，是网络通信的基础。

网络协议专题/HTTP2协议/网络层协议详解.content:
网络层协议详解
1. 网络层协议概述
1.1 网络层的职责
网络层（第3层）是OSI模型中的核心层，主要负责：

路径选择：在多个网络间找到最佳路径
逻辑寻址：使用IP地址标识网络中的设备
数据包转发：将数据包从源主机传递到目标主机
网络互连：连接不同的网络段

1.2 网络层协议族
┌─────────────────────────────────────────────────────────┐
│                    网络层协议族                         │
├─────────────────┬─────────────────┬─────────────────────┤
│   核心协议      │   辅助协议      │   路由协议          │
├─────────────────┼─────────────────┼─────────────────────┤
│ IPv4/IPv6       │ ICMP/ICMPv6     │ RIP, OSPF, BGP      │
│ (数据传输)      │ (错误报告)      │ (路由信息交换)      │
