func (s *GameServer) GameSync(stream pb.GameService_GameSyncServer) error {
    // 创建游戏房间
    room := s.createGameRoom()

    go func() {
        // 接收玩家操作
        for {
            action, err := stream.Recv()
            if err != nil {
                return
            }
            room.ProcessAction(action)
        }
    }()

