        List&lt;List&lt;Integer&gt;&gt; ans = new ArrayList&lt;&gt;();
        if (root == null) {
            return ans;
        }

        Deque&lt;TreeNode&gt; q = new ArrayDeque&lt;&gt;();
        q.addLast(root);

        while (!q.isEmpty()) {
            int size = q.size(); // 当前层的节点数量
            List&lt;Integer&gt; level = new ArrayList&lt;&gt;(size);

            for (int i = 0; i &lt; size; i++) {
