最优解（无注释）
import java.util.*;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        Map&lt;Integer, Integer&gt; pos = new HashMap&lt;&gt;();
        for (int i = 0; i &lt; inorder.length; i++) {
            pos.put(inorder[i], i);
        }
        return dfs(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, pos);
    }

    private TreeNode dfs(int[] preorder, int pl, int pr, int[] inorder, int il, int ir, Map&lt;Integer, Integer&gt; pos) {
        if (pl &gt; pr) {
            return null;
        }
        int rootVal = preorder[pl];
        int k = pos.get(rootVal);
        int leftSize = k - il;
        TreeNode root = new TreeNode(rootVal);
        root.left = dfs(preorder, pl + 1, pl + leftSize, inorder, il, k - 1, pos);
        root.right = dfs(preorder, pl + leftSize + 1, pr, inorder, k + 1, ir, pos);
        return root;
    }
}
最优解（有注释）
import java.util.*;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        // inorder 里每个值的位置，方便 O(1) 找到根在哪
        Map&lt;Integer, Integer&gt; pos = new HashMap&lt;&gt;();
        for (int i = 0; i &lt; inorder.length; i++) {
            pos.put(inorder[i], i);
        }

        return dfs(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1, pos);
    }

    // preorder[pl..pr] 和 inorder[il..ir] 表示同一棵子树
    private TreeNode dfs(int[] preorder, int pl, int pr, int[] inorder, int il, int ir, Map&lt;Integer, Integer&gt; pos) {
        if (pl &gt; pr) {
            return null;
        }

        // 前序遍历：第一个就是根
        int rootVal = preorder[pl];

        // 根在中序里的位置，把中序分成左子树和右子树
        int k = pos.get(rootVal);
        int leftSize = k - il;

        TreeNode root = new TreeNode(rootVal);

        // 左子树：前序紧跟着根的 leftSize 个元素
        root.left = dfs(preorder, pl + 1, pl + leftSize, inorder, il, k - 1, pos);

        // 右子树：剩下的部分
        root.right = dfs(preorder, pl + leftSize + 1, pr, inorder, k + 1, ir, pos);

        return root;
    }
}

题/快速记忆/LeetCode-108.content:
LeetCode-108 将有序数组转换为二叉搜索树（快速记忆）
题干
给你一个整数数组 nums，它已经按升序排列。
