    public List&lt;List&lt;Integer&gt;&gt; generate(int numRows) {
        return null;
    }
}
最优解（无注释）
import java.util.*;

class Solution {
    public List&lt;List&lt;Integer&gt;&gt; generate(int numRows) {
        List&lt;List&lt;Integer&gt;&gt; ans = new ArrayList&lt;&gt;();
        for (int r = 0; r &lt; numRows; r++) {
            List&lt;Integer&gt; row = new ArrayList&lt;&gt;(r + 1);
            for (int c = 0; c &lt;= r; c++) {
                if (c == 0 || c == r) {
                    row.add(1);
                } else {
                    row.add(ans.get(r - 1).get(c - 1) + ans.get(r - 1).get(c));
                }
            }
            ans.add(row);
        }
        return ans;
    }
}
最优解（有注释）
import java.util.*;

class Solution {
    public List&lt;List&lt;Integer&gt;&gt; generate(int numRows) {
        List&lt;List&lt;Integer&gt;&gt; ans = new ArrayList&lt;&gt;();

        for (int r = 0; r &lt; numRows; r++) {
            List&lt;Integer&gt; row = new ArrayList&lt;&gt;(r + 1);

            for (int c = 0; c &lt;= r; c++) {
                if (c == 0 || c == r) {
                    row.add(1);
                } else {
                    int a = ans.get(r - 1).get(c - 1);
                    int b = ans.get(r - 1).get(c);
                    row.add(a + b);
                }
            }

            ans.add(row);
        }

        return ans;
    }
}

题/快速记忆/LeetCode-121.content:
LeetCode-121 买卖股票的最佳时机（快速记忆）
题干
给你一个数组 prices，prices[i] 表示第 i 天股票的价格。
你只能选择某一天买入，并在未来的某一天卖出（买在前，卖在后），最多只做一次交易。
请你返回能获得的最大利润；如果不能赚钱，返回 0。
数据范围（记忆版）

1 ⇐ prices.length ⇐ 100000
0 ⇐ prices[i] ⇐ 10000

数据示例

prices = [7,1,5,3,6,4] → 5
prices = [7,6,4,3,1] → 0

Java 函数入参/出参框架
class Solution {
    public int maxProfit(int[] prices) {
        return 0;
    }
}
最优解（无注释）
class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = prices[0];
        int best = 0;

        for (int i = 1; i &lt; prices.length; i++) {
            best = Math.max(best, prices[i] - minPrice);
            minPrice = Math.min(minPrice, prices[i]);
        }

        return best;
    }
}
最优解（有注释）
class Solution {
    public int maxProfit(int[] prices) {
        // minPrice：到今天为止出现过的最低买入价
        int minPrice = prices[0];

        // best：到今天为止的最大利润
        int best = 0;

        for (int i = 1; i &lt; prices.length; i++) {
            // 今天卖出能赚多少：prices[i] - 之前最低价
            best = Math.max(best, prices[i] - minPrice);

            // 更新最低价（相当于考虑“今天是否更适合买入”）
            minPrice = Math.min(minPrice, prices[i]);
        }

        return best;
    }
}

题/快速记忆/LeetCode-124.content:
LeetCode-124 二叉树中的最大路径和（快速记忆）
题干
二叉树中的路径定义为：从任意节点出发，沿父子连接走到任意节点，路径中至少包含一个节点。
路径不一定经过根节点。
返回这棵树的最大路径和。
数据范围（记忆版）

节点数：1 ~ 3 * 10
节点值范围：-1000 ~ 1000

数据示例

root = [1,2,3] → 6
root = [-10,9,20,null,null,15,7] → 42

Java 函数入参/出参框架
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int maxPathSum(TreeNode root) {
        return 0;
    }
}
最优解（无注释）
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int maxPathSum(TreeNode root) {
        int[] ans = new int[] { Integer.MIN_VALUE };
        dfs(root, ans);
        return ans[0];
    }

    private int dfs(TreeNode node, int[] ans) {
        if (node == null) {
            return 0;
        }
        int left = Math.max(0, dfs(node.left, ans));
        int right = Math.max(0, dfs(node.right, ans));
        ans[0] = Math.max(ans[0], node.val + left + right);
        return node.val + Math.max(left, right);
    }
}
最优解（有注释）
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int maxPathSum(TreeNode root) {
        int[] ans = new int[] { Integer.MIN_VALUE };
        dfs(root, ans);
        return ans[0];
    }

    // 返回：从 node 出发，向下走（只能选一边）的最大路径和
    private int dfs(TreeNode node, int[] ans) {
        if (node == null) {
            return 0;
        }

        // 如果子树贡献为负，宁愿不选它（当作 0）
        int leftGain = Math.max(0, dfs(node.left, ans));
        int rightGain = Math.max(0, dfs(node.right, ans));

        // 以 node 为“拐点”的路径：左 + node + 右
        ans[0] = Math.max(ans[0], node.val + leftGain + rightGain);

        // 向父节点汇报时，只能选一边继续向上延伸
        return node.val + Math.max(leftGain, rightGain);
    }
}

题/快速记忆/LeetCode-128.content:
LeetCode-128 最长连续序列（快速记忆）
题干
给你一个未排序的整数数组 nums，请你找出数字连续（比如 4,5,6,7）的最长序列长度。
要求：时间复杂度尽量是 O(n)。
数据范围（记忆版）

0 ⇐ nums.length ⇐ 100000
-10^9 ⇐ nums[i] ⇐ 10

数据示例

nums = [100,4,200,1,3,2] → 4（1,2,3,4）
nums = [0,3,7,2,5,8,4,6,0,1] → 9（0..8）

Java 函数入参/出参框架
class Solution {
    public int longestConsecutive(int[] nums) {
        return 0;
    }
}
最优解（无注释）
import java.util.HashSet;
import java.util.Set;

class Solution {
    public int longestConsecutive(int[] nums) {
        Set&lt;Integer&gt; set = new HashSet&lt;&gt;();
        for (int x : nums) {
            set.add(x);
        }

        int best = 0;
        for (int x : set) {
            if (!set.contains(x - 1)) {
                int cur = x;
                int len = 1;
                while (set.contains(cur + 1)) {
                    cur++;
                    len++;
                }
                best = Math.max(best, len);
            }
        }

        return best;
    }
}
最优解（有注释）
import java.util.HashSet;
import java.util.Set;

class Solution {
    public int longestConsecutive(int[] nums) {
        Set&lt;Integer&gt; set = new HashSet&lt;&gt;();
        for (int x : nums) {
            set.add(x);
        }

        int best = 0;

        // 只从“序列起点”开始往右扩展，避免重复计算
        for (int x : set) {
            // 如果 x-1 不存在，说明 x 是一个连续序列的起点
            if (!set.contains(x - 1)) {
                int cur = x;
                int len = 1;

                while (set.contains(cur + 1)) {
                    cur++;
                    len++;
                }

                best = Math.max(best, len);
            }
        }

        return best;
    }
}

题/快速记忆/LeetCode-131.content:
LeetCode-131 分割回文串（快速记忆）
题干
给你一个字符串 s，把它分割成一些子串，使得每个子串都是回文串。
返回 s 所有可能的回文分割方案。
数据范围（记忆版）

1 &lt;= s.length &lt;= 16
s 由小写英文字母组成

数据示例

s = “aab” → [[“a”,“a”,“b”],[“aa”,“b”]]
s = “a” → “a”

Java 函数入参/出参框架
import java.util.*;

class Solution {
    public List&lt;List&lt;String&gt;&gt; partition(String s) {
        return null;
    }
}
最优解（无注释）
import java.util.*;

class Solution {
    public List&lt;List&lt;String&gt;&gt; partition(String s) {
        int n = s.length();
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i &gt;= 0; i--) {
            for (int j = i; j &lt; n; j++) {
                if (s.charAt(i) == s.charAt(j) &amp;&amp; (j - i &lt;= 2 || pal[i + 1][j - 1])) {
                    pal[i][j] = true;
                }
            }
        }

        List&lt;List&lt;String&gt;&gt; ans = new ArrayList&lt;&gt;();
        Deque&lt;String&gt; path = new ArrayDeque&lt;&gt;();
        dfs(s, 0, pal, path, ans);
        return ans;
    }

    private void dfs(String s, int start, boolean[][] pal, Deque&lt;String&gt; path, List&lt;List&lt;String&gt;&gt; ans) {
        if (start == s.length()) {
            ans.add(new ArrayList&lt;&gt;(path));
            return;
        }
        for (int end = start; end &lt; s.length(); end++) {
            if (!pal[start][end]) {
                continue;
            }
            path.addLast(s.substring(start, end + 1));
            dfs(s, end + 1, pal, path, ans);
            path.removeLast();
        }
    }
}
最优解（有注释）
import java.util.*;

class Solution {
    public List&lt;List&lt;String&gt;&gt; partition(String s) {
        int n = s.length();

        // pal[i][j] = s[i..j] 是否是回文
        boolean[][] pal = new boolean[n][n];
        for (int i = n - 1; i &gt;= 0; i--) {
            for (int j = i; j &lt; n; j++) {
                if (s.charAt(i) == s.charAt(j) &amp;&amp; (j - i &lt;= 2 || pal[i + 1][j - 1])) {
                    pal[i][j] = true;
                }
            }
        }

        List&lt;List&lt;String&gt;&gt; ans = new ArrayList&lt;&gt;();
        Deque&lt;String&gt; path = new ArrayDeque&lt;&gt;();
        dfs(s, 0, pal, path, ans);
        return ans;
    }

    private void dfs(String s, int start, boolean[][] pal, Deque&lt;String&gt; path, List&lt;List&lt;String&gt;&gt; ans) {
        if (start == s.length()) {
            ans.add(new ArrayList&lt;&gt;(path));
            return;
        }

        // 枚举“第一刀”切在哪里：start..end
        for (int end = start; end &lt; s.length(); end++) {
            if (!pal[start][end]) {
                continue; // 不是回文就不能作为一段
            }

            path.addLast(s.substring(start, end + 1));
            dfs(s, end + 1, pal, path, ans);
            path.removeLast(); // 回溯：撤销本次切分
        }
    }
}

题/快速记忆/LeetCode-136.content:
