class Node {
    int val;
    Node next;
    Node random;
    Node(int val) { this.val = val; }
}

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        Node cur = head;
        while (cur != null) {
            Node copy = new Node(cur.val);
            copy.next = cur.next;
            cur.next = copy;
            cur = copy.next;
        }

        cur = head;
        while (cur != null) {
            if (cur.random != null) {
                cur.next.random = cur.random.next;
            }
            cur = cur.next.next;
        }

        Node dummy = new Node(0);
        Node tail = dummy;
        cur = head;
        while (cur != null) {
            Node copy = cur.next;
            Node next = copy.next;
            tail.next = copy;
            tail = copy;
            cur.next = next;
            cur = next;
        }

        return dummy.next;
    }
}
最优解（有注释）
class Node {
    int val;
    Node next;
    Node random;
    Node(int val) { this.val = val; }
}

class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }

        // 1) 把复制节点插到原节点后面：A -&gt; A&#039; -&gt; B -&gt; B&#039; -&gt; ...
        Node cur = head;
        while (cur != null) {
            Node copy = new Node(cur.val);
            copy.next = cur.next;
            cur.next = copy;
            cur = copy.next;
        }

        // 2) 处理 random：原节点的 random 指向谁，复制节点的 random 就指向“那个人的复制节点”
        cur = head;
        while (cur != null) {
            if (cur.random != null) {
                cur.next.random = cur.random.next;
            }
            cur = cur.next.next;
        }

        // 3) 拆分：把交错的链表拆成“原链表”和“新链表”
        Node dummy = new Node(0);
        Node tail = dummy;
        cur = head;
        while (cur != null) {
            Node copy = cur.next;
            Node next = copy.next;

            tail.next = copy;
            tail = copy;

            cur.next = next; // 还原原链表
            cur = next;
        }

        return dummy.next;
    }
}

