    public LRUCache(int capacity) {
    }

    public int get(int key) {
        return 0;
    }

    public void put(int key, int value) {
    }
}
最优解（无注释）
import java.util.*;

class LRUCache {
    private static class Node {
        int key;
        int val;
        Node prev;
        Node next;
        Node(int key, int val) { this.key = key; this.val = val; }
    }

    private final int capacity;
    private final Map&lt;Integer, Node&gt; map;
    private final Node head;
    private final Node tail;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap&lt;&gt;();
        this.head = new Node(0, 0);
        this.tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) {
            return -1;
        }
        moveToFront(node);
        return node.val;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) {
            node.val = value;
            moveToFront(node);
            return;
        }

        if (map.size() == capacity) {
            Node lru = tail.prev;
            remove(lru);
            map.remove(lru.key);
        }

        Node fresh = new Node(key, value);
        addToFront(fresh);
        map.put(key, fresh);
    }

    private void moveToFront(Node node) {
        remove(node);
        addToFront(node);
    }

    private void addToFront(Node node) {
        Node a = head;
        Node b = head.next;
        node.prev = a;
        node.next = b;
        a.next = node;
        b.prev = node;
    }

    private void remove(Node node) {
        Node a = node.prev;
        Node b = node.next;
        a.next = b;
        b.prev = a;
        node.prev = null;
        node.next = null;
    }
}
最优解（有注释）
import java.util.*;

class LRUCache {
    private static class Node {
        int key;
        int val;
        Node prev;
        Node next;
        Node(int key, int val) { this.key = key; this.val = val; }
    }

    private final int capacity;
    private final Map&lt;Integer, Node&gt; map; // key -&gt; 节点，O(1) 找到节点
    private final Node head;              // 双向链表哑头
    private final Node tail;              // 双向链表哑尾

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap&lt;&gt;();

        // 双向链表：头部是“最近使用”，尾部是“最久未使用”
        this.head = new Node(0, 0);
        this.tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) {
            return -1;
        }

        // 被访问过，就变成“最近使用”
        moveToFront(node);
        return node.val;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) {
            node.val = value;
            moveToFront(node);
            return;
        }

        // 超容量：删掉最久未使用（尾部的前一个）
        if (map.size() == capacity) {
            Node lru = tail.prev;
            remove(lru);
            map.remove(lru.key);
        }

        Node fresh = new Node(key, value);
        addToFront(fresh);
        map.put(key, fresh);
    }

    private void moveToFront(Node node) {
        remove(node);
        addToFront(node);
    }

    private void addToFront(Node node) {
        Node a = head;
        Node b = head.next;
        node.prev = a;
        node.next = b;
        a.next = node;
        b.prev = node;
    }

    private void remove(Node node) {
        Node a = node.prev;
        Node b = node.next;
        a.next = b;
        b.prev = a;
        node.prev = null;
        node.next = null;
    }
}

