import java.util.*;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public List&lt;Integer&gt; rightSideView(TreeNode root) {
        List&lt;Integer&gt; ans = new ArrayList&lt;&gt;();
        if (root == null) {
            return ans;
        }
        Deque&lt;TreeNode&gt; q = new ArrayDeque&lt;&gt;();
        q.addLast(root);
        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i &lt; size; i++) {
                TreeNode node = q.removeFirst();
                if (i == size - 1) {
                    ans.add(node.val);
                }
                if (node.left != null) q.addLast(node.left);
                if (node.right != null) q.addLast(node.right);
            }
        }
        return ans;
    }
}
最优解（有注释）
import java.util.*;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public List&lt;Integer&gt; rightSideView(TreeNode root) {
        List&lt;Integer&gt; ans = new ArrayList&lt;&gt;();
        if (root == null) {
            return ans;
        }

        Deque&lt;TreeNode&gt; q = new ArrayDeque&lt;&gt;();
        q.addLast(root);

        // 层序遍历：每层最后一个节点，就是从右边看到的那个
        while (!q.isEmpty()) {
            int size = q.size();
            for (int i = 0; i &lt; size; i++) {
                TreeNode node = q.removeFirst();

                if (i == size - 1) {
                    ans.add(node.val);
                }

                if (node.left != null) q.addLast(node.left);
                if (node.right != null) q.addLast(node.right);
            }
        }

        return ans;
    }
}

