import java.util.PriorityQueue;

class Solution {
    public int findKthLargest(int[] nums, int k) {
        // 小顶堆，堆里最多放 k 个数
        // 保证堆顶是“当前第 k 大”
        PriorityQueue&lt;Integer&gt; minHeap = new PriorityQueue&lt;&gt;();

        for (int x : nums) {
            minHeap.offer(x);
            if (minHeap.size() &gt; k) {
                minHeap.poll();
            }
        }

        return minHeap.peek();
    }
}

