    public int[] maxSlidingWindow(int[] nums, int k) {
        return null;
    }
}
最优解（无注释）
import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] ans = new int[n - k + 1];
        Deque&lt;Integer&gt; dq = new ArrayDeque&lt;&gt;();

        for (int i = 0; i &lt; n; i++) {
            while (!dq.isEmpty() &amp;&amp; dq.peekFirst() &lt;= i - k) {
                dq.removeFirst();
            }
            while (!dq.isEmpty() &amp;&amp; nums[dq.peekLast()] &lt;= nums[i]) {
                dq.removeLast();
            }
            dq.addLast(i);
            if (i &gt;= k - 1) {
                ans[i - k + 1] = nums[dq.peekFirst()];
            }
        }

        return ans;
    }
}
最优解（有注释）
import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] ans = new int[n - k + 1];

        // 单调队列（递减）：队头永远是当前窗口最大值的下标
        Deque&lt;Integer&gt; dq = new ArrayDeque&lt;&gt;();

        for (int i = 0; i &lt; n; i++) {
            // 1) 把窗口外的下标弹掉
            while (!dq.isEmpty() &amp;&amp; dq.peekFirst() &lt;= i - k) {
                dq.removeFirst();
            }

            // 2) 保持队列递减：新元素更大就把尾部小的都弹掉
            while (!dq.isEmpty() &amp;&amp; nums[dq.peekLast()] &lt;= nums[i]) {
                dq.removeLast();
            }

            dq.addLast(i);

            // 3) 从第一个完整窗口开始收集答案
            if (i &gt;= k - 1) {
                ans[i - k + 1] = nums[dq.peekFirst()];
            }
        }

        return ans;
    }
}

