class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length;
        int n = matrix[0].length;
        int r = 0;
        int c = n - 1;
        while (r &lt; m &amp;&amp; c &gt;= 0) {
            int x = matrix[r][c];
            if (x == target) return true;
            if (x &gt; target) c--;
            else r++;
        }
