public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public boolean isValidBST(TreeNode root) {
        return dfs(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean dfs(TreeNode node, long low, long high) {
        if (node == null) {
            return true;
        }
        if (node.val &lt;= low || node.val &gt;= high) {
            return false;
        }
        return dfs(node.left, low, node.val) &amp;&amp; dfs(node.right, node.val, high);
    }
}
最优解（有注释）
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public boolean isValidBST(TreeNode root) {
        // 用“上下界”约束每个节点允许的取值范围
        return dfs(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean dfs(TreeNode node, long low, long high) {
        if (node == null) {
            return true;
        }

        // 注意是严格小于/严格大于（BST 不允许相等）
        if (node.val &lt;= low || node.val &gt;= high) {
            return false;
        }

        // 左子树：上界变成当前节点值
        // 右子树：下界变成当前节点值
        return dfs(node.left, low, node.val) &amp;&amp; dfs(node.right, node.val, high);
    }
}

题/快速记忆/LeetCode-994.content:
LeetCode-994 腐烂的橘子（快速记忆）
题干
在一个 m x n 的网格中：

0 表示空格
1 表示新鲜橘子
2 表示腐烂橘子
每分钟，腐烂橘子会让上下左右相邻的新鲜橘子腐烂。
返回直到没有新鲜橘子为止所需的最小分钟数；如果不可能，返回 -1。

数据范围（记忆版）

1 &lt;= m, n &lt;= 10
grid[i][j] 是 0/1/2

数据示例

grid = [[2,1,1],[1,1,0],[0,1,1]] → 4
grid = [[2,1,1],[0,1,1],[1,0,1]] → -1
grid = 0,2 → 0

Java 函数入参/出参框架
class Solution {
    public int orangesRotting(int[][] grid) {
        return 0;
    }
}
最优解（无注释）
import java.util.*;

class Solution {
    public int orangesRotting(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        Deque&lt;int[]&gt; q = new ArrayDeque&lt;&gt;();
        int fresh = 0;

        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == 2) q.addLast(new int[] { i, j });
                else if (grid[i][j] == 1) fresh++;
            }
        }

        if (fresh == 0) return 0;

        int minutes = 0;
        int[][] dirs = { {1,0},{-1,0},{0,1},{0,-1} };

        while (!q.isEmpty()) {
            int size = q.size();
            boolean changed = false;

            for (int t = 0; t &lt; size; t++) {
                int[] cur = q.removeFirst();
                for (int[] d : dirs) {
                    int ni = cur[0] + d[0];
                    int nj = cur[1] + d[1];
                    if (ni &lt; 0 || ni &gt;= m || nj &lt; 0 || nj &gt;= n) continue;
                    if (grid[ni][nj] != 1) continue;
                    grid[ni][nj] = 2;
                    fresh--;
                    q.addLast(new int[] { ni, nj });
                    changed = true;
                }
            }

            if (changed) minutes++;
        }

        return fresh == 0 ? minutes : -1;
    }
}
最优解（有注释）
import java.util.*;

class Solution {
    public int orangesRotting(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        Deque&lt;int[]&gt; q = new ArrayDeque&lt;&gt;();
        int fresh = 0;

        // 多源 BFS：把所有腐烂橘子都当成起点
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                if (grid[i][j] == 2) {
                    q.addLast(new int[] { i, j });
                } else if (grid[i][j] == 1) {
                    fresh++;
                }
            }
        }

        if (fresh == 0) {
            return 0;
        }

        int minutes = 0;
        int[][] dirs = { {1,0},{-1,0},{0,1},{0,-1} };

        // 每一轮循环代表“一分钟”
        while (!q.isEmpty()) {
            int size = q.size();
            boolean changed = false;

            for (int t = 0; t &lt; size; t++) {
                int[] cur = q.removeFirst();

                for (int[] d : dirs) {
                    int ni = cur[0] + d[0];
                    int nj = cur[1] + d[1];

                    if (ni &lt; 0 || ni &gt;= m || nj &lt; 0 || nj &gt;= n) {
                        continue;
                    }
                    if (grid[ni][nj] != 1) {
                        continue;
                    }

                    grid[ni][nj] = 2;
                    fresh--;
                    q.addLast(new int[] { ni, nj });
                    changed = true;
                }
            }

            if (changed) {
                minutes++;
            }
        }

        return fresh == 0 ? minutes : -1;
    }
}

